function periodBounds(h,date=todayISO()){
  const raw=String(date||todayISO()),parsed=new Date(`${raw}T12:00:00`),d=Number.isNaN(parsed.getTime())?new Date(`${todayISO()}T12:00:00`):parsed,period=h.period||'week';let start=new Date(d),end=new Date(d);
  if(period==='week'){const offset=(d.getDay()+6)%7;start.setDate(d.getDate()-offset);end=new Date(start);end.setDate(start.getDate()+6)}
  else if(period==='month'){start=new Date(d.getFullYear(),d.getMonth(),1,12);end=new Date(d.getFullYear(),d.getMonth()+1,0,12)}
  return{start:localDateISO(start),end:localDateISO(end),key:period==='month'?localDateISO(d).slice(0,7):period==='week'?localDateISO(start):localDateISO(d)};
}

