function showModal(content,wide=false){document.body.classList.add('modal-open');modalRoot.innerHTML=`<div class="modal-layer" data-close-modal><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" data-modal-content>${content}</section></div>`;setTimeout(()=>modalRoot.querySelector('input,textarea,select,button:not([data-close-modal])')?.focus(),0)}
function closeModal(){modalRoot.innerHTML='';document.body.classList.remove('modal-open')}
function showDrawer(){const inbox=state.inbox.filter(i=>i.status==='open').length;drawerRoot.innerHTML=`<div class="drawer-layer" data-close-drawer><aside class="drawer" data-drawer><div class="drawer-head"><div><span class="eyebrow">QUESTLINE</span><h2>Menu</h2></div><button class="icon-button" data-close-drawer>×</button></div><div class="drawer-list">${SYSTEM_NAV.map(([view,label,icon])=>`<button class="drawer-item" data-view="${view}">${img(icon,'')}<span><strong>${label}</strong>${view==='notes'?'<small>Ideas, evidence, and standalone notes</small>':''}</span>${view==='notes'&&inbox?`<b class="nav-count">${inbox}</b>`:''}</button>`).join('')}<button class="drawer-item" data-open-inbox>${img('object_inbox','')}<span><strong>Inbox</strong><small>Uncategorized captures</small></span>${inbox?`<b class="nav-count">${inbox}</b>`:''}</button></div><div class="sidebar-footer"><span>Installed version</span><strong>Questline v${VERSION}</strong></div></aside></div>`}
function closeDrawer(){drawerRoot.innerHTML=''}
function tag(text,icon='',kind=''){return `<span class="tag ${kind}">${icon?img(icon,''):''}${esc(text)}</span>`}
function categoryTag(category){const c=CATEGORIES[category]||CATEGORIES.Resolve;return tag(c.label,c.icon,c.class)}
function areaTag(area){return tag(area,AREA_ICONS[area]||'realm_professional')}
function versionText(){document.title=`Questline v${VERSION}`;$$('[data-version]').forEach(e=>e.textContent=`v${VERSION}`);$$('[data-version-long]').forEach(e=>e.textContent=`Questline v${VERSION}`)}

function renderNavigation(){
  const inbox=state.inbox.filter(i=>i.status==='open').length;
  const groups=[['Navigate',MAIN_NAV],['System',SYSTEM_NAV]];
  $('#desktop-nav').innerHTML=groups.map(([label,items])=>`<section class="nav-group"><h2>${label}</h2>${items.map(([view,text,icon])=>`<button class="nav-button ${state.ui.view===view?'active':''}" data-view="${view}">${img(icon,'')}<span>${text}</span>${view==='capture'&&inbox?`<b class="nav-count">${inbox}</b>`:''}</button>`).join('')}</section>`).join('');
  $('#mobile-nav').innerHTML=MAIN_NAV.map(([view,text,icon],i)=>i===2?'<span class="capture-slot"></span>':`<button class="mobile-nav-button ${state.ui.view===view?'active':''}" data-view="${view}">${img(icon,'')}<span>${text}</span></button>`).join('');
}
function updateHeader(){const v=VIEWS[state.ui.view]||VIEWS.today;$('#page-eyebrow').textContent=v.eyebrow;$('#page-title').textContent=v.title;$('#page-icon').src=A[v.icon]||A.scene_today;versionText()}
function setView(view,opts={}){if(!VIEWS[view])view='today';state.ui.view=view;if(opts.returnContext)state.ui.returnContext=opts.returnContext;if(view!=='questbook'&&!opts.keepQuest)state.ui.selectedQuestId=null;save();render();window.scrollTo({top:0,behavior:'smooth'});$('#page').focus({preventScroll:true})}
function render(){renderNavigation();updateHeader();const fn={today:renderToday,tasks:renderTasks,capture:renderCapture,questbook:renderQuestbook,review:renderReview,calendar:renderCalendar,notes:renderNotes,sync:renderSync,settings:renderSettings}[state.ui.view]||renderToday;fn();bindDragAndDrop()}
function hero({title,subtitle,scene='scene_today',meta=[]}){return `<section class="hero-compact"><div class="hero-copy"><span class="eyebrow">QUESTLINE</span><h2>${esc(title)}</h2><p>${esc(subtitle)}</p>${meta.length?`<div class="hero-meta">${meta.map(([k,v])=>`<span><strong>${esc(k)}</strong> ${esc(v)}</span>`).join('')}</div>`:''}</div>${img(scene,'','hero-art')}</section>`}
function panelHead(title,subtitle='',icon='',actions=''){return `<div class="panel-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${actions||icon?`<div class="panel-actions">${actions}${icon?img(icon,'','panel-icon'):''}</div>`:''}</div>`}

function activityCategory(activity){return activity.category||'Resolve'}
function activityQuest(activity){return activity.questId?questById(activity.questId):null}
function activityCompleted(activity){if(activity.kind==='task')return activity.task.status==='Completed';if(activity.kind==='habit')return !!activity.occurrence.completedAt;return false}
function activityProgress(activity){if(activity.kind==='task')return Number(activity.task.progress||0);if(activity.kind==='habit'){const p=periodProgress(activity.habit,activity.date);return p.percent}return 0}
function activityMeta(activity){
  const bits=[];const category=activityCategory(activity),q=activityQuest(activity);
  bits.push(categoryTag(category));bits.push(areaTag(activity.area));
  if(q)bits.push(`<button class="quest-link" data-open-quest="${q.id}" data-highlight-activity="${esc(activity.key)}">${esc(q.title)} ›</button>`);
  return bits.join('');
}
function activitySubline(activity){
  const parts=[];
  if(activity.kind==='task'){
    const t=activity.task;if(t.startTime)parts.push(`${fmtTime(t.startTime)}${t.endTime?`–${fmtTime(t.endTime)}`:''}`);else if(t.estimateMinutes)parts.push(formatMinutes(t.estimateMinutes));
    if(t.plannedDate)parts.push(`Planned ${fmtDate(t.plannedDate)}`);if(t.dueDate)parts.push(`Due ${fmtDate(t.dueDate)}`);if(t.progress>0&&t.progress<100)parts.push(`${t.progress}%`);
    const n=taskNeglect(t);if(n.reasons.length)parts.push(n.reasons[0]);
  }else if(activity.kind==='habit'){
    const p=periodProgress(activity.habit,activity.date);parts.push(`${p.actual}/${p.target} ${activity.habit.unit}`);parts.push(`${p.percent}% this ${activity.habit.period}`);parts.push(`Period ends ${fmtDate(p.end)}`);
  }else if(activity.kind==='calendar'){
    const e=activity.calendar;if(e.startTime)parts.push(`${fmtTime(e.startTime)}${e.endTime?`–${fmtTime(e.endTime)}`:''}`);parts.push(e.source||'Calendar');
  }
  return parts.join(' · ');
}
function activityRow(activity,{compact=false,draggable=true}={}){
  const category=activityCategory(activity),complete=activityCompleted(activity),progress=activityProgress(activity),neg=activity.kind==='task'?taskNeglect(activity.task):activity.kind==='habit'?habitNeglect(activity.habit,activity.date):{level:'none'},top=!!activity.topPriority;
  let control='';
  if(activity.kind==='calendar')control=`<span class="activity-check habit">◷</span>`;
  else if(activity.kind==='habit'){
    const p=periodProgress(activity.habit,activity.date);control=`<button class="activity-check habit ${complete?'checked':''}" data-complete-habit="${activity.habit.id}" data-occurrence="${activity.occurrence.id}" aria-label="${complete?'Undo habit occurrence':'Complete habit occurrence'}">${complete?'✓':activity.habit.measurement==='quantity'?`${p.actual}/${p.target}`:'+'}</button>`;
  }else control=`<button class="activity-check ${complete?'checked':progress>0?'progress':''}" style="--progress:${progress}%" data-complete-task="${activity.task.id}" aria-label="${complete?'Mark incomplete':'Mark complete'}">${complete?'✓':progress>0?`${progress}%`:''}</button>`;
  const starKey=activity.key,star=`<button class="priority-star ${top?'active':''}" data-top-priority="${esc(starKey)}" data-date="${activity.date||todayISO()}" aria-label="${top?'Remove top priority':'Set top priority'}">${top?'★':'☆'}</button>`;
  const actions=activity.kind==='calendar'?'':`<div class="activity-actions">${activity.kind==='task'?`<button class="button tiny ghost" data-progress-task="${activity.task.id}"><span class="quick-label">Progress</span><span>↗</span></button>`:`<button class="button tiny ghost" data-update-habit="${activity.habit.id}"><span class="quick-label">Update</span><span>↗</span></button>`}<button class="button tiny ghost" data-move-activity="${esc(activity.key)}" data-date="${activity.date}"><span class="quick-label">Move</span><span>↪</span></button><button class="button tiny ghost icon-only" data-open-activity="${esc(activity.key)}" aria-label="More">⋮</button></div>`;
  return `<article class="activity-row category-${categoryClass(category)} ${complete?'completed':''} ${top?'top-priority':''} ${neg.level!=='none'?'neglected':''}" data-activity-key="${esc(activity.key)}" ${draggable&&activity.kind==='task'?`draggable="true" data-task-drag="${activity.task.id}"`:''}>
    ${control}<div class="activity-content"><div class="activity-title-line"><span class="activity-title">${esc(activity.title)}</span>${star}</div><div class="activity-meta">${activityMeta(activity)}</div><div class="activity-subline">${esc(activitySubline(activity))}</div>${progress>0&&progress<100?`<div class="mini-progress"><span style="width:${Math.min(100,progress)}%"></span></div>`:''}</div>${actions}</article>`;
}
function sortActivities(list,date){
  const mode=state.ui.todaySort||'manual';return [...list].sort((a,b)=>{
    if(a.topPriority!==b.topPriority)return a.topPriority?-1:1;
    if(mode==='start')return String(a.startTime||'99:99').localeCompare(String(b.startTime||'99:99'));
    if(mode==='due')return String(a.dueDate||'9999-12-31').localeCompare(String(b.dueDate||'9999-12-31'));
    if(mode==='quest')return String(activityQuest(a)?.title||'ZZZ').localeCompare(String(activityQuest(b)?.title||'ZZZ'));
    if(mode==='recent')return String(b.task?.updatedAt||b.habit?.updatedAt||'').localeCompare(String(a.task?.updatedAt||a.habit?.updatedAt||''));
    const ao=a.task?.plannedOrder||a.occurrence?.order||99,bo=b.task?.plannedOrder||b.occurrence?.order||99;return ao-bo;
  })
}

function planningDates(){const start=state.ui.plannerStart||todayISO(),days=Number(state.settings.planningHorizonDays||7);return Array.from({length:days},(_,i)=>addDays(start,i))}
function dateSection(date,activities,{title=null,subtitle='',today=false}={}){const ordered=sortActivities(activities,date),mins=sum(ordered.map(a=>a.estimateMinutes||0));return `<section class="panel date-section ${today?'today-section':''}" data-date-section="${date}"><div class="date-section-head"><div><span class="eyebrow">${today?'TODAY':'PLANNED'}</span><h2>${esc(title||fmtDay(date))}</h2><p>${esc(subtitle||`${ordered.length} activit${ordered.length===1?'y':'ies'} · ${formatMinutes(mins)}`)}</p></div><div class="date-stats"><span>${ordered.length}</span><button class="button tiny primary" data-add-to-date="${date}">+ Add</button></div></div><div class="activity-list">${ordered.length?ordered.map(a=>activityRow(a)).join(''):'<div class="empty compact">Nothing planned. Add a Quest step, Resolve task, Habit opportunity, or Renew/Fun activity.</div>'}</div></section>`}
function overdueSection(){const list=overdueTasks().map(taskActivity);if(!list.length)return'';return `<section class="panel"><div class="panel-head"><div><span class="eyebrow" style="color:#9e2f29">OVERDUE · ${list.length}</span><h2>Replan before building today</h2><p>These final commitments are late. Complete, break down, or choose a realistic new plan.</p></div>${img('risk_critical','','panel-icon')}</div><div class="activity-list">${list.map(a=>activityRow(a,{draggable:false})).join('')}</div></section>`}
function missedPlanSection(){const list=missedPlanTasks().filter(t=>!overdueTasks().some(x=>x.id===t.id)).map(taskActivity);if(!list.length)return'';return `<section class="panel"><div class="panel-head"><div><span class="eyebrow" style="color:#876012">MISSED PLAN · ${list.length}</span><h2>Previously planned, not completed</h2><p>The due date may still be safe, but the execution plan needs an explicit decision.</p></div>${img('clock_repeated','','panel-icon')}</div><div class="activity-list">${list.map(a=>activityRow(a,{draggable:false})).join('')}</div></section>`}
function renderDueLens(){
  const groups=['Overdue','Due today','Due tomorrow','Due this week','Later','No due date'];
  const tasks=openTasks().sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999')));
  return `<div class="stack">${groups.map(g=>{const list=tasks.filter(t=>taskDueGroup(t)===g).map(taskActivity);if(!list.length)return'';return `<section class="panel date-section"><div class="date-section-head"><div><span class="eyebrow">DEADLINES</span><h2>${g}</h2><p>${list.length} task${list.length===1?'':'s'} · planned dates remain visible</p></div><span class="date-stats"><span>${list.length}</span></span></div><div class="activity-list">${list.map(a=>activityRow(a,{draggable:false})).join('')}</div></section>`}).join('')}</div>`
}
function renderToday(){
  ensureHabitPeriods();const dates=planningDates(),lens=state.ui.todayLens||'planned';const overdue=overdueTasks().length,missed=missedPlanTasks().filter(t=>!overdueTasks().some(x=>x.id===t.id)).length,plannedCount=dates.reduce((n,d)=>n+activitiesForDate(d).length,0);
  root.innerHTML=`${hero({title:'Daily Activity Planner',subtitle:'Replan overdue work first, then combine Quest steps, Resolve tasks, Habits, calendar commitments, and Renew/Fun by date.',scene:'scene_today',meta:[['Horizon',`${state.settings.planningHorizonDays} days`],['Planned',String(plannedCount)],['Needs decision',String(overdue+missed)],['Version',`v${VERSION}`]]})}
  <div class="toolbar"><div class="toolbar-group"><div class="segmented"><button class="${lens==='planned'?'active':''}" data-today-lens="planned">Planned Date</button><button class="${lens==='due'?'active':''}" data-today-lens="due">Due Date</button></div><select class="select-control" id="today-sort" aria-label="Sort activities"><option value="manual" ${state.ui.todaySort==='manual'?'selected':''}>Manual plan order</option><option value="start" ${state.ui.todaySort==='start'?'selected':''}>Start time</option><option value="due" ${state.ui.todaySort==='due'?'selected':''}>Due date</option><option value="quest" ${state.ui.todaySort==='quest'?'selected':''}>Quest</option><option value="recent" ${state.ui.todaySort==='recent'?'selected':''}>Recently updated</option></select></div><div class="date-nav"><button class="date-chip" data-shift-horizon="-${state.settings.planningHorizonDays}">‹</button><button class="date-chip" data-reset-horizon>Today</button><button class="date-chip" data-shift-horizon="${state.settings.planningHorizonDays}">›</button><button class="date-chip active" data-change-horizon>${state.settings.planningHorizonDays} days</button></div></div>
  <div class="toolbar"><div class="toolbar-group"><button class="button primary" data-plan-next>${img('character_plan','')}Plan Next Days</button><button class="button ghost" data-add-to-date="${todayISO()}">+ Add to today</button></div><span class="muted">Top Priority ★ stays inside the date sequence.</span></div>
  ${lens==='due'?renderDueLens():`<div class="stack">${overdueSection()}${missedPlanSection()}${dates.map(d=>dateSection(d,activitiesForDate(d),{today:d===todayISO()})).join('')}</div>`}`;
}

function renderTasks(){
  const tab=state.ui.tasksTab||'Resolve';root.innerHTML=`${hero({title:'Tasks',subtitle:'Review the same actionable work by source and mental state. Resolve is the default; Quest tasks retain their Goal/Project or Exploration track.',scene:'scene_priority',meta:[['Open tasks',String(openTasks().length)],['Resolve',String(openTasks().filter(t=>taskCategory(t)==='Resolve').length)],['Quest tasks',String(openTasks().filter(t=>t.questId).length)],['Neglected',String(openTasks().filter(t=>taskNeglect(t).score>=2).length)]]})}<div class="tab-strip">${['Resolve','Quest Tasks','Habit Activities','Renew/Fun','Unscheduled','Matrix'].map(x=>`<button class="tab-button ${tab===x?'active':''}" data-tasks-tab="${x}">${x}</button>`).join('')}</div><div id="tasks-content">${renderTasksTab(tab)}</div>`;
}
function renderTasksTab(tab){if(tab==='Resolve')return renderResolveTasks();if(tab==='Quest Tasks')return renderQuestTasks();if(tab==='Habit Activities')return renderHabitActivities();if(tab==='Renew/Fun')return renderRenewTasks();if(tab==='Unscheduled')return renderUnscheduled();return renderMatrix()}
function renderResolveTasks(){
  const list=openTasks().filter(t=>taskCategory(t)==='Resolve'),stages={
    'Do Now':list.filter(t=>t.status!=='Waiting'&&!t.startTime&&(t.estimateMinutes||0)<=15),
    'Schedule':list.filter(t=>t.status!=='Waiting'&&((t.estimateMinutes||0)>15||t.startTime)),
    'Waiting':list.filter(t=>t.status==='Waiting'),
    'Follow Up':list.filter(t=>t.followUpDate),
    'Needs Definition':list.filter(t=>!t.plannedDate&&!t.dueDate&&!(t.estimateMinutes>0))
  };
  return `<section class="panel">${panelHead('Resolve · Close Loops','Standalone tasks that need to be scheduled, followed up, or completed. Completing a step can still create a next step.','mode_resolve','<button class="button primary small" data-new-task data-standalone="Resolve">+ Resolve task</button>')}<div class="resolve-lanes">${Object.entries(stages).map(([name,items])=>`<section class="lane" data-resolve-lane="${name}"><h3>${name}<span>${items.length}</span></h3><div class="activity-list">${items.length?items.map(t=>activityRow(taskActivity(t),{compact:true})).join(''):'<div class="empty compact">None</div>'}</div></section>`).join('')}</div></section>`
}
function renderQuestTasks(){
  const filter=state.ui.questTaskTrack||'All',area=state.ui.taskArea||'All';let list=openTasks().filter(t=>t.questId);if(filter==='Goal/Project')list=list.filter(t=>t.track!=='exploration');if(filter==='Exploration')list=list.filter(t=>t.track==='exploration');if(area!=='All')list=list.filter(t=>t.area===area);
  return `<section class="panel">${panelHead('Quest Tasks','Concrete Goal/Project and Exploration steps across every active Quest.','object_goal','<button class="button primary small" data-open-questbook>Open Questbook</button>')}<div class="toolbar"><div class="subfilters">${['All','Goal/Project','Exploration'].map(x=>`<button class="chip ${filter===x?'active':''}" data-quest-task-filter="${x}">${x}</button>`).join('')}</div><select class="select-control" id="task-area-filter"><option>All</option>${AREAS.map(a=>`<option ${area===a?'selected':''}>${a}</option>`).join('')}</select></div><div class="activity-list">${list.length?list.sort((a,b)=>String(a.plannedDate||'9999').localeCompare(String(b.plannedDate||'9999'))).map(t=>activityRow(taskActivity(t))).join(''):'<div class="empty">No Quest tasks match this view.</div>'}</div></section>`
}
function renderHabitActivities(){
  ensureHabitPeriods();const date=todayISO();const cards=activeHabits().map(h=>{const p=periodProgress(h,date),n=habitNeglect(h,date);return `<article class="habit-card">${img(h.direction==='Avoid'?'habit_avoid':h.direction==='Limit'?'habit_limit':'habit_build','')}<div><h3>${esc(h.title)}</h3><p>${esc(h.area)}${h.questId?` · ${esc(questById(h.questId)?.title||'Quest')}`:''}</p><div class="habit-meter"><span style="width:${Math.min(100,p.percent)}%"></span></div><div class="habit-counters"><span>${p.actual}/${p.target} ${esc(h.unit)}</span><span>${p.percent}%</span><span>Ends ${fmtDate(p.end)}</span>${n.reasons[0]?`<span style="color:#8a312a">${esc(n.reasons[0])}</span>`:''}</div></div><div><button class="button tiny primary" data-update-habit="${h.id}">Update</button><button class="button tiny ghost" data-open-habit="${h.id}">Open</button></div></article>`});return `<section class="panel">${panelHead('Habit Activities','Period targets that can be scheduled alongside tasks. Full definitions live in Questbook → Habits.','object_habit','<button class="button primary small" data-open-habits>Open Habits</button>')}<div class="habit-list">${cards.join('')||'<div class="empty">No active Habits.</div>'}</div></section>`
}
function renderRenewTasks(){const list=openTasks().filter(t=>taskCategory(t)==='Renew/Fun');return `<section class="panel">${panelHead('Renew/Fun','Intentional rest, play, connection, and enjoyment.','mode_renew','<button class="button primary small" data-new-task data-standalone="Renew/Fun">+ Add activity</button>')}<div class="activity-list">${list.length?list.map(t=>activityRow(taskActivity(t))).join(''):'<div class="empty">No Renew/Fun activities yet.</div>'}</div></section>`}
function renderUnscheduled(){const list=openTasks().filter(t=>!t.plannedDate);return `<section class="panel">${panelHead('Unscheduled Tasks','Valid work with no planned date. Bring forward what is due, important, or a Quest Next Move.','clock_current','<button class="button primary small" data-plan-next>Plan Next Days</button>')}<div class="activity-list">${list.length?list.map(t=>activityRow(taskActivity(t))).join(''):'<div class="empty">Every open task has a planned date.</div>'}</div></section>`}
function renderMatrix(){
  const selected=state.ui.matrixCell||'High-High';const levels=['Low','Medium','High'];const cells=[];for(const imp of ['High','Medium','Low'])for(const urg of levels){const key=`${imp}-${urg}`,meta=priorityState({importance:imp,urgency:urg}),items=openTasks().filter(t=>t.importance===imp&&t.urgency===urg);cells.push({key,imp,urg,meta,items})}
  return `<section class="panel">${panelHead('Importance × Urgency Matrix','Desktop: drag tasks between cells. Mobile: select a cell and use Move. Scheduling remains a separate action.','priority_plan')}<div class="matrix"><div class="matrix-axis">IMPORTANCE ↓<br>URGENCY →</div>${levels.map(x=>`<div class="matrix-axis">${x}</div>`).join('')}${['High','Medium','Low'].map(imp=>`<div class="matrix-axis">${imp}</div>${cells.filter(c=>c.imp===imp).map(c=>`<section class="matrix-cell" data-matrix-importance="${c.imp}" data-matrix-urgency="${c.urg}"><h3>${img(c.meta[1],'')}${c.meta[0]} <span>${c.items.length}</span></h3>${c.items.map(t=>`<div class="matrix-item" draggable="true" data-task-drag="${t.id}">${img(categoryIcon(taskCategory(t)),'')}<span>${esc(t.title)}</span></div>`).join('')}</section>`).join('')}`).join('')}</div><div class="matrix-mobile"><div class="grid three">${cells.map(c=>`<button class="chip ${selected===c.key?'active':''}" data-matrix-cell="${c.key}">${c.meta[0]} · ${c.items.length}</button>`).join('')}</div><div class="activity-list" style="margin-top:10px">${cells.find(c=>c.key===selected)?.items.map(t=>activityRow(taskActivity(t),{draggable:false})).join('')||'<div class="empty">No tasks in this cell.</div>'}</div></div></section>`
}

function renderQuestbook(){
  if(state.ui.selectedQuestId){renderQuestDetail(state.ui.selectedQuestId);return}
  const tab=state.ui.questbookTab||'quests';root.innerHTML=`${hero({title:'Questbook',subtitle:'Quests hold outcomes, exploration, ideas, decisions, tasks, and supporting Habits. Habits have their own planning space.',scene:'scene_discovery',meta:[['Active Quests',String(activeQuests().filter(q=>!['Completed','Stopped'].includes(q.status)).length)],['Habits',String(activeHabits().length)],['Top Quest',activeQuests().find(q=>q.topQuest)?.title||'None'],['Inbox',String(state.inbox.filter(i=>i.status==='open').length)]]})}<div class="tab-strip">${['quests','habits','archive'].map(x=>`<button class="tab-button ${tab===x?'active':''}" data-questbook-tab="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div>${tab==='quests'?renderQuestList():tab==='habits'?renderHabitWorkspace():renderQuestArchive()}`
}
function renderQuestList(){
  const filter=state.ui.questFilter||'All',sort=state.ui.questSort||'manual';let list=activeQuests();if(filter==='Active')list=list.filter(q=>['To Start','In Progress'].includes(q.status));else if(filter!=='All')list=list.filter(q=>q.status===filter);
  list.sort((a,b)=>{if(a.topQuest!==b.topQuest)return a.topQuest?-1:1;if(sort==='status')return a.status.localeCompare(b.status);if(sort==='target')return String(a.outcome.targetDate||'9999').localeCompare(String(b.outcome.targetDate||'9999'));if(sort==='progress')return (b.outcome.progress||0)-(a.outcome.progress||0);if(sort==='recent')return String(b.updatedAt).localeCompare(String(a.updatedAt));return(a.manualOrder||99)-(b.manualOrder||99)});
  return `<section class="panel">${panelHead('Quests','Compare Quests, choose a Top Quest, and dive directly into their plan and exploration.','object_goal','<button class="button primary small" data-new-quest>+ New Quest</button>')}<div class="toolbar"><div class="subfilters">${['All','Active','To Start','In Progress','Paused','Completed','Stopped'].map(x=>`<button class="chip ${filter===x?'active':''}" data-quest-filter="${x}">${x}</button>`).join('')}</div><select class="select-control" id="quest-sort"><option value="manual" ${sort==='manual'?'selected':''}>Manual order</option><option value="status" ${sort==='status'?'selected':''}>Status</option><option value="target" ${sort==='target'?'selected':''}>Target date</option><option value="progress" ${sort==='progress'?'selected':''}>Progress</option><option value="recent" ${sort==='recent'?'selected':''}>Recently updated</option></select></div><div class="quest-list">${list.length?list.map(questRow).join(''):'<div class="empty">No Quests match this filter.</div>'}</div></section>`
}
function questRow(q){const known=questKnown(q),explore=questExplorationMetrics(q),label=questLabel(q),next=taskById(q.nextMoveTaskId),neg=questNeglect(q);return `<article class="quest-row" draggable="true" data-quest-drag="${q.id}">${img(label==='Exploration'?'scene_discovery':'scene_goal','')}<div><div style="display:flex;align-items:center;gap:7px"><h3>${esc(q.title)}</h3><span class="quest-type ${label==='Combined'?'combined':label==='Exploration'?'exploration':'goal'}">${label}</span></div><p>${esc(q.status)} · ${esc(q.area)}${q.outcome.targetDate?` · Target ${fmtDate(q.outcome.targetDate)}`:''}</p><div class="quest-stats">${q.outcome.enabled?tag(`${q.outcome.progress}% outcome`,'goal_progress','quest'):''}${tag(`${known.done}/${known.total} tasks`,'object_action')}${q.exploration.enabled?tag(`${explore.answered}/${explore.questions} questions`,'discovery_question','explore'):''}${neg.reasons[0]?tag('Needs attention','risk_at_risk','risk'):''}</div>${next?`<p><strong>Next:</strong> ${esc(next.title)}${next.plannedDate?` · ${fmtDate(next.plannedDate)}`:''}</p>`:'<p><strong>Next:</strong> Needs a Next Move</p>'}</div><div class="row-tail"><button class="quest-top ${q.topQuest?'active':''}" data-top-quest="${q.id}" aria-label="${q.topQuest?'Remove Top Quest':'Set Top Quest'}">${q.topQuest?'★':'☆'}</button><button class="button tiny primary" data-open-quest="${q.id}">Open</button></div></article>`}
function renderQuestDetail(id){
  const q=questById(id);if(!q){state.ui.selectedQuestId=null;save();renderQuestbook();return}const tab=state.ui.questTab||'overview',label=questLabel(q),known=questKnown(q),explore=questExplorationMetrics(q),back=state.ui.returnContext?.view||'questbook';
  root.innerHTML=`<section class="quest-header"><div class="quest-copy"><span class="eyebrow">${esc(label.toUpperCase())}</span><h2>${esc(q.title)}</h2><p>${esc(q.status)} · ${esc(q.area)} · Outcome ${q.outcome.enabled?`${q.outcome.progress}%`:'not defined'} · Known tasks ${known.done}/${known.total}${q.exploration.enabled?` · Exploration ${explore.done}/${explore.tasks} tasks`:''}</p><div class="quest-header-actions"><button class="button small ghost" data-back-from-quest>← Back</button><button class="button small ${q.topQuest?'warning':'ghost'}" data-top-quest="${q.id}">${q.topQuest?'★ Top Quest':'☆ Set Top Quest'}</button><button class="button small primary" data-add-quest-task="${q.id}" data-track="${tab==='explore'?'exploration':'outcome'}">+ Task</button><button class="button small ghost" data-add-quest-entry="${q.id}">+ Idea</button></div></div>${img(label==='Exploration'?'scene_discovery':'scene_goal','','scene')}</section><div class="tab-strip quest-tabs">${[['overview','Overview'],['tasks','Tasks'],['explore','Explore']].map(([k,l])=>`<button class="tab-button ${tab===k?'active':''}" data-quest-tab="${k}">${l}</button>`).join('')}</div>${tab==='overview'?renderQuestOverview(q):tab==='tasks'?renderQuestTasksDetail(q):renderQuestExplore(q)}`
}
function renderQuestOverview(q){
  const tasks=questTasks(q.id),next=taskById(q.nextMoveTaskId),known=questKnown(q),metrics=questExplorationMetrics(q),latest=[...(q.exploration.entries||[])].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))[0],neg=questNeglect(q);
  return `<div class="layout-2"><div class="stack"><section class="panel">${panelHead('Quest Overview','Goal/Project progress and Exploration progress remain distinct.','goal_goal','<button class="button small ghost" data-edit-quest="'+q.id+'">Edit</button>')}<div class="grid two"><div><h3>Outcome</h3><p class="muted">${esc(q.outcome.enabled?q.outcome.statement||'Outcome not yet written.':'No outcome track yet.')}</p>${q.outcome.enabled?`<div class="quest-progress-line"><span>${q.outcome.progress}%</span><div class="quest-progress-bar"><span style="width:${Math.min(100,q.outcome.progress)}%"></span></div><span>${known.done}/${known.total} known tasks</span></div>`:'<button class="button tiny primary" data-enable-outcome="'+q.id+'">Add outcome track</button>'}</div><div><h3>Exploration</h3><p class="muted">${esc(q.exploration.enabled?q.exploration.centralQuestion||'Central question not yet written.':'No exploration track yet.')}</p>${q.exploration.enabled?`<div class="quest-stats">${tag(`${metrics.answered}/${metrics.questions} questions`,'discovery_question','explore')}${tag(`${metrics.done}/${metrics.tasks} research tasks`,'discovery_research','explore')}${tag(q.exploration.readiness,'decision_criteria','explore')}</div>`:'<button class="button tiny primary" data-enable-exploration="'+q.id+'">Add exploration track</button>'}</div></div></section><section class="panel">${panelHead('Next Move','Every active Quest should have one clear executable step.','goal_next','<button class="button small ghost" data-select-next-move="'+q.id+'">Choose</button>')}${next?`<div class="next-move">${img(categoryIcon(taskCategory(next)),'')}<div><strong>${esc(next.title)}</strong><small>${taskCategory(next)}${next.plannedDate?` · Planned ${fmtDate(next.plannedDate)}`:' · Unscheduled'}</small></div><button class="button tiny primary" data-open-task="${next.id}">Open</button></div>`:'<div class="empty">No Next Move. Select an existing task, add a task, or turn an Idea into a task.</div>'}</section><section class="panel">${panelHead('Next Tasks','Plan and sequence the next known work without mapping the whole Quest.','object_action','<button class="button small primary" data-quest-tab="tasks">Open task board</button>')}<div class="activity-list">${tasks.filter(t=>t.status!=='Completed').slice(0,5).map(t=>activityRow(taskActivity(t))).join('')||'<div class="empty">No open Quest tasks.</div>'}</div></section></div><aside class="stack"><section class="panel">${panelHead('Quest Health','Neglect is derived from missing plans, repeated postponement, and lack of progress.','risk_watch')}<div class="stack">${neg.reasons.length?neg.reasons.map(r=>`<div class="notice watch">${img('risk_watch','')}<div><strong>Needs attention</strong><p>${esc(r)}</p></div></div>`).join(''):'<div class="notice">'+img('habit_on_track','')+'<div><strong>Moving</strong><p>The Quest has a next move and recent progress.</p></div></div>'}</div></section><section class="panel">${panelHead('Latest Evolution','Ideas and decisions remain connected to the tasks they create.','discovery_new')}${latest?`<div class="entry-card"><p><strong>${esc(latest.type)}:</strong> ${esc(latest.text)}</p><div class="entry-actions"><button class="button tiny primary" data-entry-to-task="${latest.id}" data-quest="${q.id}">Create Task</button></div></div>`:'<div class="empty compact">No Ideas or evidence yet.</div>'}</section><section class="panel"><button class="button primary" style="width:100%" data-add-quest-task="${q.id}">+ Add Task</button><button class="button ghost" style="width:100%;margin-top:7px" data-close-quest="${q.id}">Close or pause Quest</button></section></aside></div>`
}
function renderQuestTasksDetail(q){
  const filter=state.ui.questTaskFilter||'All',streams=[...(q.workstreams||[])].sort((a,b)=>(a.order||0)-(b.order||0));let tasks=questTasks(q.id);if(filter==='Goal/Project')tasks=tasks.filter(t=>t.track!=='exploration');if(filter==='Exploration')tasks=tasks.filter(t=>t.track==='exploration');if(filter==='Completed')tasks=tasks.filter(t=>t.status==='Completed');else tasks=tasks.filter(t=>t.status!=='Completed');
  return `<section class="panel">${panelHead('Quest Tasks','Goal/Project and Exploration tasks use the same planner but contribute to different Quest progress.','object_action','<button class="button small ghost" data-add-workstream="'+q.id+'">+ Workstream</button><button class="button small primary" data-add-quest-task="'+q.id+'">+ Task</button>')}<div class="subfilters">${['All','Goal/Project','Exploration','Completed'].map(x=>`<button class="chip ${filter===x?'active':''}" data-quest-task-detail-filter="${x}">${x}</button>`).join('')}</div><div class="stack" style="margin-top:8px">${streams.map(s=>{const list=tasks.filter(t=>t.workstreamId===s.id).sort((a,b)=>a.plannedOrder-b.plannedOrder);return `<section class="workstream" data-workstream-drop="${s.id}" data-quest="${q.id}"><div class="workstream-head"><h3>${esc(s.title)}</h3><button class="button tiny primary" data-add-quest-task="${q.id}" data-workstream="${s.id}">+ Next Task</button></div><div class="workstream-actions">${list.length?list.map(t=>activityRow(taskActivity(t))).join(''):'<div class="empty compact">No tasks in this workstream.</div>'}</div><div class="workstream-drop"></div></section>`}).join('')}${tasks.filter(t=>!t.workstreamId).length?`<section class="workstream"><div class="workstream-head"><h3>Unsorted</h3><button class="button tiny primary" data-add-quest-task="${q.id}">+ Task</button></div><div class="workstream-actions">${tasks.filter(t=>!t.workstreamId).map(t=>activityRow(taskActivity(t))).join('')}</div></section>`:''}</div></section>`
}
function renderQuestExplore(q){
  const entries=q.exploration.entries||[],groups=['Question','Idea','Evidence','Experiment','Option','Decision','Insight','Note'];const metrics=questExplorationMetrics(q);
  return `<div class="stack"><section class="panel">${panelHead('Exploration Progress','Track questions, evidence, experiments, options, decisions, and their actionable tasks.','scene_discovery','<button class="button small primary" data-add-quest-entry="'+q.id+'">+ Capture</button>')}<div class="review-summary"><div class="review-metric">${img('discovery_question','')}<strong>${metrics.answered}/${metrics.questions}</strong><span>Questions</span></div><div class="review-metric">${img('discovery_evidence','')}<strong>${metrics.evidence}</strong><span>Evidence</span></div><div class="review-metric">${img('discovery_experiment','')}<strong>${metrics.experiments}</strong><span>Experiments</span></div><div class="review-metric">${img('decision_reached','')}<strong>${metrics.decisions}</strong><span>Decisions</span></div><div class="review-metric">${img('discovery_research','')}<strong>${metrics.done}/${metrics.tasks}</strong><span>Explore Tasks</span></div></div><div class="form-field" style="margin-top:10px"><label>Central question</label><div class="next-move">${img('discovery_question','')}<div><strong>${esc(q.exploration.centralQuestion||'No central question yet')}</strong><small>Decision readiness: ${esc(q.exploration.readiness||'Early')}</small></div><button class="button tiny ghost" data-edit-quest="${q.id}">Edit</button></div></div></section><div class="explore-grid">${groups.map(type=>{const list=entries.filter(e=>e.type===type);if(!list.length&&['Insight','Note'].includes(type))return'';return `<section class="explore-section"><h3>${type}<button class="button tiny ghost" data-add-quest-entry="${q.id}" data-entry-type="${type}">+</button></h3>${list.length?list.map(e=>`<article class="entry-card"><p>${esc(e.text)}</p><div class="entry-actions"><button class="button tiny primary" data-entry-to-task="${e.id}" data-quest="${q.id}">Create Task</button>${type==='Question'&&!e.resolved?`<button class="button tiny ghost" data-resolve-question="${e.id}" data-quest="${q.id}">Answered</button>`:''}</div></article>`).join(''):'<div class="empty compact">None yet.</div>'}</section>`}).join('')}</div></div>`
}
function renderHabitWorkspace(){
  const list=activeHabits();return `<section class="panel">${panelHead('Habits','Define recurring targets here. Their scheduled occurrences and period check-ins appear in Today.','scene_habit','<button class="button primary small" data-new-habit>+ New Habit</button>')}<div class="habit-list">${list.length?list.map(h=>{const p=periodProgress(h),neg=habitNeglect(h);return `<article class="habit-card">${img(h.direction==='Avoid'?'habit_avoid':h.direction==='Limit'?'habit_limit':'habit_build','')}<div><h3>${esc(h.title)}</h3><p>${esc(h.area)}${h.questId?` · ${esc(questById(h.questId)?.title||'Quest')}`:''} · ${esc(h.measurement==='quantity'?'Numeric target':'Repeatable check-ins')}</p><div class="habit-meter"><span style="width:${Math.min(100,p.percent)}%"></span></div><div class="habit-counters"><span>${p.actual}/${p.target} ${esc(h.unit)}</span><span>${p.percent}%</span><span>${esc(h.period)}</span><span>${esc(h.maturity)} · ${esc(h.health)}</span>${neg.reasons[0]?`<span style="color:#8b3029">${esc(neg.reasons[0])}</span>`:''}</div></div><div><button class="button tiny primary" data-update-habit="${h.id}">Update</button><button class="button tiny ghost" data-open-habit="${h.id}">Manage</button><button class="button tiny ghost" data-schedule-habit="${h.id}">Schedule</button></div></article>`}).join(''):'<div class="empty">No Habits yet.</div>'}</div></section>`
}
function renderQuestArchive(){const quests=state.quests.filter(q=>q.archivedAt),habits=state.habits.filter(h=>h.archivedAt);return `<section class="panel">${panelHead('Archive','Completed context remains available without competing with active planning.','decision_archived')}<div class="stack">${quests.map(q=>`<div class="inbox-row"><div><strong>${esc(q.title)}</strong><small>Quest · ${esc(q.status)}</small></div><button class="button tiny ghost" data-restore-quest="${q.id}">Restore</button></div>`).join('')}${habits.map(h=>`<div class="inbox-row"><div><strong>${esc(h.title)}</strong><small>Habit</small></div><button class="button tiny ghost" data-restore-habit="${h.id}">Restore</button></div>`).join('')||'<div class="empty">Archive is empty.</div>'}</div></section>`}

function renderCapture(){
  const tab=state.ui.captureTab||'new',open=state.inbox.filter(i=>i.status==='open').length;root.innerHTML=`${hero({title:'Capture',subtitle:'Choose a category first. Saving without a category is available, but it is intentionally the exception.',scene:'character_capture',meta:[['Inbox',String(open)],['Tasks',String(openTasks().length)],['Quests',String(activeQuests().length)],['Habits',String(activeHabits().length)]]})}<div class="tab-strip"><button class="tab-button ${tab==='new'?'active':''}" data-capture-tab="new">New Capture</button><button class="tab-button ${tab==='inbox'?'active':''}" data-capture-tab="inbox">Inbox · ${open}</button></div>${tab==='new'?renderCaptureNew():renderInbox()}`
}
function renderCaptureNew(){const type=state.ui.captureType||'Task';return `<div class="capture-shell"><section class="panel capture-box">${panelHead('What are you adding?','The category determines the next lightweight form.','object_inbox')}<textarea id="capture-text" placeholder="Write the task, Quest, Habit, idea, or note…"></textarea><div class="capture-types">${[
    ['Task','object_action','A concrete step. Standalone tasks default to Resolve; Quest tasks inherit Goal/Project or Exploration.'],
    ['Quest','object_goal','A meaningful initiative with an optional outcome and optional exploration track.'],
    ['Habit','object_habit','A recurring target measured inside a day, week, or month.'],
    ['Idea/Note','discovery_new','An idea, question, evidence item, decision, or resource—usually attached to a Quest.']
  ].map(([k,icon,desc])=>`<button class="capture-type ${type===k?'active':''}" data-capture-type="${k}">${img(icon,'')}<span><strong>${k}</strong><small>${desc}</small></span></button>`).join('')}</div><div class="toolbar" style="margin-top:10px"><button class="button primary" data-continue-capture>Continue</button><button class="button ghost" data-save-uncategorized>Save without category</button></div></section><aside class="panel">${panelHead('Fast examples','Categories can be converted later without losing the original text.','character_capture')}<div class="stack"><div class="candidate-group"><h3>Task</h3><small>Call dentist · Research fintech roles · Book hotel</small></div><div class="candidate-group"><h3>Quest</h3><small>Find a new job · Improve portfolio strategy</small></div><div class="candidate-group"><h3>Habit</h3><small>Run 3× weekly · Clean house monthly</small></div><div class="candidate-group"><h3>Idea/Note</h3><small>Industry idea · Recruiter insight · Research evidence</small></div></div></aside></div>`}
function renderInbox(){const list=state.inbox.filter(i=>i.status==='open');return `<section class="panel">${panelHead('Inbox','Only uncategorized or interrupted captures belong here.','object_inbox')}<div class="stack">${list.length?list.map(i=>`<article class="inbox-row"><div><strong>${esc(i.text)}</strong><small>Captured ${fmtDate(i.createdAt?.slice(0,10))} · Needs classification</small></div><div class="panel-actions"><button class="button tiny primary" data-classify-inbox="${i.id}">Classify</button><button class="button tiny ghost" data-delete-inbox="${i.id}">Delete</button></div></article>`).join(''):'<div class="empty">Inbox is clear. New captures normally go directly into a category.</div>'}</div></section>`}

function reviewPeriodBounds(){const d=new Date(`${todayISO()}T12:00:00`),range=state.ui.reviewRange||'week';if(range==='month'){return{start:localDateISO(new Date(d.getFullYear(),d.getMonth(),1,12)),end:localDateISO(new Date(d.getFullYear(),d.getMonth()+1,0,12)),label:new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(d)}}const offset=(d.getDay()+6)%7,start=new Date(d);start.setDate(d.getDate()-offset);const end=new Date(start);end.setDate(start.getDate()+6);return{start:localDateISO(start),end:localDateISO(end),label:`${fmtDate(localDateISO(start))}–${fmtDate(localDateISO(end))}`}}
function completedInRange(start,end){return state.tasks.filter(t=>t.status==='Completed'&&t.completedAt?.slice(0,10)>=start&&t.completedAt?.slice(0,10)<=end)}
function renderReview(){
  const b=reviewPeriodBounds(),completed=completedInRange(b.start,b.end),resolved=completed.filter(t=>taskCategory(t)==='Resolve'),goal=completed.filter(t=>taskCategory(t)==='Goal/Project'),explore=completed.filter(t=>taskCategory(t)==='Exploration'),renew=completed.filter(t=>taskCategory(t)==='Renew/Fun'),habitResults=activeHabits().map(h=>({h,p:periodProgress(h,b.end)})),areas=areaInsights(),needs=areas.filter(a=>a.status==='Needs Focus'||a.status==='Dormant'),strong=areas.filter(a=>a.status==='Strong Momentum'),big=completed.filter(t=>t.importance==='High'||t.progress===100).slice(0,5);
  root.innerHTML=`${hero({title:'Progress Story',subtitle:'Recognize real movement first, then surface neglected tasks, Quests, Habits, and life areas with clear evidence.',scene:'scene_campfire',meta:[['Period',b.label],['Big Moves',String(big.length)],['Completed',String(completed.length)],['Needs Focus',String(needs.length)]]})}<div class="toolbar"><div class="segmented"><button class="${state.ui.reviewRange==='week'?'active':''}" data-review-range="week">This Week</button><button class="${state.ui.reviewRange==='month'?'active':''}" data-review-range="month">This Month</button></div><button class="button primary" data-complete-review>${img('badge_campfire','')}Complete Review</button></div><div class="layout-2"><div class="stack"><section class="panel">${panelHead('Big Moves','Meaningful outcomes, major task progress, decisions, and recoveries appear before raw task counts.','badge_momentum')}<div class="stack">${big.length?big.map(t=>`<article class="big-move">${img(categoryIcon(taskCategory(t)),'')}<div><strong>${esc(t.title)}</strong><p>${esc(taskCategory(t))}${t.questId?` · ${esc(questById(t.questId)?.title||'Quest')}`:''} · completed ${fmtDate(t.completedAt.slice(0,10))}</p></div><button class="button tiny ghost" data-open-task="${t.id}">Open</button></article>`).join(''):'<div class="empty compact">No Big Move has been identified in this period. Small and steady progress still counts.</div>'}</div></section><section class="panel">${panelHead('Progress Dimensions','Different kinds of progress are visible without competing against each other.','object_review')}<div class="review-summary"><div class="review-metric">${img('mode_achieve','')}<strong>${goal.length}</strong><span>Goal Tasks</span></div><div class="review-metric">${img('mode_explore','')}<strong>${explore.length}</strong><span>Exploration</span></div><div class="review-metric">${img('mode_resolve','')}<strong>${resolved.length}</strong><span>Resolved</span></div><div class="review-metric">${img('mode_sustain','')}<strong>${habitResults.filter(x=>x.p.met).length}</strong><span>Habits Met</span></div><div class="review-metric">${img('mode_renew','')}<strong>${renew.length}</strong><span>Renewed</span></div></div></section><section class="panel">${panelHead('Habit Rhythm','Period success, overdelivery, and risk are measured against each Habit target.','habit_stable')}<div class="habit-list">${habitResults.map(({h,p})=>`<article class="habit-card">${img(h.direction==='Avoid'?'habit_avoid':h.direction==='Limit'?'habit_limit':'habit_build','')}<div><h3>${esc(h.title)}</h3><p>${p.actual}/${p.target} ${esc(h.unit)} · ${p.percent}% · ${p.met?'Target achieved':'In progress'}</p><div class="habit-meter"><span style="width:${Math.min(100,p.percent)}%"></span></div></div><span class="area-status ${p.met?'strong':'focus'}">${p.actual>p.target?'Overdelivered':p.met?'Achieved':'Needs attention'}</span></article>`).join('')}</div></section><section class="panel">${panelHead('Quest Movement','Outcome tasks and exploration tasks remain distinct but contribute to the same Quest story.','scene_goal')}<div class="quest-list">${activeQuests().filter(q=>recent(q.updatedAt,state.ui.reviewRange==='month'?35:14)).map(q=>{const known=questKnown(q),m=questExplorationMetrics(q);return `<article class="quest-row">${img(questLabel(q)==='Exploration'?'scene_discovery':'scene_goal','')}<div><h3>${esc(q.title)}</h3><p>${questLabel(q)} · ${esc(q.status)}</p><div class="quest-stats">${q.outcome.enabled?tag(`${q.outcome.progress}% outcome`,'goal_progress','quest'):''}${q.exploration.enabled?tag(`${m.done}/${m.tasks} explore tasks`,'discovery_research','explore'):''}${tag(`${known.done}/${known.total} known tasks`,'object_action')}</div></div><div class="row-tail"><button class="button tiny primary" data-open-quest="${q.id}">Open</button></div></article>`}).join('')||'<div class="empty">No Quest movement in this period.</div>'}</div></section></div><aside class="stack"><section class="panel">${panelHead('Strong Momentum','Areas with meaningful recent completion or Quest movement.','habit_on_track')}<div class="area-pulse">${strong.length?strong.map(renderAreaRow).join(''):'<div class="empty compact">No area currently qualifies as strong momentum.</div>'}</div></section><section class="panel">${panelHead('Needs Proactive Focus','Warnings come from neglected tasks, stalled Quests, or Habit periods—not from an arbitrary time-spent score.','risk_at_risk')}<div class="stack">${needs.length?needs.map(a=>renderAreaNeglect(a)).join(''):'<div class="empty compact">No life area currently needs proactive focus.</div>'}</div></section><section class="panel">${panelHead('Recurring Achievement','Approved badge art is reused while period counts and streaks remain live data.','badge_habit')}${renderRecurringAchievement()}</section></aside></div>`;
}
function renderAreaRow(a){return `<div class="area-row">${img(AREA_ICONS[a.area]||'realm_professional','')}<div><strong>${esc(a.area)}</strong><small>${a.completed.length} completed in 30 days${a.last?` · last movement ${daysSince(a.last)}d ago`:''}</small></div><span class="area-status strong">${esc(a.status)}</span></div>`}
function renderAreaNeglect(a){const reasons=[];if(a.neglectedTasks.length)reasons.push(`${a.neglectedTasks.length} task${a.neglectedTasks.length===1?'':'s'} need attention`);if(a.neglectedQuests.length)reasons.push(`${a.neglectedQuests.length} Quest${a.neglectedQuests.length===1?'':'s'} stalled`);if(a.neglectedHabits.length)reasons.push(`${a.neglectedHabits.length} Habit target${a.neglectedHabits.length===1?'':'s'} at risk`);if(!reasons.length)reasons.push(a.last?`No meaningful movement for ${daysSince(a.last)} days`:'No meaningful movement recorded');return `<article class="neglect-card">${img(AREA_ICONS[a.area]||'realm_professional','')}<div><h3>${esc(a.area)} · ${esc(a.status)}</h3><p>${esc(reasons.join(' · '))}</p><div class="entry-actions"><button class="button tiny primary" data-review-area="${a.area}">Review items</button><button class="button tiny ghost" data-quiet-area="${a.area}">Quiet by Choice</button></div></div></article>`}
function renderRecurringAchievement(){const r=state.recurringAchievements.habitKeeper||{periods:0,currentStreak:0,bestStreak:0,lastPeriod:'—'};return `<article class="achievement">${img('badge_habit','')}<div><h3>Habit Keeper</h3><p>Earned whenever the selected Habit-success threshold is met for a review period.</p><div class="achievement-stats"><span>${r.periods} periods</span><span>${r.currentStreak} current streak</span><span>${r.bestStreak} best streak</span></div></div></article>`}

function renderCalendar(){const events=[...state.calendarEvents].sort((a,b)=>a.date.localeCompare(b.date)||String(a.startTime).localeCompare(String(b.startTime)));root.innerHTML=`${hero({title:'Calendar Commitments',subtitle:'Read-only imported calendar context appears in Today. Convert a commitment into a Task only when you need preparation, follow-up, or completion tracking.',scene:'scene_today',meta:[['Events',String(events.length)],['Source','Manual or .ics snapshot'],['Write access','Disabled'],['Version',`v${VERSION}`]]})}<section class="panel">${panelHead('Calendar','Fixed commitments reduce available capacity without becoming duplicate Tasks.','object_event','<button class="button primary small" data-import-ics>Import .ics</button>')}<div class="stack">${events.length?events.map(e=>`<div class="inbox-row"><div><strong>${esc(e.title)}</strong><small>${fmtDay(e.date)} · ${fmtTime(e.startTime)}${e.endTime?`–${fmtTime(e.endTime)}`:''} · ${esc(e.area)}</small></div><button class="button tiny ghost" data-calendar-to-task="${e.id}">Create linked Task</button></div>`).join(''):'<div class="empty">No calendar events imported.</div>'}</div></section>`}
function renderNotes(){const list=[...state.notes].sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));root.innerHTML=`${hero({title:'Notes & Resources',subtitle:'Ideas, evidence, decisions, and references can remain non-actionable or create one or more Quest tasks.',scene:'scene_discovery',meta:[['Notes',String(list.length)],['Inbox',String(state.inbox.filter(i=>i.status==='open').length)],['Quest-linked',String(list.filter(n=>n.questId).length)],['Version',`v${VERSION}`]]})}<section class="panel">${panelHead('Notes','Open a Quest to see its structured exploration entries. This view includes standalone notes and references.','object_reference','<button class="button primary small" data-new-note>+ Note</button>')}<div class="stack">${list.length?list.map(n=>`<article class="inbox-row"><div><strong>${esc(n.type||'Note')} · ${esc(n.text||n.title||'')}</strong><small>${n.questId?`Quest: ${esc(questById(n.questId)?.title||'Unknown')}`:'Standalone'} · ${fmtDate(n.createdAt?.slice(0,10))}</small></div>${n.questId?`<button class="button tiny ghost" data-open-quest="${n.questId}">Open Quest</button>`:''}</article>`).join(''):'<div class="empty">No notes or resources.</div>'}</div></section>`}
function renderSync(){root.innerHTML=`${hero({title:'Data & Sync',subtitle:'Data remains local. Export a JSON or Excel workbook, move it through Google Drive, and import it on another device.',scene:'scene_today',meta:[['Tasks',String(state.tasks.length)],['Quests',String(state.quests.length)],['Habits',String(state.habits.length)],['Version',`v${VERSION}`]]})}<div class="grid two"><section class="panel">${panelHead('Export','Create a complete local backup.','object_reference')}<div class="stack"><button class="button primary" data-export-json>Export JSON Backup</button><button class="button primary" data-export-excel>Export Excel Workbook</button></div></section><section class="panel">${panelHead('Import','Newer records replace older records by ID and timestamp.','object_inbox')}<button class="button primary" data-import-file>Import JSON or Excel</button></section><section class="panel">${panelHead('Manual phone ↔ desktop sync','1. Export on the first device. 2. Save the workbook in Google Drive. 3. Import it on the second device.','resources')}<p class="muted">Quest links, Task tracks, Habit periods, planned-date history, reviews, and recurring achievements are preserved.</p></section><section class="panel">${panelHead('Version Metadata','Exports record the deployed app and data-schema versions.','brand')}<p><strong>Questline v${VERSION}</strong></p><p class="muted">Schema ${SCHEMA_VERSION} · Storage key ${STORAGE_KEY}</p></section></div>`}
function renderSettings(){root.innerHTML=`${hero({title:'Settings',subtitle:'Adjust planning horizon, daily capacity, review period, and motion. The app version is visible here and in exports.',scene:'scene_today',meta:[['Version',`v${VERSION}`],['Schema',String(SCHEMA_VERSION)],['Storage','Local browser'],['Horizon',`${state.settings.planningHorizonDays} days`]]})}<div class="grid two"><section class="panel">${panelHead('Planning','Seven days is the default, but you can plan farther forward at any time.','character_plan')}<div class="form-grid"><div class="form-field"><label>Planning horizon (days)</label><input id="setting-horizon" type="number" min="1" max="90" value="${state.settings.planningHorizonDays}"></div><div class="form-field"><label>Daily capacity (minutes)</label><input id="setting-capacity" type="number" min="30" max="720" step="15" value="${state.settings.dailyCapacityMinutes}"></div><div class="form-field"><label>Review period</label><select id="setting-review"><option value="week" ${state.settings.reviewPeriod==='week'?'selected':''}>Week</option><option value="month" ${state.settings.reviewPeriod==='month'?'selected':''}>Month</option></select></div></div><button class="button primary" style="margin-top:10px" data-save-settings>Save Settings</button></section><section class="panel">${panelHead('Application Version','The version is visible in navigation, Settings, exports, and the browser title.','brand')}<h3>Questline v${VERSION}</h3><p class="muted">Version 4.2 · Movable Tasks, trustworthy Review analytics, automatic history, and compact mobile planning.</p><code>schema ${SCHEMA_VERSION}</code></section><section class="panel">${panelHead('Display','Motion respects system preferences and can be disabled.','settings')}<label class="inbox-row"><div><strong>Celebration motion</strong><small>Lightweight feedback for progress and recovery.</small></div><input id="setting-motion" type="checkbox" ${state.settings.motion?'checked':''}></label></section><section class="panel">${panelHead('Reset Demo','Replace local data with the Version 4 sample portfolio.','risk_critical')}<button class="button danger" data-reset-demo>Reset local data</button></section></div>`}

function openTaskEditor(existing=null,defaults={}){
  const t=existing?normalizeTask(existing):normalizeTask({id:uid('task'),title:defaults.title||'',area:defaults.area||'Professional',questId:defaults.questId||null,track:defaults.track||null,standaloneType:defaults.standaloneType||'Resolve',workstreamId:defaults.workstreamId||null,status:'To Do',progress:0,plannedDate:defaults.plannedDate||null,startTime:defaults.startTime||null,endTime:defaults.endTime||null,dueDate:defaults.dueDate||null,importance:'Medium',urgency:'Medium',estimateMinutes:defaults.estimateMinutes||0,plannedOrder:99,createdAt:nowStamp(),updatedAt:nowStamp(),sourceEntryId:defaults.sourceEntryId||null});
  const quest=t.questId?questById(t.questId):null;
  showModal(`${modalHeader(existing?'Edit Task':'New Task','Quest-linked tasks inherit Goal/Project or Exploration. Standalone tasks are Resolve or Renew/Fun.')}<form id="task-form" data-id="${t.id}" data-existing="${existing?'1':'0'}" data-source-entry="${esc(t.sourceEntryId||'')}"><div class="modal-body"><div class="form-grid"><div class="form-field full"><label>Task</label><input name="title" required value="${esc(t.title)}" placeholder="Concrete next step"></div><div class="form-field"><label>Quest (optional)</label><select name="questId" id="task-quest"><option value="">Standalone task</option>${activeQuests().filter(q=>!['Completed','Stopped'].includes(q.status)).map(q=>`<option value="${q.id}" ${t.questId===q.id?'selected':''}>${esc(q.title)}</option>`).join('')}</select></div><div class="form-field" data-track-field><label>Quest track</label><select name="track"><option value="outcome" ${t.track!=='exploration'?'selected':''}>Goal / Project</option><option value="exploration" ${t.track==='exploration'?'selected':''}>Exploration</option></select></div><div class="form-field" data-standalone-field><label>Standalone type</label><select name="standaloneType"><option value="Resolve" ${t.standaloneType!=='Renew/Fun'?'selected':''}>Resolve</option><option value="Renew/Fun" ${t.standaloneType==='Renew/Fun'?'selected':''}>Renew / Fun</option></select></div><div class="form-field"><label>Life area</label><select name="area">${AREAS.map(a=>`<option ${t.area===a?'selected':''}>${a}</option>`).join('')}</select></div><div class="form-field" data-workstream-field><label>Workstream</label><select name="workstreamId" id="task-workstream"><option value="">Unsorted</option>${quest?(quest.workstreams||[]).map(w=>`<option value="${w.id}" ${t.workstreamId===w.id?'selected':''}>${esc(w.title)}</option>`).join(''):''}</select></div><div class="form-field"><label>Status</label><select name="status">${TASK_STATUSES.filter(x=>x!=='Archived').map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Progress</label><input name="progress" type="number" min="0" max="100" step="5" value="${t.progress}"></div><div class="form-field"><label>Planned date</label><input name="plannedDate" type="date" value="${t.plannedDate||''}"></div><div class="form-field"><label>Due date</label><input name="dueDate" type="date" value="${t.dueDate||''}"></div><div class="form-field"><label>Start time (optional)</label><input name="startTime" type="time" value="${t.startTime||''}"></div><div class="form-field"><label>End time (optional)</label><input name="endTime" type="time" value="${t.endTime||''}"></div><div class="form-field"><label>Estimated minutes</label><input name="estimateMinutes" type="number" min="0" step="5" value="${t.estimateMinutes}"></div><div class="form-field"><label>Importance</label><select name="importance">${IMPORTANCE.map(x=>`<option ${t.importance===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Urgency</label><select name="urgency">${URGENCY.map(x=>`<option ${t.urgency===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field full"><label>Notes</label><textarea name="notes">${esc(t.notes||'')}</textarea></div></div></div>${modalActions(existing?`<button type="button" class="button danger" data-archive-task="${t.id}">Archive</button>`:'<button type="button" class="button ghost" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Save Task</button>')}</form>`,true);toggleTaskSourceFields();
}
function toggleTaskSourceFields(){const form=$('#task-form');if(!form)return;const linked=!!form.elements.questId.value;$('[data-track-field]',form)?.classList.toggle('hidden',!linked);$('[data-standalone-field]',form)?.classList.toggle('hidden',linked);$('[data-workstream-field]',form)?.classList.toggle('hidden',!linked)}
function saveTask(form){
  const fd=new FormData(form),existing=taskById(form.dataset.id),old=existing?clone(existing):null,questId=fd.get('questId')||null,quest=questById(questId),planned=fd.get('plannedDate')||null,due=fd.get('dueDate')||null;
  const t=normalizeTask({...(existing||{}),id:form.dataset.id,title:String(fd.get('title')||'').trim(),area:quest?.area||fd.get('area'),questId,track:questId?(fd.get('track')||'outcome'):null,standaloneType:questId?'Resolve':fd.get('standaloneType'),workstreamId:questId?(fd.get('workstreamId')||null):null,status:fd.get('status'),progress:Number(fd.get('progress')||0),plannedDate:planned,startTime:fd.get('startTime')||null,endTime:fd.get('endTime')||null,dueDate:due,importance:fd.get('importance'),urgency:fd.get('urgency'),estimateMinutes:Number(fd.get('estimateMinutes')||0),notes:String(fd.get('notes')||''),plannedOrder:existing?.plannedOrder||99,plannedDateHistory:existing?.plannedDateHistory||[],dueDateHistory:existing?.dueDateHistory||[],createdAt:existing?.createdAt||nowStamp(),updatedAt:nowStamp(),lastProgressAt:existing?.lastProgressAt||null,sourceEntryId:existing?.sourceEntryId||form.dataset.sourceEntry||null});
  if(existing&&old.plannedDate!==planned)t.plannedDateHistory=[...(old.plannedDateHistory||[]),{from:old.plannedDate,to:planned,at:nowStamp(),reason:'Changed in editor'}];
  if(existing&&old.dueDate!==due)t.dueDateHistory=[...(old.dueDateHistory||[]),{from:old.dueDate,to:due,at:nowStamp()}];
  if(t.status==='Completed'&&!t.completedAt)t.completedAt=nowStamp();if(t.status!=='Completed')t.completedAt=null;if(t.progress>Number(existing?.progress||0))t.lastProgressAt=nowStamp();
  if(existing)Object.assign(existing,t);else{t.plannedOrder=activeTasks().filter(x=>x.plannedDate===t.plannedDate).length+1;state.tasks.push(t)}
  if(questId&&quest&&!quest.nextMoveTaskId)quest.nextMoveTaskId=t.id;if(quest)quest.updatedAt=nowStamp();save();closeModal();toast(existing?'Task updated':'Task created',categoryIcon(taskCategory(t)));render();
}
function openTaskProgress(id){const t=taskById(id);if(!t)return;showModal(`${modalHeader('Update Progress',t.title)}<form id="task-progress-form" data-id="${t.id}"><div class="modal-body"><div class="form-field"><label>Progress: <strong id="progress-value">${t.progress}%</strong></label><input id="progress-range" name="progress" type="range" min="0" max="100" step="5" value="${t.progress}"></div><div class="form-field" style="margin-top:10px"><label>Evidence or note (optional)</label><textarea name="note" placeholder="What changed, what was learned, or what remains?"></textarea></div><label class="inbox-row" style="margin-top:10px"><div><strong>Mark complete at 100%</strong><small>Completion updates Today, the Quest, and Review.</small></div><input type="checkbox" name="completeAt100" checked></label></div>${modalActions('<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Save Progress</button>')}</form>`)}
function saveTaskProgress(form){const t=taskById(form.dataset.id);if(!t)return;const fd=new FormData(form),p=Number(fd.get('progress')||0),old=t.progress;t.progress=p;t.lastProgressAt=nowStamp();t.updatedAt=nowStamp();const note=String(fd.get('note')||'').trim();if(note)t.notes=[t.notes,note].filter(Boolean).join('\n');if(p>=100&&fd.get('completeAt100')){t.status='Completed';t.completedAt=nowStamp()}else if(p>0&&t.status==='To Do')t.status='In Progress';const q=questById(t.questId);if(q)q.updatedAt=nowStamp();state.profile.xp+=Math.max(0,p-old);save();closeModal();toast(p>=100?'Task completed':'Progress updated',p>=100?'signal_complete':'goal_progress');render()}
function openMoveActivity(key,date){
  const [kind,id,occId]=key.split(':');if(kind==='task'){const t=taskById(id);if(!t)return;showModal(`${modalHeader('Move Task',t.title)}<form id="move-task-form" data-id="${t.id}"><div class="modal-body"><div class="form-grid"><div class="form-field"><label>Planned date</label><input name="plannedDate" type="date" value="${t.plannedDate||''}"></div><div class="form-field"><label>Due date</label><input name="dueDate" type="date" value="${t.dueDate||''}"></div><div class="form-field"><label>Importance</label><select name="importance">${IMPORTANCE.map(x=>`<option ${t.importance===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Urgency</label><select name="urgency">${URGENCY.map(x=>`<option ${t.urgency===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field full"><label>Reason (optional)</label><select name="reason"><option value="">No reason</option><option>Capacity conflict</option><option>Waiting on someone</option><option>Priority changed</option><option>Scope increased</option><option>Original date was unrealistic</option><option>Procrastination</option></select></div></div></div>${modalActions('<button class="button ghost" type="button" data-unschedule-task="'+t.id+'">Unscheduled</button>','<button class="button primary" type="submit">Move Task</button>')}</form>`)}else if(kind==='habit'){const h=habitById(id),o=h?.occurrences.find(x=>x.id===occId);if(!h||!o)return;showModal(`${modalHeader('Move Habit Activity',h.title)}<form id="move-habit-form" data-habit="${h.id}" data-occurrence="${o.id}"><div class="modal-body"><div class="form-field"><label>Planned date</label><input name="date" type="date" value="${o.date}"></div><p class="muted">Moving an occurrence inside the same period does not reduce Habit success.</p></div>${modalActions('<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Move Activity</button>')}</form>`)}
}
function saveMoveTask(form){const t=taskById(form.dataset.id);if(!t)return;const fd=new FormData(form),planned=fd.get('plannedDate')||null,due=fd.get('dueDate')||null,oldPlanned=t.plannedDate,oldDue=t.dueDate;if(planned!==oldPlanned)t.plannedDateHistory=[...(t.plannedDateHistory||[]),{from:oldPlanned,to:planned,at:nowStamp(),reason:fd.get('reason')||''}];if(due!==oldDue)t.dueDateHistory=[...(t.dueDateHistory||[]),{from:oldDue,to:due,at:nowStamp()}];t.plannedDate=planned;t.dueDate=due;t.importance=fd.get('importance');t.urgency=fd.get('urgency');t.updatedAt=nowStamp();save();closeModal();toast('Task moved','clock_current');render()}
function saveMoveHabit(form){const h=habitById(form.dataset.habit),o=h?.occurrences.find(x=>x.id===form.dataset.occurrence);if(!h||!o)return;const date=new FormData(form).get('date');if(date&&date!==o.date){o.originalDate=o.originalDate||o.date;o.date=date;o.moveCount=(o.moveCount||0)+1;h.updatedAt=nowStamp()}save();closeModal();toast('Habit activity moved within its period','mode_sustain');render()}
function openActivity(key){const [kind,id]=key.split(':');if(kind==='task')openTaskEditor(taskById(id));else if(kind==='habit')openHabitEditor(habitById(id));}
function toggleTaskComplete(id){const t=taskById(id);if(!t)return;const before=clone(t);if(t.status==='Completed'){t.status=t.progress>0?'In Progress':'To Do';t.completedAt=null;toast('Task reopened','clock_recovered')}else{t.status='Completed';t.progress=100;t.completedAt=nowStamp();t.lastProgressAt=nowStamp();state.profile.xp+=25;const q=questById(t.questId);if(q)q.updatedAt=nowStamp();toast('Task completed','signal_complete',()=>{Object.assign(t,before);save();render()});if(taskCategory(t)==='Resolve')setTimeout(()=>openResolveClosure(t),120)}t.updatedAt=nowStamp();save();render()}
function openResolveClosure(t){showModal(`${modalHeader('Is the matter fully resolved?',t.title)}<div class="modal-body"><div class="stack"><button class="inbox-row" data-resolve-complete="${t.id}"><div><strong>Yes, close the loop</strong><small>No follow-up is needed.</small></div>${img('badge_loop','')}</button><button class="inbox-row" data-resolve-next="${t.id}"><div><strong>No, add the next step</strong><small>Create another standalone Resolve task.</small></div>${img('goal_next','')}</button><button class="inbox-row" data-resolve-wait="${t.id}"><div><strong>Waiting on someone</strong><small>Keep the task visible with a follow-up date.</small></div>${img('risk_waiting','')}</button></div></div>${modalActions('<button class="button ghost" data-close-modal>Decide later</button>','')}`)}
function completeHabitOccurrence(habitId,occurrenceId){const h=habitById(habitId),o=h?.occurrences.find(x=>x.id===occurrenceId);if(!h||!o)return;if(o.completedAt){o.completedAt=null;h.entries[o.date]=Math.max(0,Number(h.entries[o.date]||0)-1)}else{o.completedAt=nowStamp();h.entries[o.date]=Number(h.entries[o.date]||0)+1;state.profile.xp+=10}h.updatedAt=nowStamp();save();toast(`${h.title}: ${periodProgress(h,o.date).actual}/${h.targetValue}`,'habit_on_track');render()}
function openHabitProgress(id){const h=habitById(id);if(!h)return;const p=periodProgress(h);showModal(`${modalHeader('Update Habit',h.title)}<form id="habit-progress-form" data-id="${h.id}"><div class="modal-body"><div class="form-field"><label>${h.measurement==='quantity'?'Current quantity':'Completed occurrences'}</label><input name="actual" type="number" min="0" value="${p.actual}"></div><p class="muted">Target: ${p.target} ${esc(h.unit)} per ${esc(h.period)}. Overdelivery is allowed and stays in the current period.</p></div>${modalActions('<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Update Habit</button>')}</form>`)}
function saveHabitProgress(form){const h=habitById(form.dataset.id);if(!h)return;const p=periodProgress(h),actual=Math.max(0,Number(new FormData(form).get('actual')||0));Object.keys(h.entries).forEach(d=>{if(d>=p.start&&d<=p.end)delete h.entries[d]});h.entries[todayISO()]=actual;h.updatedAt=nowStamp();if(actual>=h.targetValue)state.profile.xp+=15;save();closeModal();toast(`${h.title}: ${actual}/${h.targetValue}`,'habit_on_track');render()}
function setTopPriority(key,date){const current=state.topPriorityByDate[date];if(current===key)delete state.topPriorityByDate[date];else state.topPriorityByDate[date]=key;save();toast(current===key?'Top Priority removed':'Top Priority set','priority_act');render()}

function openQuestEditor(existing=null,defaults={}){
  const q=existing?normalizeQuest(existing):normalizeQuest({id:uid('quest'),title:defaults.title||'',area:defaults.area||'Professional',status:'To Start',topQuest:false,manualOrder:activeQuests().length+1,outcome:{enabled:defaults.outcomeEnabled??true,statement:'',successCriteria:'',targetDate:null,progress:0,milestones:[]},exploration:{enabled:defaults.explorationEnabled??true,centralQuestion:'',readiness:'Early',entries:[]},workstreams:[{id:uid('ws'),title:'Next Steps',order:1}],createdAt:nowStamp(),updatedAt:nowStamp()});
  showModal(`${modalHeader(existing?'Edit Quest':'New Quest','A Quest may have an outcome track, an exploration track, or both.')}<form id="quest-form" data-id="${q.id}" data-existing="${existing?'1':'0'}"><div class="modal-body"><div class="form-grid"><div class="form-field full"><label>Quest title</label><input name="title" required value="${esc(q.title)}" placeholder="Find a new job"></div><div class="form-field"><label>Life area</label><select name="area">${AREAS.map(a=>`<option ${q.area===a?'selected':''}>${a}</option>`).join('')}</select></div><div class="form-field"><label>Status</label><select name="status">${QUEST_STATUSES.map(x=>`<option ${q.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field full"><label class="inbox-row"><span><strong>Goal / Project track</strong><small>Defined outcome, milestones, and progress.</small></span><input type="checkbox" name="outcomeEnabled" ${q.outcome.enabled?'checked':''}></label></div><div class="form-field full"><label>Desired outcome</label><textarea name="outcomeStatement" placeholder="What meaningful result are you trying to reach?">${esc(q.outcome.statement||'')}</textarea></div><div class="form-field"><label>Target date</label><input name="targetDate" type="date" value="${q.outcome.targetDate||''}"></div><div class="form-field"><label>Outcome progress</label><input name="outcomeProgress" type="number" min="0" max="100" step="5" value="${q.outcome.progress||0}"></div><div class="form-field full"><label>Success criteria</label><textarea name="successCriteria">${esc(q.outcome.successCriteria||'')}</textarea></div><div class="form-field full"><label class="inbox-row"><span><strong>Exploration track</strong><small>Questions, evidence, options, experiments, and decisions.</small></span><input type="checkbox" name="explorationEnabled" ${q.exploration.enabled?'checked':''}></label></div><div class="form-field full"><label>Central question</label><textarea name="centralQuestion" placeholder="What are you trying to understand or decide?">${esc(q.exploration.centralQuestion||'')}</textarea></div><div class="form-field"><label>Decision readiness</label><select name="readiness">${['Early','Developing','Ready to Decide','Decided'].map(x=>`<option ${q.exploration.readiness===x?'selected':''}>${x}</option>`).join('')}</select></div>${existing?'':`<div class="form-field full"><label>Initial tasks — one per line</label><textarea name="initialTasks" placeholder="Research the industry\nCreate resume\nContact three people"></textarea></div><div class="form-field full"><label>Supporting Habit (optional)</label><input name="habitTitle" placeholder="Apply to roles"><div class="grid three" style="margin-top:6px"><input name="habitTarget" type="number" min="1" value="10" aria-label="Habit target"><select name="habitPeriod"><option value="week">per week</option><option value="month">per month</option></select><select name="habitMeasurement"><option value="quantity">Numeric progress</option><option value="occurrences">Repeatable check-ins</option></select></div></div>`}</div></div>${modalActions(existing?`<button class="button danger" type="button" data-archive-quest="${q.id}">Archive</button>`:'<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Save Quest</button>')}</form>`,true)
}
function saveQuest(form){
  const fd=new FormData(form),existing=questById(form.dataset.id),q=normalizeQuest({...(existing||{}),id:form.dataset.id,title:String(fd.get('title')||'').trim(),area:fd.get('area'),status:fd.get('status'),topQuest:existing?.topQuest||false,manualOrder:existing?.manualOrder||activeQuests().length+1,quietUntil:existing?.quietUntil||null,outcome:{enabled:!!fd.get('outcomeEnabled'),statement:String(fd.get('outcomeStatement')||'').trim(),successCriteria:String(fd.get('successCriteria')||'').trim(),targetDate:fd.get('targetDate')||null,progress:Number(fd.get('outcomeProgress')||0),milestones:existing?.outcome?.milestones||[]},exploration:{enabled:!!fd.get('explorationEnabled'),centralQuestion:String(fd.get('centralQuestion')||'').trim(),readiness:fd.get('readiness')||'Early',entries:existing?.exploration?.entries||[]},workstreams:existing?.workstreams||[{id:uid('ws'),title:'Next Steps',order:1}],nextMoveTaskId:existing?.nextMoveTaskId||null,createdAt:existing?.createdAt||nowStamp(),updatedAt:nowStamp(),archivedAt:existing?.archivedAt||null});
  if(existing)Object.assign(existing,q);else state.quests.push(q);
  if(!existing){const lines=String(fd.get('initialTasks')||'').split(/\n/).map(x=>x.trim()).filter(Boolean);lines.forEach((title,i)=>state.tasks.push(normalizeTask({id:uid('task'),title,area:q.area,questId:q.id,track:q.exploration.enabled&&!q.outcome.enabled?'exploration':'outcome',workstreamId:q.workstreams[0]?.id||null,status:'To Do',progress:0,plannedDate:i===0?todayISO():null,dueDate:q.outcome.targetDate,importance:'Medium',urgency:'Medium',estimateMinutes:30,plannedOrder:i+1,createdAt:nowStamp(),updatedAt:nowStamp()})));q.nextMoveTaskId=lines.length?state.tasks.at(-lines.length).id:null;const ht=String(fd.get('habitTitle')||'').trim();if(ht)state.habits.push(normalizeHabit({id:uid('habit'),title:ht,area:q.area,questId:q.id,direction:'Build',measurement:fd.get('habitMeasurement'),targetValue:Number(fd.get('habitTarget')||1),unit:/role|apply/i.test(ht)?'roles':'times',period:fd.get('habitPeriod'),preferredWeekdays:[0],estimateMinutes:30,status:'Active',maturity:'Launching',health:'On Track',entries:{},occurrences:[],createdAt:nowStamp(),updatedAt:nowStamp()}))}
  state.ui.selectedQuestId=q.id;state.ui.questTab='overview';save();closeModal();toast(existing?'Quest updated':'Quest created','object_goal');render()
}
function openQuestEntry(questId,type='Idea'){const q=questById(questId);if(!q)return;showModal(`${modalHeader(`Add ${type}`,q.title)}<form id="quest-entry-form" data-id="${q.id}"><div class="modal-body"><div class="form-grid"><div class="form-field"><label>Entry type</label><select name="type">${['Question','Idea','Evidence','Experiment','Option','Decision','Insight','Note'].map(x=>`<option ${type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Decision / question status</label><select name="resolved"><option value="false">Open / developing</option><option value="true">Resolved / completed</option></select></div><div class="form-field full"><label>Entry</label><textarea name="text" required></textarea></div></div></div>${modalActions('<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Add to Quest</button>')}</form>`)}
function saveQuestEntry(form){const q=questById(form.dataset.id);if(!q)return;const fd=new FormData(form),e={id:uid('entry'),type:fd.get('type'),text:String(fd.get('text')||'').trim(),resolved:fd.get('resolved')==='true',completed:fd.get('resolved')==='true',createdAt:nowStamp(),updatedAt:nowStamp(),taskIds:[]};q.exploration.enabled=true;q.exploration.entries=[...(q.exploration.entries||[]),e];q.updatedAt=nowStamp();save();closeModal();toast(`${e.type} added`,'discovery_new');render()}
function openEntryToTask(questId,entryId){const q=questById(questId),e=q?.exploration.entries.find(x=>x.id===entryId);if(!q||!e)return;closeModal();openTaskEditor(null,{title:e.type==='Question'?`Research: ${e.text}`:e.text,area:q.area,questId:q.id,track:'exploration',workstreamId:q.workstreams[0]?.id||null,sourceEntryId:e.id})}
function openAddWorkstream(questId){const q=questById(questId);if(!q)return;showModal(`${modalHeader('Add Workstream',q.title)}<form id="workstream-form" data-id="${q.id}"><div class="modal-body"><div class="form-field"><label>Workstream name</label><input name="title" required placeholder="Research, Materials, Execution…"></div></div>${modalActions('<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Add Workstream</button>')}</form>`)}
function saveWorkstream(form){const q=questById(form.dataset.id),title=String(new FormData(form).get('title')||'').trim();if(!q||!title)return;q.workstreams=[...(q.workstreams||[]),{id:uid('ws'),title,order:q.workstreams.length+1}];q.updatedAt=nowStamp();save();closeModal();toast('Workstream added','goal_milestone');render()}
function openSelectNextMove(questId){const q=questById(questId);if(!q)return;const tasks=questTasks(q.id).filter(t=>t.status!=='Completed');showModal(`${modalHeader('Choose Next Move',q.title)}<div class="modal-body"><div class="stack">${tasks.length?tasks.map(t=>`<button class="search-result" data-set-next-move="${t.id}" data-quest="${q.id}">${img(categoryIcon(taskCategory(t)),'')}<span><strong>${esc(t.title)}</strong><small>${taskCategory(t)}${t.plannedDate?` · ${fmtDate(t.plannedDate)}`:' · Unscheduled'}</small></span><span>→</span></button>`).join(''):'<div class="empty">No open tasks. Add a task first.</div>'}</div></div>${modalActions('<button class="button ghost" data-close-modal>Cancel</button>','')}`)}
function openQuestClose(questId){const q=questById(questId);if(!q)return;showModal(`${modalHeader('Close or Pause Quest',q.title)}<div class="modal-body"><div class="stack">${[['Completed','The desired result was reached.','goal_completed'],['Stopped','You chose not to continue.','goal_released'],['Paused','Keep the Quest available but inactive.','goal_paused']].map(([status,desc,icon])=>`<button class="inbox-row" data-set-quest-status="${status}" data-quest="${q.id}">${img(icon,'')}<span><strong>${status}</strong><small>${desc}</small></span></button>`).join('')}</div><p class="muted" style="margin-top:10px">Open tasks remain visible until completed, moved, or archived.</p></div>${modalActions('<button class="button ghost" data-close-modal>Cancel</button>','')}`)}
function setQuestStatus(id,status){const q=questById(id);if(!q)return;q.status=status;q.updatedAt=nowStamp();if(status==='Completed'){state.badges.badge_questmaster=state.badges.badge_questmaster||todayISO();state.profile.xp+=150}save();closeModal();toast(`Quest ${status.toLowerCase()}`,status==='Completed'?'badge_questmaster':'goal_paused');render()}
function setTopQuest(id){state.quests.forEach(q=>q.topQuest=q.id===id?!q.topQuest:false);save();toast(questById(id)?.topQuest?'Top Quest set':'Top Quest removed','priority_act');render()}

function openHabitEditor(existing=null,defaults={}){
  const h=existing?normalizeHabit(existing):normalizeHabit({id:uid('habit'),title:defaults.title||'',area:defaults.area||'Health',questId:defaults.questId||null,direction:'Build',measurement:'occurrences',targetValue:3,unit:'times',period:'week',preferredWeekdays:[2,4,6],preferredMonthDay:15,estimateMinutes:30,status:'Active',maturity:'Seed',health:'On Track',entries:{},occurrences:[],createdAt:nowStamp(),updatedAt:nowStamp()});
  showModal(`${modalHeader(existing?'Manage Habit':'New Habit','Habits define period targets. Their generated activities appear in Today and can be moved within the period.')}<form id="habit-form" data-id="${h.id}" data-existing="${existing?'1':'0'}"><div class="modal-body"><div class="form-grid"><div class="form-field full"><label>Habit</label><input name="title" required value="${esc(h.title)}"></div><div class="form-field"><label>Life area</label><select name="area">${AREAS.map(a=>`<option ${h.area===a?'selected':''}>${a}</option>`).join('')}</select></div><div class="form-field"><label>Linked Quest</label><select name="questId"><option value="">None</option>${activeQuests().map(q=>`<option value="${q.id}" ${h.questId===q.id?'selected':''}>${esc(q.title)}</option>`).join('')}</select></div><div class="form-field"><label>Direction</label><select name="direction">${['Build','Avoid','Limit'].map(x=>`<option ${h.direction===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Measurement</label><select name="measurement"><option value="occurrences" ${h.measurement==='occurrences'?'selected':''}>Repeatable check-ins</option><option value="quantity" ${h.measurement==='quantity'?'selected':''}>Numeric progress</option></select></div><div class="form-field"><label>Target</label><input name="targetValue" type="number" min="1" value="${h.targetValue}"></div><div class="form-field"><label>Unit</label><input name="unit" value="${esc(h.unit)}"></div><div class="form-field"><label>Period</label><select name="period">${['day','week','month'].map(x=>`<option ${h.period===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Preferred month day</label><input name="preferredMonthDay" type="number" min="1" max="31" value="${h.preferredMonthDay}"></div><div class="form-field full"><label>Preferred weekdays</label><div class="checkbox-grid">${WEEKDAYS.map((d,i)=>`<label class="checkbox-tile"><input type="checkbox" name="preferredWeekdays" value="${i}" ${h.preferredWeekdays.includes(i)?'checked':''}><span>${d}</span></label>`).join('')}</div></div><div class="form-field"><label>Estimated minutes</label><input name="estimateMinutes" type="number" min="0" value="${h.estimateMinutes}"></div><div class="form-field"><label>Status</label><select name="status">${['Active','Paused'].map(x=>`<option ${h.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Maturity</label><select name="maturity">${['Seed','Launching','Forming','Stable','Strengthening','Embedded'].map(x=>`<option ${h.maturity===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Health</label><select name="health">${['On Track','Fragile','Interrupted','Recovering','Paused','Retired'].map(x=>`<option ${h.health===x?'selected':''}>${x}</option>`).join('')}</select></div></div></div>${modalActions(existing?`<button class="button danger" type="button" data-archive-habit="${h.id}">Archive</button>`:'<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Save Habit</button>')}</form>`,true)
}
function saveHabit(form){const fd=new FormData(form),existing=habitById(form.dataset.id),h=normalizeHabit({...(existing||{}),id:form.dataset.id,title:String(fd.get('title')||'').trim(),area:fd.get('area'),questId:fd.get('questId')||null,direction:fd.get('direction'),measurement:fd.get('measurement'),targetValue:Number(fd.get('targetValue')||1),unit:String(fd.get('unit')||'times'),period:fd.get('period'),preferredWeekdays:fd.getAll('preferredWeekdays').map(Number),preferredMonthDay:Number(fd.get('preferredMonthDay')||15),estimateMinutes:Number(fd.get('estimateMinutes')||0),status:fd.get('status'),maturity:fd.get('maturity'),health:fd.get('health'),entries:existing?.entries||{},occurrences:existing?.occurrences||[],periodHistory:existing?.periodHistory||{},createdAt:existing?.createdAt||nowStamp(),updatedAt:nowStamp()});if(existing)Object.assign(existing,h);else state.habits.push(h);ensureHabitOccurrences(h);save();closeModal();toast(existing?'Habit updated':'Habit created','object_habit');render()}
function openScheduleHabit(id){const h=habitById(id);if(!h)return;showModal(`${modalHeader('Schedule Habit Activity',h.title)}<form id="schedule-habit-form" data-id="${h.id}"><div class="modal-body"><div class="form-field"><label>Planned date</label><input name="date" type="date" value="${todayISO()}"></div><p class="muted">An extra occurrence may create overdelivery in the current period.</p></div>${modalActions('<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Add Activity</button>')}</form>`)}
function saveScheduleHabit(form){const h=habitById(form.dataset.id),date=new FormData(form).get('date');if(!h||!date)return;const p=periodBounds(h,date);h.occurrences=[...(h.occurrences||[]),{id:uid('occ'),periodKey:p.key,date,completedAt:null,order:h.occurrences.filter(o=>o.periodKey===p.key).length+1,moveCount:0,extra:true}];h.updatedAt=nowStamp();save();closeModal();toast('Habit activity scheduled','mode_sustain');render()}

function continueCapture(){const text=String($('#capture-text')?.value||'').trim(),type=state.ui.captureType||'Task';if(!text){toast('Write one sentence first','risk_watch');return}if(type==='Task'){openTaskEditor(null,{title:text,plannedDate:todayISO()});return}if(type==='Quest'){openQuestEditor(null,{title:text});return}if(type==='Habit'){openHabitEditor(null,{title:text});return}openIdeaNoteCapture(text)}
function openIdeaNoteCapture(text){showModal(`${modalHeader('Add Idea or Note','Attach it to a Quest whenever possible, or keep it as a standalone note.')}<form id="note-form"><div class="modal-body"><div class="form-grid"><div class="form-field full"><label>Text</label><textarea name="text" required>${esc(text)}</textarea></div><div class="form-field"><label>Type</label><select name="type">${['Idea','Question','Evidence','Option','Decision','Insight','Note','Resource'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="form-field"><label>Quest</label><select name="questId"><option value="">Standalone note</option>${activeQuests().map(q=>`<option value="${q.id}">${esc(q.title)}</option>`).join('')}</select></div></div></div>${modalActions('<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Save</button>')}</form>`)}
function saveNote(form){const fd=new FormData(form),questId=fd.get('questId')||null,n={id:uid('note'),questId,type:fd.get('type'),text:String(fd.get('text')||'').trim(),createdAt:nowStamp(),updatedAt:nowStamp()};state.notes.push(n);if(questId){const q=questById(questId);q.exploration.enabled=true;q.exploration.entries=[...(q.exploration.entries||[]),{id:n.id,type:n.type,text:n.text,createdAt:n.createdAt,taskIds:[]}];q.updatedAt=nowStamp()}save();closeModal();toast('Idea or note saved','discovery_new');render()}
function saveUncategorized(){const text=String($('#capture-text')?.value||'').trim();if(!text){toast('Write one sentence first','risk_watch');return}state.inbox.push({id:uid('inbox'),text,status:'open',createdAt:nowStamp(),updatedAt:nowStamp()});state.ui.captureTab='inbox';save();toast('Saved without category','object_inbox');render()}
function openClassifyInbox(id){const i=state.inbox.find(x=>x.id===id);if(!i)return;showModal(`${modalHeader('Classify Capture','Choose a destination.')}<div class="modal-body"><div class="notice">${img('object_inbox','')}<div><strong>${esc(i.text)}</strong><p>Captured ${fmtDate(i.createdAt.slice(0,10))}</p></div></div><div class="capture-types" style="margin-top:10px">${[['Task','object_action'],['Quest','object_goal'],['Habit','object_habit'],['Idea/Note','discovery_new']].map(([type,icon])=>`<button class="capture-type" data-classify-as="${type}" data-inbox="${i.id}">${img(icon,'')}<span><strong>${type}</strong><small>Convert while preserving the original capture.</small></span></button>`).join('')}</div></div>${modalActions('<button class="button ghost" data-close-modal>Keep in Inbox</button>','')}`)}
function classifyInbox(id,type){const i=state.inbox.find(x=>x.id===id);if(!i)return;i.status='processed';i.updatedAt=nowStamp();save();closeModal();if(type==='Task')openTaskEditor(null,{title:i.text,plannedDate:todayISO()});else if(type==='Quest')openQuestEditor(null,{title:i.text});else if(type==='Habit')openHabitEditor(null,{title:i.text});else openIdeaNoteCapture(i.text)}

function openPlanNextDays(targetDate=todayISO()){
  const horizonEnd=addDays(targetDate,Math.max(2,Number(state.settings.planningHorizonDays||7)-1));const dueSoon=openTasks().filter(t=>!t.plannedDate&&t.dueDate&&t.dueDate<=horizonEnd),resolve=openTasks().filter(t=>taskCategory(t)==='Resolve'&&!t.plannedDate),nextMoves=activeQuests().map(q=>taskById(q.nextMoveTaskId)).filter(t=>t&&t.status!=='Completed'&&!t.plannedDate),renew=openTasks().filter(t=>taskCategory(t)==='Renew/Fun'&&!t.plannedDate);const habits=activeHabits().filter(h=>{const p=periodProgress(h,targetDate);return !p.met});
  showModal(`${modalHeader('Plan Next Days','Bring forward the right mix of overdue work, deadlines, Quest progress, Habit targets, and renewal.')}<div class="modal-body"><div class="form-field"><label>Plan into date</label><input id="plan-target-date" type="date" value="${targetDate}"></div><div class="candidate-groups" style="margin-top:10px">${candidateGroup('Due Soon',dueSoon.map(t=>({type:'task',id:t.id,title:t.title,meta:`Due ${fmtDate(t.dueDate)} · ${taskCategory(t)}`})),'clock_due_soon')}${candidateGroup('Resolve',resolve.map(t=>({type:'task',id:t.id,title:t.title,meta:`${t.estimateMinutes?formatMinutes(t.estimateMinutes):'No duration'} · ${t.area}`})),'mode_resolve')}${candidateGroup('Quest Next Moves',nextMoves.map(t=>({type:'task',id:t.id,title:t.title,meta:`${questById(t.questId)?.title||'Quest'} · ${taskCategory(t)}`})),'goal_next')}${candidateGroup('Habits Due This Period',habits.map(h=>{const p=periodProgress(h,targetDate);return{type:'habit',id:h.id,title:h.title,meta:`${p.actual}/${p.target} ${h.unit} · ${p.remaining} remaining`}}),'mode_sustain')}${candidateGroup('Renew/Fun',renew.map(t=>({type:'task',id:t.id,title:t.title,meta:t.area})),'mode_renew')}</div></div>${modalActions('<button class="button ghost" data-close-modal>Done</button>','')}`,true)
}
function candidateGroup(title,items,icon){return `<section class="candidate-group"><h3><span style="display:flex;align-items:center;gap:6px">${img(icon,'')} ${esc(title)}</span><span>${items.length}</span></h3>${items.length?items.map(i=>`<div class="candidate-row"><div><strong>${esc(i.title)}</strong><small>${esc(i.meta||'')}</small></div><button class="button tiny primary" data-plan-candidate="${i.type}:${i.id}">Add</button></div>`).join(''):'<div class="muted">Nothing waiting here.</div>'}</section>`}
function planCandidate(key){const date=$('#plan-target-date')?.value||todayISO(),[type,id]=key.split(':');if(type==='task'){const t=taskById(id);if(!t)return;if(t.plannedDate!==date)t.plannedDateHistory=[...(t.plannedDateHistory||[]),{from:t.plannedDate,to:date,at:nowStamp(),reason:'Added during planning'}];t.plannedDate=date;t.plannedOrder=activeTasks().filter(x=>x.plannedDate===date).length+1;t.updatedAt=nowStamp()}else{const h=habitById(id);if(!h)return;const p=periodBounds(h,date);h.occurrences=[...(h.occurrences||[]),{id:uid('occ'),periodKey:p.key,date,completedAt:null,order:h.occurrences.filter(o=>o.periodKey===p.key).length+1,moveCount:0,extra:true}];h.updatedAt=nowStamp()}save();toast(`Added to ${fmtDate(date)}`,'clock_current');openPlanNextDays(date)}
function openAddToDate(date){showModal(`${modalHeader(`Add to ${fmtDay(date)}`,'Select an existing item or create something new.')}<div class="modal-body"><div class="stack"><button class="inbox-row" data-plan-next-date="${date}">${img('character_plan','')}<span><strong>Choose from suggestions</strong><small>Due soon, Resolve, Quest Next Moves, Habits, and Renew/Fun.</small></span></button><button class="inbox-row" data-new-task data-date="${date}">${img('object_action','')}<span><strong>New Task</strong><small>Standalone Resolve or Renew/Fun, or linked to a Quest.</small></span></button><button class="inbox-row" data-new-habit data-date="${date}">${img('object_habit','')}<span><strong>New Habit</strong><small>Define a recurring target and schedule its first activity.</small></span></button></div></div>${modalActions('<button class="button ghost" data-close-modal>Cancel</button>','')}`)}
function openHorizonModal(){showModal(`${modalHeader('Planning Horizon','Seven days is the default, not a limit.')}<div class="modal-body"><div class="grid two">${[3,7,14,30].map(n=>`<button class="button ${Number(state.settings.planningHorizonDays)===n?'primary':'ghost'}" data-set-horizon="${n}">${n} days</button>`).join('')}</div><div class="form-field" style="margin-top:12px"><label>Custom days (1–90)</label><input id="custom-horizon" type="number" min="1" max="90" value="${state.settings.planningHorizonDays}"></div></div>${modalActions('<button class="button ghost" data-close-modal>Cancel</button>','<button class="button primary" data-save-custom-horizon>Apply</button>')}`)}
function openReviewModal(){const areas=areaInsights();showModal(`${modalHeader('Complete Review','Most evidence is generated automatically. Add only the reflection that helps you choose what follows.')}<form id="review-form"><div class="modal-body"><div class="form-field"><label>What are you proud of?</label><textarea name="proud"></textarea></div><div class="form-field" style="margin-top:9px"><label>What made progress difficult?</label><select name="difficulty"><option>Capacity</option><option>Unclear next task</option><option>Waiting on someone</option><option>Low energy</option><option>Too many commitments</option><option>Unexpected urgent work</option><option>Nothing significant</option></select></div><div class="form-field" style="margin-top:9px"><label>Choose up to three proactive focus areas</label><div class="checkbox-grid">${areas.map(a=>`<label class="checkbox-tile"><input type="checkbox" name="focusAreas" value="${a.area}"><span>${a.area}</span></label>`).join('')}</div></div><div class="form-field" style="margin-top:9px"><label>What would make the next period meaningful?</label><textarea name="nextIntention"></textarea></div></div>${modalActions('<button class="button ghost" type="button" data-close-modal>Cancel</button>','<button class="button primary" type="submit">Complete Review</button>')}</form>`,true)}
function saveReview(form){const fd=new FormData(form),b=reviewPeriodBounds(),focus=fd.getAll('focusAreas').slice(0,3);state.reviews.push({id:uid('review'),start:b.start,end:b.end,date:todayISO(),proud:String(fd.get('proud')||''),difficulty:fd.get('difficulty'),focusAreas:focus,nextIntention:String(fd.get('nextIntention')||''),createdAt:nowStamp(),updatedAt:nowStamp()});state.badges.badge_campfire=state.badges.badge_campfire||todayISO();state.profile.xp+=50;save();closeModal();toast('Review completed','badge_campfire');render()}
function openAreaReview(area){const tasks=openTasks().filter(t=>t.area===area&&taskNeglect(t).score),quests=activeQuests().filter(q=>q.area===area&&questNeglect(q).reasons.length),habits=activeHabits().filter(h=>h.area===area&&habitNeglect(h).reasons.length);showModal(`${modalHeader(`${area} · Needs Focus`,'The signal is based on neglected work, not an arbitrary time-spent score.')}<div class="modal-body"><div class="stack">${tasks.map(t=>activityRow(taskActivity(t),{draggable:false})).join('')}${quests.map(q=>`<div class="notice watch">${img('scene_goal','')}<div><strong>${esc(q.title)}</strong><p>${esc(questNeglect(q).reasons.join(' · '))}</p></div><button class="button tiny primary" data-open-quest="${q.id}">Open</button></div>`).join('')}${habits.map(h=>`<div class="notice watch">${img('object_habit','')}<div><strong>${esc(h.title)}</strong><p>${esc(habitNeglect(h).reasons.join(' · '))}</p></div><button class="button tiny primary" data-open-habit="${h.id}">Open</button></div>`).join('')||'<div class="empty">No underlying item currently needs attention.</div>'}</div></div>${modalActions('<button class="button ghost" data-close-modal>Close</button>','')}`,true)}
function openSearch(){showModal(`${modalHeader('Search Questline','Find tasks, Quests, Habits, and notes without remembering where they live.')}<div class="modal-body"><div class="form-field"><label>Search</label><input id="search-input" placeholder="Type a title, Quest, area, or note…"></div><div id="search-results" class="search-results" style="margin-top:10px"><div class="empty compact">Start typing to search.</div></div></div>${modalActions('<button class="button ghost" data-close-modal>Close</button>','')}`,true)}
function updateSearch(){const q=String($('#search-input')?.value||'').trim().toLowerCase(),out=$('#search-results');if(!out)return;if(!q){out.innerHTML='<div class="empty compact">Start typing to search.</div>';return}const results=[];activeTasks().filter(t=>`${t.title} ${t.area} ${questById(t.questId)?.title||''}`.toLowerCase().includes(q)).slice(0,8).forEach(t=>results.push({type:'task',id:t.id,title:t.title,meta:`Task · ${taskCategory(t)}${t.questId?` · ${questById(t.questId)?.title}`:''}`,icon:categoryIcon(taskCategory(t))}));activeQuests().filter(x=>`${x.title} ${x.area} ${x.outcome.statement} ${x.exploration.centralQuestion}`.toLowerCase().includes(q)).slice(0,6).forEach(x=>results.push({type:'quest',id:x.id,title:x.title,meta:`Quest · ${questLabel(x)} · ${x.status}`,icon:questLabel(x)==='Exploration'?'scene_discovery':'scene_goal'}));activeHabits().filter(h=>`${h.title} ${h.area}`.toLowerCase().includes(q)).slice(0,6).forEach(h=>results.push({type:'habit',id:h.id,title:h.title,meta:`Habit · ${h.area}`,icon:'object_habit'}));state.notes.filter(n=>`${n.text} ${n.type}`.toLowerCase().includes(q)).slice(0,5).forEach(n=>results.push({type:'note',id:n.id,title:n.text,meta:`${n.type}${n.questId?` · ${questById(n.questId)?.title}`:''}`,icon:'object_reference'}));out.innerHTML=results.length?results.map(r=>`<button class="search-result" data-search-open="${r.type}:${r.id}">${img(r.icon,'')}<span><strong>${esc(r.title)}</strong><small>${esc(r.meta)}</small></span><span>→</span></button>`).join(''):'<div class="empty compact">No results.</div>'}

function snapshot(){return{appVersion:VERSION,schemaVersion:SCHEMA_VERSION,exportedAt:nowStamp(),profile:state.profile,settings:state.settings,ui:{},tasks:state.tasks,quests:state.quests,habits:state.habits,notes:state.notes,inbox:state.inbox,calendarEvents:state.calendarEvents,reviews:state.reviews,badges:state.badges,recurringAchievements:state.recurringAchievements,quietAreas:state.quietAreas,tombstones:state.tombstones,topPriorityByDate:state.topPriorityByDate}}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500)}
function exportJSON(){downloadBlob(new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'}),`questline-v4.2-${todayISO()}.json`);toast('JSON backup exported','object_reference')}
async function exportExcel(){try{if(!window.QuestlineExcel)throw new Error('Excel engine unavailable');const s=snapshot();const compat={version:3,appVersion:VERSION,schemaVersion:SCHEMA_VERSION,exportedAt:s.exportedAt,profile:s.profile,settings:s.settings,appmeta:{id:'appmeta',appVersion:VERSION,schemaVersion:SCHEMA_VERSION,updatedAt:nowStamp()},actions:s.tasks,campaigns:s.quests,habits:s.habits,captures:s.inbox,decisions:s.notes.filter(n=>n.type==='Decision'),events:s.calendarEvents,reviews:s.reviews,resources:s.notes,tombstones:s.tombstones,trash:[]};await window.QuestlineExcel.exportState(compat,`questline-v4.2-${todayISO()}.xlsx`);toast('Excel workbook exported','resources')}catch(e){toast(`Excel export failed: ${e.message}`,'risk_critical')}}
function mergeById(local,incoming){const map=new Map((local||[]).map(x=>[x.id,x]));let added=0,updated=0;for(const item of incoming||[]){if(!item?.id)continue;const cur=map.get(item.id);if(!cur){map.set(item.id,item);added++}else if(String(item.updatedAt||item.createdAt||'')>String(cur.updatedAt||cur.createdAt||'')){map.set(item.id,item);updated++}}return{items:[...map.values()],added,updated}}
function applySnapshot(incoming){const m=incoming?.schemaVersion>=SCHEMA_VERSION&&Array.isArray(incoming.tasks)?incoming:migrateLegacy(incoming,'import');if(!m)throw new Error('Unsupported Questline data');let added=0,updated=0;for(const key of ['tasks','quests','habits','notes','inbox','calendarEvents','reviews','tombstones']){const r=mergeById(state[key],m[key]);state[key]=r.items;added+=r.added;updated+=r.updated}state.badges={...state.badges,...(m.badges||{})};state.recurringAchievements={...state.recurringAchievements,...(m.recurringAchievements||{})};state.quietAreas={...state.quietAreas,...(m.quietAreas||{})};ensureState();save();render();return{added,updated}}
function recordsToSnapshot(records){const old={schemaVersion:2};for(const r of records){if(['profile','settings','appmeta'].includes(r.type))old[r.type]=r.payload;else{old[r.type]=old[r.type]||[];old[r.type].push(r.payload)}}return migrateLegacy(old,'excel-import')}
async function importFile(file){if(!file)return;try{if(file.name.toLowerCase().endsWith('.ics')){const count=parseICS(await file.text());toast(`${count} calendar events imported`,'object_event');render();return}let incoming;if(file.name.toLowerCase().endsWith('.xlsx')){const result=await window.QuestlineExcel.importState(file);incoming=recordsToSnapshot(result.records)}else incoming=JSON.parse(await file.text());const r=applySnapshot(incoming);toast(`Import complete: ${r.added} added, ${r.updated} updated`,'decision_reached')}catch(e){toast(`Import failed: ${e.message}`,'risk_critical')}}
function parseICS(text){const lines=text.replace(/\r\n[ \t]/g,'').replace(/\n[ \t]/g,'').split(/\r?\n/),events=[];let cur=null;for(const line of lines){if(line==='BEGIN:VEVENT')cur={};else if(line==='END:VEVENT'&&cur){events.push(cur);cur=null}else if(cur){const i=line.indexOf(':');if(i<0)continue;cur[line.slice(0,i).split(';')[0]]=line.slice(i+1)}}const parse=v=>{if(!v)return{date:null,time:''};const x=v.slice(0,8);return{date:`${x.slice(0,4)}-${x.slice(4,6)}-${x.slice(6,8)}`,time:v.includes('T')?`${v.slice(9,11)}:${v.slice(11,13)}`:''}};let count=0;for(const e of events){const s=parse(e.DTSTART),en=parse(e.DTEND);if(!s.date)continue;const rec={id:`ics-${e.UID||uid('cal')}`,title:(e.SUMMARY||'Calendar event').replace(/\\,/g,','),date:s.date,startTime:s.time,endTime:en.time,area:'Professional',source:'ICS snapshot'};const old=state.calendarEvents.find(x=>x.id===rec.id);old?Object.assign(old,rec):state.calendarEvents.push(rec);count++}save();return count}

function archiveTask(id){const t=taskById(id);if(!t)return;t.archivedAt=nowStamp();t.status='Archived';t.updatedAt=nowStamp();save();closeModal();toast('Task archived','decision_archived');render()}
function archiveQuest(id){const q=questById(id);if(!q)return;q.archivedAt=nowStamp();q.updatedAt=nowStamp();save();closeModal();toast('Quest archived','decision_archived');render()}
function archiveHabit(id){const h=habitById(id);if(!h)return;h.archivedAt=nowStamp();h.status='Archived';h.updatedAt=nowStamp();save();closeModal();toast('Habit archived','decision_archived');render()}
function setQuietArea(area){const until=addDays(todayISO(),30);state.quietAreas[area]=until;save();toast(`${area} quiet until ${fmtDate(until)}`,'realm_renew');render()}
function calendarToTask(id){const e=state.calendarEvents.find(x=>x.id===id);if(!e)return;openTaskEditor(null,{title:`Prepare / follow up: ${e.title}`,area:e.area,plannedDate:e.date,startTime:e.startTime,endTime:e.endTime,standaloneType:'Resolve'})}
function shiftTaskOrder(taskId,targetId){const a=taskById(taskId),b=taskById(targetId);if(!a||!b||a.plannedDate!==b.plannedDate)return;const x=a.plannedOrder;a.plannedOrder=b.plannedOrder;b.plannedOrder=x;a.updatedAt=b.updatedAt=nowStamp();save();render()}
function moveTaskToDate(taskId,date){const t=taskById(taskId);if(!t)return;if(t.plannedDate!==date)t.plannedDateHistory=[...(t.plannedDateHistory||[]),{from:t.plannedDate,to:date,at:nowStamp(),reason:'Drag to date'}];t.plannedDate=date;t.plannedOrder=activeTasks().filter(x=>x.plannedDate===date).length+1;t.updatedAt=nowStamp();save();toast(`Planned for ${fmtDate(date)}`,'clock_current');render()}
function setMatrixTask(taskId,importance,urgency){const t=taskById(taskId);if(!t)return;t.importance=importance;t.urgency=urgency;t.updatedAt=nowStamp();save();toast(`Moved to ${priorityState(t)[0]}`,'priority_plan');render()}
function setNextMove(questId,taskId){const q=questById(questId);if(!q)return;q.nextMoveTaskId=taskId;q.updatedAt=nowStamp();save();closeModal();toast('Quest Next Move selected','goal_next');render()}
function resolveQuestion(questId,entryId){const q=questById(questId),e=q?.exploration.entries.find(x=>x.id===entryId);if(!e)return;e.resolved=true;e.updatedAt=nowStamp();q.updatedAt=nowStamp();save();toast('Question marked answered','decision_reached');render()}
function enableTrack(id,track){const q=questById(id);if(!q)return;if(track==='outcome')q.outcome.enabled=true;else q.exploration.enabled=true;q.updatedAt=nowStamp();save();openQuestEditor(q)}
function unscheduleTask(id){const t=taskById(id);if(!t)return;if(t.plannedDate)t.plannedDateHistory=[...(t.plannedDateHistory||[]),{from:t.plannedDate,to:null,at:nowStamp(),reason:'Returned to Unscheduled'}];t.plannedDate=null;t.updatedAt=nowStamp();save();closeModal();toast('Task returned to Unscheduled','clock_current');render()}
function restore(kind,id){const item=kind==='quest'?questById(id):habitById(id);if(!item)return;item.archivedAt=null;if(kind==='habit')item.status='Active';item.updatedAt=nowStamp();save();toast(`${kind==='quest'?'Quest':'Habit'} restored`,'clock_recovered');render()}

function handleSearchOpen(token){const [type,id]=token.split(':');closeModal();if(type==='task'){const t=taskById(id);if(t?.questId){state.ui.returnContext={view:'tasks'};state.ui.selectedQuestId=t.questId;state.ui.questTab='tasks';state.ui.questTaskFilter=t.track==='exploration'?'Exploration':'Goal/Project';save();setView('questbook',{keepQuest:true})}else openTaskEditor(t)}else if(type==='quest'){state.ui.selectedQuestId=id;state.ui.questTab='overview';save();setView('questbook',{keepQuest:true})}else if(type==='habit'){state.ui.questbookTab='habits';save();setView('questbook');setTimeout(()=>openHabitEditor(habitById(id)),30)}else{const n=state.notes.find(x=>x.id===id);if(n?.questId){state.ui.selectedQuestId=n.questId;state.ui.questTab='explore';save();setView('questbook',{keepQuest:true})}else setView('notes')}}


