function isTaskComplete(t){return !!(t&&t.completedAt)||t?.status==='Completed'||Number(t?.progress||0)>=100}
function taskDerivedState(t,reference=todayISO()){
  if(isTaskComplete(t))return 'Done';
  if(t.dueDate&&t.dueDate<reference)return 'Overdue';
  if(t.plannedDate&&t.plannedDate<reference)return 'Missed Plan';
  if(Number(t.progress||0)>0)return 'In Progress';
  if(t.plannedDate||t.dueDate)return 'Planned';
  return 'Unscheduled';
}
function effectivePlanDate(t){
  if(!t)return null;
  if(t.plannedDate)return t.plannedDate;
  if(t.dueDate)return t.dueDate;
  if(isTaskComplete(t)&&t.completedAt)return t.completedAt.slice(0,10);
  return null;
}
function normalizeTask(t,index=0){
  const progress=Math.max(0,Math.min(100,Number(t.progress||0)));
  const completedAt=t.completedAt||(String(t.status||'').toLowerCase()==='completed'?t.updatedAt||nowStamp():progress>=100?t.updatedAt||nowStamp():null);
  return {...t,id:t.id||uid('task'),title:String(t.title||'Untitled Task'),area:t.area||'Professional',questId:t.questId||t.campaignId||null,track:t.track||(t.mode==='Explore'?'exploration':t.campaignId?'outcome':null),standaloneType:t.standaloneType||(t.mode==='Renew/Fun'?'Renew/Fun':'Resolve'),workstreamId:t.workstreamId||t.campaignSectionId||null,status:completedAt?'Completed':progress>0?'In Progress':'To Do',progress:completedAt?100:progress,plannedDate:t.plannedDate||null,startTime:t.startTime||t.start||null,endTime:t.endTime||t.end||null,dueDate:t.dueDate||t.targetDate||null,topPriority:!!t.topPriority,importance:IMPORTANCE.includes(t.importance)?t.importance:'Medium',urgency:URGENCY.includes(t.urgency)?t.urgency:'Medium',estimateMinutes:Number(t.estimateMinutes||0),plannedOrder:Number(t.plannedOrder||index+1),plannedDateHistory:Array.isArray(t.plannedDateHistory)?t.plannedDateHistory:[],dueDateHistory:Array.isArray(t.dueDateHistory)?t.dueDateHistory:[],lastProgressAt:t.lastProgressAt||null,followUpDate:t.followUpDate||null,waitingOn:t.waitingOn||'',notes:t.notes||'',sourceEntryId:t.sourceEntryId||null,completedAt,createdAt:t.createdAt||nowStamp(),updatedAt:t.updatedAt||nowStamp(),archivedAt:t.archivedAt||null};
}
function ensureState(){
  state.appVersion=VERSION;state.schemaVersion=SCHEMA_VERSION;state.updatedAt=nowStamp();
  state.tasks=(state.tasks||[]).map(normalizeTask);state.quests=(state.quests||[]).map(normalizeQuest);state.habits=(state.habits||[]).map(normalizeHabit);
  state.notes=Array.isArray(state.notes)?state.notes:[];state.inbox=Array.isArray(state.inbox)?state.inbox:[];state.calendarEvents=Array.isArray(state.calendarEvents)?state.calendarEvents:[];state.reviews=Array.isArray(state.reviews)?state.reviews:[];state.badges=state.badges||{};state.recurringAchievements=state.recurringAchievements||{};state.quietAreas=state.quietAreas||{};state.tombstones=state.tombstones||[];
  state.settings={planningHorizonDays:7,dailyCapacityMinutes:240,reviewPeriod:'week',motion:true,...(state.settings||{})};
  const oldTab=state.ui?.questbookTab;
  state.ui={view:'today',todayLens:'planned',plannerStart:todayISO(),todaySort:'manual',showCompletedToday:false,showCompletedTasks:false,showCompletedQuest:false,tasksTab:'Resolve',questbookTab:oldTab==='habits'?'habits':oldTab==='archive'?'archive':'projects',questFilter:'Active',questSort:'manual',selectedQuestId:null,questTab:'tasks',questTaskFilter:'All',captureType:'Task',captureTab:'new',reviewRange:'week',matrixCell:'High-High',taskArea:'All',questTaskTrack:'All',returnContext:null,search:'',...(state.ui||{})};
  if(state.ui.questbookTab==='quests')state.ui.questbookTab='projects';
  if(state.ui.questTab==='overview')state.ui.questTab='details';
  state.topPriorityByDate=state.topPriorityByDate||{};
  state.settings.planningHorizonDays=Math.max(1,Math.min(90,Number(state.settings.planningHorizonDays||7)));
  if(!VIEWS[state.ui.view])state.ui.view='today';
}
function questKnown(q){const list=questTasks(q.id),done=list.filter(isTaskComplete).length;return{total:list.length,done,percent:list.length?Math.round(done/list.length*100):0}}
function questExplorationMetrics(q){const entries=q.exploration?.entries||[],questions=entries.filter(e=>e.type==='Question'),decisions=entries.filter(e=>e.type==='Decision'),evidence=entries.filter(e=>['Evidence','Research'].includes(e.type)),experiments=entries.filter(e=>e.type==='Experiment'),tasks=questTasks(q.id).filter(t=>t.track==='exploration');return{questions:questions.length,answered:questions.filter(e=>e.resolved).length,evidence:evidence.length,experiments:experiments.filter(e=>e.completed).length,decisions:decisions.length,tasks:tasks.length,done:tasks.filter(isTaskComplete).length}}
function taskActivity(t){const date=effectivePlanDate(t);return{key:`task:${t.id}`,kind:'task',date,task:t,category:taskCategory(t),area:t.area,questId:t.questId,title:t.title,estimateMinutes:t.estimateMinutes||0,startTime:t.startTime||null,dueDate:t.dueDate,topPriority:state.topPriorityByDate[date]===`task:${t.id}`}}
function activitiesForDate(date,{includeCompleted=false}={}){
  const tasks=activeTasks().filter(t=>effectivePlanDate(t)===date&&(includeCompleted||!isTaskComplete(t))).map(taskActivity);
  const habits=habitOccurrenceActivities(date).filter(a=>includeCompleted||!activityCompleted(a));
  return [...tasks,...habits,...calendarActivities(date)];
}
function taskDueGroup(t){if(!t.dueDate)return'No due date';const d=dateDiff(todayISO(),t.dueDate);if(d<0)return'Overdue';if(d===0)return'Due today';if(d===1)return'Due tomorrow';if(d<=7)return'Due this week';return'Later'}
function missedPlanTasks(){return openTasks().filter(t=>t.plannedDate&&t.plannedDate<todayISO()&&(!t.dueDate||t.dueDate>=todayISO()))}
function overdueTasks(){return openTasks().filter(t=>t.dueDate&&t.dueDate<todayISO())}
function completedForDate(date){return activeTasks().filter(t=>isTaskComplete(t)&&((t.completedAt&&t.completedAt.slice(0,10)===date)||(!t.completedAt&&effectivePlanDate(t)===date))).map(t=>taskActivity({...t,plannedDate:date}))}

function activityMeta(activity){
  const category=activityCategory(activity),c=CATEGORIES[category]||CATEGORIES.Resolve,q=activityQuest(activity),pieces=[];
  pieces.push(`<span class="activity-kind ${c.class}">${img(c.icon,'')}<b>${esc(c.label)}</b></span>`);
  pieces.push(`<span class="activity-area">${img(AREA_ICONS[activity.area]||'realm_professional','')} ${esc(activity.area)}</span>`);
  if(q)pieces.push(`<button class="quest-link" data-open-quest="${q.id}" data-highlight-activity="${esc(activity.key)}">${esc(q.title)} ›</button>`);
  return pieces.join('');
}
function activitySubline(activity){
  const parts=[];
  if(activity.kind==='task'){
    const t=activity.task,derived=taskDerivedState(t);
    if(t.startTime)parts.push(`${fmtTime(t.startTime)}${t.endTime?`–${fmtTime(t.endTime)}`:''}`);else if(t.estimateMinutes)parts.push(formatMinutes(t.estimateMinutes));
    if(t.plannedDate)parts.push(`Planned ${fmtDate(t.plannedDate)}`);else if(t.dueDate)parts.push(`Due date used as plan`);
    if(t.dueDate)parts.push(`Due ${fmtDate(t.dueDate)}`);
    if(t.progress>0&&t.progress<100)parts.push(`${t.progress}%`);
    if(['Overdue','Missed Plan'].includes(derived))parts.push(derived);
    const n=taskNeglect(t);if(n.reasons.length&&parts.length<5)parts.push(n.reasons[0]);
  }else if(activity.kind==='habit'){
    const p=periodProgress(activity.habit,activity.date);parts.push(`${p.actual}/${p.target} ${activity.habit.unit}`);parts.push(`${p.percent}% this ${activity.habit.period}`);parts.push(`Ends ${fmtDate(p.end)}`);
  }else if(activity.kind==='calendar'){
    const e=activity.calendar;if(e.startTime)parts.push(`${fmtTime(e.startTime)}${e.endTime?`–${fmtTime(e.endTime)}`:''}`);parts.push(e.source||'Calendar');
  }
  return parts.join(' · ');
}
function activityRow(activity,{compact=false,draggable=true}={}){
  const category=activityCategory(activity),complete=activityCompleted(activity),progress=activityProgress(activity),neg=activity.kind==='task'?taskNeglect(activity.task):activity.kind==='habit'?habitNeglect(activity.habit,activity.date):{level:'none'},top=!!activity.topPriority;
  let control='';
  if(activity.kind==='calendar')control=`<span class="activity-check calendar-check">◷</span>`;
  else if(activity.kind==='habit'){
    const p=periodProgress(activity.habit,activity.date),quantity=activity.habit.measurement==='quantity';
    control=`<button class="activity-check habit ${complete?'checked':''}" ${quantity?`data-update-habit="${activity.habit.id}"`:`data-complete-habit="${activity.habit.id}" data-occurrence="${activity.occurrence.id}"`} aria-label="${quantity?'Update habit quantity':complete?'Undo habit occurrence':'Complete habit occurrence'}">${complete?'✓':`${p.actual}/${p.target}`}</button>`;
  }else control=`<button class="activity-check ${complete?'checked':progress>0?'progress':''}" style="--progress:${progress}%" data-complete-task="${activity.task.id}" aria-label="${complete?'Mark incomplete':'Mark complete'}">${complete?'✓':progress>0?`${progress}%`:''}</button>`;
  const star=activity.kind==='calendar'?'':`<button class="priority-star ${top?'active':''}" data-top-priority="${esc(activity.key)}" data-date="${activity.date||todayISO()}" aria-label="${top?'Remove top priority':'Set top priority'}">${top?'★':'☆'}</button>`;
  const actions=activity.kind==='calendar'?'':`<div class="activity-actions compact-actions">${activity.kind==='task'?`<button class="row-action" data-progress-task="${activity.task.id}" aria-label="Update progress" title="Update progress">↗</button>`:`<button class="row-action" data-update-habit="${activity.habit.id}" aria-label="Update habit" title="Update habit">↗</button>`}<button class="row-action" data-move-activity="${esc(activity.key)}" data-date="${activity.date}" aria-label="Change date" title="Change date">▣</button><button class="row-action" data-open-activity="${esc(activity.key)}" aria-label="More details" title="More details">⋮</button></div>`;
  return `<article class="activity-row compact-row category-${categoryClass(category)} ${complete?'completed':''} ${top?'top-priority':''} ${neg.level!=='none'?'neglected':''}" data-activity-key="${esc(activity.key)}" ${draggable&&activity.kind==='task'?`draggable="true" data-task-drag="${activity.task.id}"`:''}>${control}<div class="activity-content"><div class="activity-title-line"><span class="activity-title">${esc(activity.title)}</span>${star}</div><div class="activity-meta">${activityMeta(activity)}</div><div class="activity-subline">${esc(activitySubline(activity))}</div>${progress>0&&progress<100?`<div class="mini-progress"><span style="width:${Math.min(100,progress)}%"></span></div>`:''}</div>${actions}</article>`;
}
function completedGroup(date,items){if(!items.length)return'';return `<details class="completed-group"><summary>Completed · ${items.length}</summary><div class="activity-list">${sortActivities(items,date).map(a=>activityRow(a,{draggable:false})).join('')}</div></details>`}
function dateSection(date,activities,{title=null,subtitle='',today=false}={}){
  const open=sortActivities(activities.filter(a=>!activityCompleted(a)),date),done=sortActivities(completedForDate(date),date),mins=sum(open.map(a=>a.estimateMinutes||0));
  return `<section class="panel date-section ${today?'today-section':''}" data-date-section="${date}"><div class="date-section-head"><div><span class="eyebrow">${today?'TODAY':'PLANNED'}</span><h2>${esc(title||fmtDay(date))}</h2><p>${esc(subtitle||`${open.length} activit${open.length===1?'y':'ies'} · ${formatMinutes(mins)}`)}</p></div><div class="date-stats"><span>${open.length}</span><button class="button tiny primary" data-add-to-date="${date}">+ Add</button></div></div><div class="activity-list">${open.length?open.map(a=>activityRow(a)).join(''):'<div class="empty compact">Nothing planned.</div>'}</div>${state.ui.showCompletedToday?completedGroup(date,done):''}</section>`;
}
function overdueSection(){const list=overdueTasks().map(taskActivity);if(!list.length)return'';return `<section class="panel attention-section overdue-section"><div class="attention-head"><div><span class="eyebrow danger-text">OVERDUE · ${list.length}</span><h2>Replan before Today</h2><p>Complete, move, or break these down before adding more work.</p></div>${img('risk_critical','','small-scene-icon')}</div><div class="activity-list">${list.map(a=>activityRow(a,{draggable:false})).join('')}</div></section>`}
function missedPlanSection(){const overdueIds=new Set(overdueTasks().map(x=>x.id)),list=missedPlanTasks().filter(t=>!overdueIds.has(t.id)).map(taskActivity);if(!list.length)return'';return `<section class="panel attention-section"><div class="attention-head"><div><span class="eyebrow warning-text">MISSED PLAN · ${list.length}</span><h2>Choose a new plan</h2><p>The deadline may still be safe, but the intended work date passed.</p></div>${img('clock_repeated','','small-scene-icon')}</div><div class="activity-list">${list.map(a=>activityRow(a,{draggable:false})).join('')}</div></section>`}
function renderDueLens(){
  const groups=['Overdue','Due today','Due tomorrow','Due this week','Later','No due date'],tasks=activeTasks().filter(t=>state.ui.showCompletedToday||!isTaskComplete(t)).sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999')));
  return `<div class="stack">${groups.map(g=>{const list=tasks.filter(t=>taskDueGroup(t)===g).map(taskActivity),open=list.filter(a=>!activityCompleted(a)),done=list.filter(activityCompleted);if(!list.length)return'';return `<section class="panel date-section"><div class="date-section-head"><div><span class="eyebrow">DEADLINES</span><h2>${g}</h2><p>${open.length} open task${open.length===1?'':'s'} · planned dates stay visible</p></div><span class="date-stats"><span>${open.length}</span></span></div><div class="activity-list">${open.map(a=>activityRow(a,{draggable:false})).join('')||'<div class="empty compact">No open tasks.</div>'}</div>${state.ui.showCompletedToday?completedGroup(g,done):''}</section>`}).join('')}</div>`;
}
function renderToday(){
  ensureHabitPeriods();const dates=planningDates(),lens=state.ui.todayLens||'planned',overdue=overdueTasks().length,missed=missedPlanTasks().filter(t=>!overdueTasks().some(x=>x.id===t.id)).length,plannedCount=dates.reduce((n,d)=>n+activitiesForDate(d).filter(a=>!activityCompleted(a)).length,0);
  root.innerHTML=`<section class="planner-header"><div><span class="eyebrow">DAILY PLANNER</span><h2>${fmtDay(todayISO())}</h2><p>${plannedCount} planned · ${overdue+missed} need a decision · v${VERSION}</p></div>${img('scene_today','','planner-header-art')}</section>
  <div class="toolbar planner-toolbar"><div class="toolbar-group"><div class="segmented"><button class="${lens==='planned'?'active':''}" data-today-lens="planned">Planned Date</button><button class="${lens==='due'?'active':''}" data-today-lens="due">Due Date</button></div><select class="select-control" id="today-sort" aria-label="Sort activities"><option value="manual" ${state.ui.todaySort==='manual'?'selected':''}>Manual order</option><option value="start" ${state.ui.todaySort==='start'?'selected':''}>Start time</option><option value="due" ${state.ui.todaySort==='due'?'selected':''}>Due date</option><option value="quest" ${state.ui.todaySort==='quest'?'selected':''}>Project / Exploration</option><option value="recent" ${state.ui.todaySort==='recent'?'selected':''}>Recently updated</option></select></div><div class="toolbar-group"><button class="button ghost small" data-toggle-completed>${state.ui.showCompletedToday?'Hide completed':'Show completed'}</button><button class="button primary small" data-plan-next>Plan Next Days</button></div></div>
  <div class="date-nav compact-date-nav"><button class="date-chip" data-shift-horizon="-${state.settings.planningHorizonDays}">‹</button><button class="date-chip" data-reset-horizon>Today</button><button class="date-chip" data-shift-horizon="${state.settings.planningHorizonDays}">›</button><button class="date-chip active" data-change-horizon>${state.settings.planningHorizonDays} days</button></div>
  ${lens==='due'?renderDueLens():`<div class="stack planner-stack">${overdueSection()}${missedPlanSection()}${dates.map(d=>dateSection(d,activitiesForDate(d,{includeCompleted:state.ui.showCompletedToday}),{today:d===todayISO()})).join('')}</div>`}`;
}

function renderTasks(){
  const tab=state.ui.tasksTab||'Resolve';root.innerHTML=`<section class="planner-header"><div><span class="eyebrow">TASKS</span><h2>Open work by source</h2><p>Resolve simple obligations, advance Projects, research Explorations, or find unscheduled work.</p></div>${img('scene_priority','','planner-header-art')}</section><div class="tab-strip compact-tabs">${['Resolve','Project Tasks','Exploration Tasks','Renew/Fun','Unscheduled','Matrix'].map(x=>`<button class="tab-button ${tab===x?'active':''}" data-tasks-tab="${x}">${x}</button>`).join('')}</div><div id="tasks-content">${renderTasksTab(tab)}</div>`;
}
function renderTasksTab(tab){if(tab==='Resolve')return renderResolveTasks();if(tab==='Project Tasks'){state.ui.questTaskTrack='Goal/Project';return renderQuestTasks()}if(tab==='Exploration Tasks'){state.ui.questTaskTrack='Exploration';return renderQuestTasks()}if(tab==='Renew/Fun')return renderRenewTasks();if(tab==='Unscheduled')return renderUnscheduled();return renderMatrix()}
function renderQuestTasks(){
  const filter=state.ui.questTaskTrack||'All',area=state.ui.taskArea||'All';let list=openTasks().filter(t=>t.questId);if(filter==='Goal/Project')list=list.filter(t=>t.track!=='exploration');if(filter==='Exploration')list=list.filter(t=>t.track==='exploration');if(area!=='All')list=list.filter(t=>t.area===area);
  return `<section class="panel">${panelHead(filter==='Exploration'?'Exploration Tasks':'Project Tasks',filter==='Exploration'?'Research, tests, evidence, and decision steps across Explorations.':'Concrete next steps across active Projects.',filter==='Exploration'?'object_discovery':'object_goal','<button class="button primary small" data-open-questbook>Open Questbook</button>')}<div class="toolbar"><select class="select-control" id="task-area-filter"><option>All</option>${AREAS.map(a=>`<option ${area===a?'selected':''}>${a}</option>`).join('')}</select><button class="button ghost small" data-toggle-completed-tasks>${state.ui.showCompletedTasks?'Hide completed':'Show completed'}</button></div><div class="activity-list">${list.filter(t=>state.ui.showCompletedTasks||!isTaskComplete(t)).sort((a,b)=>String(effectivePlanDate(a)||'9999').localeCompare(String(effectivePlanDate(b)||'9999'))).map(t=>activityRow(taskActivity(t))).join('')||'<div class="empty">No tasks match this view.</div>'}</div></section>`;
}
function renderUnscheduled(){const list=openTasks().filter(t=>!t.plannedDate&&!t.dueDate);return `<section class="panel">${panelHead('Unscheduled Tasks','Tasks with neither a planned date nor a due date.','clock_current','<button class="button primary small" data-plan-next>Plan Next Days</button>')}<div class="activity-list">${list.length?list.map(t=>activityRow(taskActivity(t))).join(''):'<div class="empty">No unscheduled tasks.</div>'}</div></section>`}

function questPrimarySpace(q){return q.outcome?.enabled?'projects':'explorations'}
function renderQuestbook(){
  if(state.ui.selectedQuestId){renderQuestDetail(state.ui.selectedQuestId);return}
  const tab=state.ui.questbookTab||'projects';root.innerHTML=`<section class="planner-header"><div><span class="eyebrow">QUESTBOOK</span><h2>Projects, Explorations & Habits</h2><p>Plan defined outcomes, investigate open questions, and manage recurring targets.</p></div>${img(tab==='explorations'?'scene_discovery':tab==='habits'?'scene_habit':'scene_goal','','planner-header-art')}</section><div class="tab-strip compact-tabs">${[['projects','Projects'],['explorations','Explorations'],['habits','Habits'],['archive','Archive']].map(([k,l])=>`<button class="tab-button ${tab===k?'active':''}" data-questbook-tab="${k}">${l}</button>`).join('')}</div>${tab==='projects'?renderQuestList('projects'):tab==='explorations'?renderQuestList('explorations'):tab==='habits'?renderHabitWorkspace():renderQuestArchive()}`;
}
function renderQuestList(space='projects'){
  const filter=state.ui.questFilter||'Active',sort=state.ui.questSort||'manual';let list=activeQuests().filter(q=>space==='projects'?q.outcome.enabled:!q.outcome.enabled&&q.exploration.enabled);
  if(filter==='Active')list=list.filter(q=>['To Start','In Progress'].includes(q.status));else if(filter!=='All')list=list.filter(q=>q.status===filter);
  list.sort((a,b)=>{if(a.topQuest!==b.topQuest)return a.topQuest?-1:1;if(sort==='status')return a.status.localeCompare(b.status);if(sort==='target')return String(a.outcome.targetDate||'9999').localeCompare(String(b.outcome.targetDate||'9999'));if(sort==='progress')return (b.outcome.progress||0)-(a.outcome.progress||0);if(sort==='recent')return String(b.updatedAt).localeCompare(String(a.updatedAt));return(a.manualOrder||99)-(b.manualOrder||99)});
  const label=space==='projects'?'Projects':'Explorations',icon=space==='projects'?'object_goal':'object_discovery';
  return `<section class="panel">${panelHead(label,space==='projects'?'Defined outcomes with Tasks, milestones, and an Ideas space.':'Open questions with Ideas, evidence, and schedulable research Tasks.',icon,`<button class="button primary small" data-new-quest data-quest-kind="${space==='projects'?'project':'exploration'}">+ New ${space==='projects'?'Project':'Exploration'}</button>`)}<div class="toolbar"><div class="subfilters">${['All','Active','To Start','In Progress','Paused','Completed','Stopped'].map(x=>`<button class="chip ${filter===x?'active':''}" data-quest-filter="${x}">${x}</button>`).join('')}</div><select class="select-control" id="quest-sort"><option value="manual" ${sort==='manual'?'selected':''}>Manual order</option><option value="status" ${sort==='status'?'selected':''}>Status</option><option value="target" ${sort==='target'?'selected':''}>Target date</option><option value="progress" ${sort==='progress'?'selected':''}>Progress</option><option value="recent" ${sort==='recent'?'selected':''}>Recently updated</option></select></div><div class="quest-list compact-quest-list">${list.length?list.map(q=>questRow(q,space)).join(''):'<div class="empty">No items match this view.</div>'}</div></section>`;
}
function questRow(q,space=questPrimarySpace(q)){
  const known=questKnown(q),explore=questExplorationMetrics(q),next=taskById(q.nextMoveTaskId),neg=questNeglect(q),project=space==='projects';
  return `<article class="quest-row compact-quest-row" draggable="true" data-quest-drag="${q.id}">${img(project?'object_goal':'object_discovery','')}<div><div class="quest-row-title"><h3>${esc(q.title)}</h3><span class="quest-type ${project?'goal':'exploration'}">${project?'Project':'Exploration'}</span></div><p>${esc(q.status)} · ${esc(q.area)}${q.outcome.targetDate?` · Target ${fmtDate(q.outcome.targetDate)}`:''}</p><div class="quest-stats">${project?tag(`${q.outcome.progress}% progress`,'goal_progress','quest'):tag(`${explore.answered}/${explore.questions} questions`,'discovery_question','explore')}${tag(`${known.done}/${known.total} tasks`,'object_action')}${neg.reasons[0]?tag('Needs attention','risk_at_risk','risk'):''}</div>${next?`<p><strong>Next:</strong> ${esc(next.title)}${effectivePlanDate(next)?` · ${fmtDate(effectivePlanDate(next))}`:''}</p>`:'<p><strong>Next:</strong> Add or select a next Task</p>'}</div><div class="row-tail"><button class="quest-top ${q.topQuest?'active':''}" data-top-quest="${q.id}" aria-label="${q.topQuest?'Remove Top Quest':'Set Top Quest'}">${q.topQuest?'★':'☆'}</button><button class="button tiny primary" data-open-quest="${q.id}">Open</button></div></article>`;
}
function defaultQuestTab(q){return q.outcome?.enabled?'tasks':'explore'}
function renderQuestDetail(id){
  const q=questById(id);if(!q){state.ui.selectedQuestId=null;save();renderQuestbook();return}
  let tab=state.ui.questTab||defaultQuestTab(q);if(tab==='overview')tab='details';
  const project=q.outcome.enabled,known=questKnown(q),explore=questExplorationMetrics(q),label=project?'Project':'Exploration';
  const tabs=project?[['tasks','Tasks'],['explore','Ideas'],['details','Details']]:[['explore','Ideas'],['tasks','Tasks'],['details','Details']];
  root.innerHTML=`<section class="quest-header compact-quest-header"><div class="quest-copy"><span class="eyebrow">${label.toUpperCase()}</span><h2>${esc(q.title)}</h2><p>${esc(q.status)} · ${esc(q.area)} · ${project?`Progress ${q.outcome.progress}% · `:''}${known.done}/${known.total} Tasks${q.exploration.enabled?` · ${explore.answered}/${explore.questions} questions`:''}</p><div class="quest-header-actions"><button class="button small ghost" data-back-from-quest>← Back</button><button class="button small ${q.topQuest?'warning':'ghost'}" data-top-quest="${q.id}">${q.topQuest?'★ Top':'☆ Top'}</button><button class="button small primary" data-add-quest-task="${q.id}" data-track="${tab==='explore'?'exploration':'outcome'}">+ Task</button><button class="button small ghost" data-add-quest-entry="${q.id}">+ Idea</button></div></div>${img(project?'scene_goal':'scene_discovery','','scene')}</section><div class="tab-strip quest-tabs compact-tabs">${tabs.map(([k,l])=>`<button class="tab-button ${tab===k?'active':''}" data-quest-tab="${k}">${l}</button>`).join('')}</div>${tab==='tasks'?renderQuestTasksDetail(q):tab==='explore'?renderQuestExplore(q):renderQuestOverview(q)}`;
}
function renderQuestTasksDetail(q){
  const filter=state.ui.questTaskFilter||'All',all=questTasks(q.id),visible=filter==='All'?all:filter==='Completed'?all.filter(isTaskComplete):all.filter(t=>(filter==='Exploration')===(t.track==='exploration'));
  const streams=(q.workstreams||[]).length?q.workstreams:[{id:'unsorted',title:'Next Steps',order:1}];
  return `<div class="stack"><section class="panel">${panelHead('Tasks','Add the next step inline. Details and dates can be refined afterward.','object_action','<button class="button small ghost" data-add-workstream="'+q.id+'">+ Workstream</button>')}<div class="toolbar"><div class="subfilters">${['All','Goal/Project','Exploration','Completed'].map(x=>`<button class="chip ${filter===x?'active':''}" data-quest-task-detail-filter="${x}">${x}</button>`).join('')}</div><button class="button ghost small" data-toggle-completed-quest>${state.ui.showCompletedQuest?'Hide completed':'Show completed'}</button></div>${streams.map(ws=>{const items=visible.filter(t=>(t.workstreamId||'unsorted')===(ws.id||'unsorted')),open=items.filter(t=>!isTaskComplete(t)),done=items.filter(isTaskComplete),track=q.outcome.enabled?'outcome':'exploration';return `<section class="workstream" data-workstream-drop="${ws.id}" data-quest="${q.id}"><div class="workstream-head"><h3>${esc(ws.title)}</h3><span class="muted">${open.length} open</span></div><div class="workstream-actions activity-list">${open.map(t=>activityRow(taskActivity(t))).join('')||'<div class="empty compact">No open Tasks.</div>'}</div><form class="inline-task-form" data-quest="${q.id}" data-workstream="${ws.id}" data-track="${track}"><input name="title" placeholder="Add a Task…" autocomplete="off" aria-label="Add a Task"><button class="button small primary" type="submit">Add</button></form>${state.ui.showCompletedQuest?completedGroup(ws.id,done.map(taskActivity)):''}</section>`}).join('')}</section></div>`;
}
function renderQuestExplore(q){
  const entries=q.exploration.entries||[],groups=['Question','Idea','Evidence','Experiment','Option','Decision','Insight','Note'],metrics=questExplorationMetrics(q);
  return `<div class="stack"><section class="panel">${panelHead(q.outcome.enabled?'Ideas & Exploration':'Exploration','Capture thinking quickly, then turn useful entries into one or more schedulable Tasks.','scene_discovery')}<form class="inline-entry-form" data-quest="${q.id}"><select name="type" aria-label="Entry type">${['Idea','Question','Evidence','Experiment','Option','Decision','Insight','Note'].map(x=>`<option>${x}</option>`).join('')}</select><input name="text" placeholder="Add an idea, question, insight, or evidence…" autocomplete="off"><button class="button small primary" type="submit">Add</button></form><div class="review-summary compact-review-summary"><div class="review-metric">${img('discovery_question','')}<strong>${metrics.answered}/${metrics.questions}</strong><span>Questions</span></div><div class="review-metric">${img('discovery_evidence','')}<strong>${metrics.evidence}</strong><span>Evidence</span></div><div class="review-metric">${img('discovery_research','')}<strong>${metrics.done}/${metrics.tasks}</strong><span>Tasks</span></div><div class="review-metric">${img('decision_reached','')}<strong>${metrics.decisions}</strong><span>Decisions</span></div></div>${q.exploration.centralQuestion?`<div class="central-question"><strong>Central question</strong><p>${esc(q.exploration.centralQuestion)}</p></div>`:''}</section><div class="explore-grid">${groups.map(type=>{const list=entries.filter(e=>e.type===type);if(!list.length&&['Insight','Note','Experiment'].includes(type))return'';return `<section class="explore-section"><h3>${type}<button class="button tiny ghost" data-add-quest-entry="${q.id}" data-entry-type="${type}">+</button></h3>${list.length?list.map(e=>`<article class="entry-card"><p>${esc(e.text)}</p><div class="entry-actions"><button class="button tiny primary" data-entry-to-task="${e.id}" data-quest="${q.id}">Create Task</button>${type==='Question'&&!e.resolved?`<button class="button tiny ghost" data-resolve-question="${e.id}" data-quest="${q.id}">Answered</button>`:''}</div></article>`).join(''):'<div class="empty compact">None yet.</div>'}</section>`}).join('')}</div></div>`;
}
function renderQuestOverview(q){
  const known=questKnown(q),metrics=questExplorationMetrics(q),next=taskById(q.nextMoveTaskId);
  return `<div class="layout-2"><section class="panel">${panelHead('Details','Low-frequency Project or Exploration settings live here.','settings','<button class="button small primary" data-edit-quest="'+q.id+'">Edit</button>')}<div class="stack"><div class="detail-block"><strong>${q.outcome.enabled?'Desired outcome':'Central question'}</strong><p>${esc(q.outcome.enabled?q.outcome.statement||'Not defined':q.exploration.centralQuestion||'Not defined')}</p></div>${q.outcome.enabled?`<div class="detail-block"><strong>Progress</strong><p>${q.outcome.progress}% overall · ${known.done}/${known.total} known Tasks complete${q.outcome.targetDate?` · Target ${fmtDate(q.outcome.targetDate)}`:''}</p></div>`:''}${q.exploration.enabled?`<div class="detail-block"><strong>Exploration</strong><p>${metrics.answered}/${metrics.questions} questions answered · ${metrics.done}/${metrics.tasks} Tasks complete · ${esc(q.exploration.readiness)}</p></div>`:''}<div class="detail-block"><strong>Next Task</strong><p>${esc(next?.title||'No Next Task selected')}</p></div></div></section><aside class="panel">${panelHead('Manage','Pause, close, archive, or select the next Task.','goal_next')}<div class="stack"><button class="button primary" data-select-next-move="${q.id}">Choose Next Task</button><button class="button ghost" data-close-quest="${q.id}">Close or Pause</button><button class="button danger" data-archive-quest="${q.id}">Archive</button></div></aside></div>`;
}
function renderHabitWorkspace(){
  const list=activeHabits();return `<section class="panel">${panelHead('Habits','Define recurring targets here. The relevant occurrences appear in Today.','scene_habit','<button class="button primary small" data-new-habit>+ New Habit</button>')}<div class="habit-list">${list.length?list.map(h=>{const p=periodProgress(h),neg=habitNeglect(h);return `<article class="habit-card compact-habit-card">${img(h.direction==='Avoid'?'habit_avoid':h.direction==='Limit'?'habit_limit':'habit_build','')}<div><h3>${esc(h.title)}</h3><p>${esc(h.area)}${h.questId?` · ${esc(questById(h.questId)?.title||'Project')}`:''} · ${h.measurement==='quantity'?'Numeric':'Repeatable'} · ${p.actual}/${p.target} ${esc(h.unit)}</p><div class="habit-meter"><span style="width:${Math.min(100,p.percent)}%"></span></div><div class="habit-counters"><span>${p.percent}% this ${esc(h.period)}</span><span>${esc(h.maturity)} · ${esc(h.health)}</span>${neg.reasons[0]?`<span class="danger-text">${esc(neg.reasons[0])}</span>`:''}</div></div><div><button class="button tiny primary" data-update-habit="${h.id}">Update</button><button class="button tiny ghost" data-schedule-habit="${h.id}">+ Activity</button><button class="button tiny ghost" data-open-habit="${h.id}">Manage</button></div></article>`}).join(''):'<div class="empty">No Habits yet.</div>'}</div></section>`;
}

function renderCapture(){
  const tab=state.ui.captureTab||'new',open=state.inbox.filter(i=>i.status==='open').length;root.innerHTML=`<section class="planner-header"><div><span class="eyebrow">CAPTURE</span><h2>Add it quickly</h2><p>Choose the natural destination. Saving without a category is the rare fallback.</p></div>${img('character_capture','','planner-header-art')}</section><div class="tab-strip compact-tabs"><button class="tab-button ${tab==='new'?'active':''}" data-capture-tab="new">New</button><button class="tab-button ${tab==='inbox'?'active':''}" data-capture-tab="inbox">Inbox · ${open}</button></div>${tab==='new'?renderCaptureNew():renderInbox()}`;
}
function renderCaptureNew(){const type=state.ui.captureType||'Task';const types=[['Task','object_action','One concrete thing to do.'],['Project','object_goal','A defined outcome with several Tasks.'],['Exploration','object_discovery','A question to investigate through Ideas and Tasks.'],['Habit','object_habit','A recurring target measured by period.'],['Renew/Fun','mode_renew','A simple restorative activity.'],['Idea/Note','discovery_new','Information or an idea, preferably linked to a Project or Exploration.']];return `<section class="panel capture-box compact-capture">${panelHead('What are you capturing?','Pick a category, write one line, and continue.','object_inbox')}<textarea id="capture-text" placeholder="Write the Task, Project, Exploration, Habit, or Idea…">${esc(state.ui.captureDraft||'')}</textarea><div class="capture-types compact-capture-types">${types.map(([k,icon,desc])=>`<button class="capture-type ${type===k?'active':''}" data-capture-type="${k}">${img(icon,'')}<span><strong>${k}</strong><small>${desc}</small></span></button>`).join('')}</div><div class="capture-actions"><button class="button primary" data-continue-capture>Continue</button><button class="button ghost small" data-save-uncategorized>Save to Inbox without category</button></div></section>`}
function continueCapture(){const text=String($('#capture-text')?.value||state.ui.captureDraft||'').trim(),type=state.ui.captureType||'Task';if(!text){toast('Write one line first','risk_watch');return}state.ui.captureDraft='';save();if(type==='Task')return openTaskEditor(null,{title:text,plannedDate:todayISO(),standaloneType:'Resolve'});if(type==='Renew/Fun')return openTaskEditor(null,{title:text,plannedDate:todayISO(),standaloneType:'Renew/Fun'});if(type==='Project')return openQuestEditor(null,{title:text,kind:'project'});if(type==='Exploration')return openQuestEditor(null,{title:text,kind:'exploration'});if(type==='Habit')return openHabitEditor(null,{title:text});openIdeaNoteCapture(text)}
