function openClassifyInbox(id){const i=state.inbox.find(x=>x.id===id);if(!i)return;showModal(`${modalHeader('Classify Capture','Choose its natural destination.')}<div class="modal-body"><div class="notice">${img('object_inbox','')}<div><strong>${esc(i.text)}</strong><p>Captured ${fmtDate(i.createdAt.slice(0,10))}</p></div></div><div class="capture-types compact-capture-types" style="margin-top:10px">${[['Task','object_action'],['Project','object_goal'],['Exploration','object_discovery'],['Habit','object_habit'],['Idea/Note','discovery_new']].map(([type,icon])=>`<button class="capture-type" data-classify-as="${type}" data-inbox="${i.id}">${img(icon,'')}<span><strong>${type}</strong><small>Convert while preserving the original capture.</small></span></button>`).join('')}</div></div>${modalActions('<button class="button ghost" data-close-modal>Keep in Inbox</button>','')}`)}
