function handleSearchOpen(token){const [type,id]=token.split(':');closeModal();if(type==='task'){const t=taskById(id);if(t?.questId){const q=questById(t.questId);state.ui.returnContext={view:'tasks'};state.ui.selectedQuestId=t.questId;state.ui.questTab=t.track==='exploration'?'explore':'tasks';state.ui.questbookTab=questPrimarySpace(q);save();setView('questbook',{keepQuest:true})}else openTaskEditor(t)}else if(type==='quest'){const q=questById(id);state.ui.selectedQuestId=id;state.ui.questbookTab=questPrimarySpace(q);state.ui.questTab=defaultQuestTab(q);save();setView('questbook',{keepQuest:true})}else if(type==='habit'){state.ui.questbookTab='habits';save();setView('questbook');setTimeout(()=>openHabitEditor(habitById(id)),30)}else{const n=state.notes.find(x=>x.id===id);if(n?.questId){const q=questById(n.questId);state.ui.selectedQuestId=n.questId;state.ui.questbookTab=questPrimarySpace(q);state.ui.questTab='explore';save();setView('questbook',{keepQuest:true})}else setView('notes')}}

$('#header-add').addEventListener('click',()=>setView('capture'));
$('#mobile-add').addEventListener('click',()=>setView('capture'));
