    const p=periodProgress(activity.habit,activity.date),quantity=activity.habit.measurement==='quantity';control=`<button class="activity-check habit ${closed?'checked':''} ${skipped?'skipped':''}" ${quantity?`data-update-habit="${activity.habit.id}"`:`data-complete-habit="${activity.habit.id}" data-occurrence="${activity.occurrence.id}"`} aria-label="${quantity?'Update habit quantity':closed?'Undo habit result':'Complete habit occurrence'}">${skipped?'—':activity.occurrence?.completedAt?'✓':`${p.actual}/${p.target}`}</button>`
