function v34EntryMenu(token){const [qid,eid]=token.split(':'),q=questById(qid),entry=v34EntryById(q,eid);if(!entry)return;showModal(`${modalHeader('Entry actions',entry.type)}<div class="modal-body action-menu-list"><button data-v34-entry-edit="${token}"><span>Edit</span><b>›</b></button><button data-v34-entry-pin="${token}"><span>${entry.isPinned?'Unpin':'Pin'}</span><b>${entry.isPinned?'☆':'★'}</b></button><button data-entry-to-task="${entry.id}" data-quest="${q.id}"><span>Create Task</span><small>One Idea may create several Tasks.</small></button>${entry.archivedAt?`<button data-v34-entry-restore="${token}"><span>Restore</span><b>›</b></button>`:`<button data-v34-entry-archive="${token}"><span>Archive</span><small>Preserves linked Tasks and history.</small></button>`}<button class="destructive" data-v34-entry-delete="${token}"><span>Move to Trash</span><b>›</b></button></div><footer class="modal-actions compact-footer"><div></div><div><button class="button ghost" data-close-modal>Close</button></div></footer>`)}
