function v33OpenTodaySort(){showModal(`${modalHeader('Sort within each date','Priority is the recommended daily order. The date remains the primary grouping.')}<div class="modal-body"><div class="choice-list">${[['priority','Priority Rank'],['manual','Manual order'],['quest','Project / Exploration'],['recent','Recently updated']].map(([v,l])=>`<button class="choice-row ${state.ui.todaySort===v?'active':''}" data-set-today-sort="${v}"><strong>${l}</strong><small>${v==='priority'?'R10 first, then R9, R8, and lower ranks.':'Select this order.'}</small></button>`).join('')}</div></div>${modalActions('<button class="button ghost" data-close-modal>Close</button>','')}`)}
