renderHabitWorkspace=function(){const list=activeHabits();return `<section class="panel">${panelHead('Habits','Review the cycle and plan upcoming opportunities from the same Habit.','scene_habit','<button class="button primary small" data-new-habit>+ New Habit</button>')}<div class="habit-list">${list.length?list.map(h=>{v38DedupeHabitOccurrences(h);const p=periodProgress(h),health=v33HabitHealth(h),urg=v35HabitUrgency(h),rank=PRIORITY_RANK[`${h.importance||'Medium'}-${urg}`]||7,stats=v38PeriodStats(h),up=v33EnsureUpcomingHabitOccurrences(h,3);return `<article class="habit-card compact-habit-card rank-card-${rank}"><img src="${A[h.direction==='Avoid'?'habit_avoid':h.direction==='Limit'?'habit_limit':'habit_build']}" alt=""><div><div class="habit-card-title"><h3>${esc(h.title)}</h3><button class="v38-rank-dock" data-v38-habit-priority="${h.id}"><img src="${A[v37RankKey(rank)]}" alt=""><span>R${rank}</span></button></div><p>${esc(h.area)}${h.questId?` · ${esc(questById(h.questId)?.title||'Project')}`:''} · ${h.measurement==='quantity'?'Numeric':'Occurrence'} · ${p.actual}/${p.target} ${esc(h.unit)}</p><div class="habit-meter"><span style="width:${Math.min(100,p.percent)}%"></span></div><div class="habit-counters"><span>${p.percent}% this ${esc(h.period)}</span><span>${esc(h.maturity)} · ${esc(health.label)}</span><span>${stats.skipped.length} skipped</span></div><div class="habit-cycle-glance">${up.map(o=>`<span>${fmtDate(o.date)}</span>`).join('')}</div></div><div class="habit-card-actions">${v38HabitCardActions(h)}<button class="button tiny ghost" data-open-habit="${h.id}">Settings</button></div></article>`}).join(''):'<div class="empty">No Habits yet.</div>'}</div></section>`};

function v38RankDock(activity,rank){if(activity.kind==='calendar')return'';const attr=activity.kind==='task'?`data-v35-edit-priority="${activity.task.id}"`:`data-v38-habit-priority="${activity.habit.id}"`;return `<button class="v38-rank-dock" ${attr} aria-label="Priority rank R${rank}"><img src="${A[v37RankKey(rank)]}" alt=""><span>R${rank}</span></button>`}
function v38ActivityActions(activity,{overdue=false,missed=false}={}){
  if(activity.kind==='calendar')return `<div class="activity-actions compact-actions"><button class="row-action text-action" data-hide-calendar="${activity.calendar.id}">Hide</button></div>`;
  if(activity.kind==='habit'){
    const p=periodProgress(activity.habit,activity.date),closed=activityCompleted(activity),extra=!!activity.occurrence?.extra,skip=activity.habit.measurement==='occurrences'&&!closed&&!p.met?`<button class="row-action text-action" data-skip-habit="${activity.habit.id}" data-occurrence="${activity.occurrence.id}">Skip</button>`:'';
    return `<div class="activity-actions compact-actions">${extra&&!closed?`<button class="row-action text-action" data-complete-habit="${activity.habit.id}" data-occurrence="${activity.occurrence.id}">Complete extra</button>`:skip}<button class="row-action text-action" data-v38-move-habit="${activity.habit.id}:${activity.occurrence.id}:main">Move</button><button class="row-action" data-v38-review-habit="${activity.habit.id}" aria-label="Review Habit">⋮</button></div>`
  }
  const main=overdue||missed?`<button class="row-action text-action replan-action" data-v35-replan-task="${activity.task.id}">Replan</button>`:`<button class="row-action text-action" data-progress-task="${activity.task.id}">Progress</button><button class="row-action text-action" data-v35-replan-task="${activity.task.id}">Move</button>`;
  return `<div class="activity-actions compact-actions">${main}<button class="row-action" data-open-activity="${esc(activity.key)}" aria-label="More details">⋮</button></div>`
}
activityRow=function(activity,{compact=false,draggable=true}={}){
  const category=activityCategory(activity),closed=activityCompleted(activity),progress=activityProgress(activity),top=!!activity.topPriority,skipped=activity.kind==='habit'&&!!activity.occurrence?.skippedAt,overdue=activity.kind==='task'&&taskDerivedState(activity.task)==='Overdue',missed=activity.kind==='task'&&taskDerivedState(activity.task)==='Missed Plan',rank=v35ActivityRank(activity,activity.date);
  let control='';
  if(activity.kind==='calendar')control='<span class="activity-check calendar-check">◷</span>';
  else if(activity.kind==='habit'){const p=periodProgress(activity.habit,activity.date),quantity=activity.habit.measurement==='quantity';control=`<button class="activity-check habit ${closed?'checked':''} ${skipped?'skipped':''}" ${quantity?`data-update-habit="${activity.habit.id}"`:`data-complete-habit="${activity.habit.id}" data-occurrence="${activity.occurrence.id}"`} aria-label="${quantity?'Update habit quantity':closed?'Undo habit result':'Complete habit occurrence'}">${skipped?'—':activity.occurrence?.completedAt?'✓':`${p.actual}/${p.target}`}</button>`}
  else control=`<button class="activity-check ${closed?'checked':progress>0?'progress':''}" style="--progress:${progress}%" data-complete-task="${activity.task.id}" aria-label="${closed?'Mark incomplete':'Mark complete'}">${closed?'✓':progress>0?`${progress}%`:''}</button>`;
  const star=activity.kind==='calendar'?'':`<button class="priority-star ${top?'active':''}" data-top-priority="${esc(activity.key)}" data-date="${activity.date||todayISO()}" aria-label="${top?'Remove star':'Star activity'}">${top?'★':'☆'}</button>`;
  return `<article class="activity-row compact-row v38-activity-row category-${categoryClass(category)} rank-card-${rank} ${closed?'completed':''} ${top?'top-priority':''} ${overdue?'overdue-row':''} ${missed?'missed-row':''} ${skipped?'skipped-row':''}" data-activity-key="${esc(activity.key)}" ${draggable&&activity.kind==='task'?`draggable="true" data-task-drag="${activity.task.id}"`:''}>${control}<div class="activity-content"><div class="v38-activity-title-row"><span class="activity-title">${esc(activity.title)}</span><div class="v38-title-tools">${star}${v38RankDock(activity,rank)}</div></div><div class="activity-meta">${activityMeta(activity)}</div><div class="activity-subline rich-subline">${v34ActivitySublineHTML(activity)}</div>${progress>0&&progress<100?`<div class="mini-progress"><span style="width:${Math.min(100,progress)}%"></span></div>`:''}${v38ActivityActions(activity,{overdue,missed})}</div></article>`
};
sortActivities=function(list,date){const mode=state.ui.todaySort||'priority';return[...list].sort((a,b)=>{if(mode==='priority'){const diff=v35ActivityRank(b,date)-v35ActivityRank(a,date);if(diff)return diff;if(a.topPriority!==b.topPriority)return a.topPriority?-1:1}if(mode==='quest'){const q=String(activityQuest(a)?.title||'ZZZ').localeCompare(String(activityQuest(b)?.title||'ZZZ'));if(q)return q}if(mode==='recent'){const r=String(b.task?.updatedAt||b.habit?.updatedAt||'').localeCompare(String(a.task?.updatedAt||a.habit?.updatedAt||''));if(r)return r}const ao=a.task?.plannedOrder||a.occurrence?.order||99,bo=b.task?.plannedOrder||b.occurrence?.order||99;return ao-bo})};
renderResolveTasks=function(){const list=openTasks().filter(t=>taskCategory(t)==='Resolve'),sort=items=>items.slice().sort((a,b)=>v35PriorityRank(b)-v35PriorityRank(a)||String(effectivePlanDate(a)||'9999').localeCompare(String(effectivePlanDate(b)||'9999'))),stages={'Do Now':sort(list.filter(t=>!t.followUpDate&&!t.waitingOn&&(v35DeadlineDate(t)||effectivePlanDate(t)||v35PriorityRank(t)>=7))),'Schedule':sort(list.filter(t=>!effectivePlanDate(t)&&!v35DeadlineDate(t)&&!t.waitingOn)),'Waiting':sort(list.filter(t=>!!t.waitingOn)),'Follow Up':sort(list.filter(t=>!!t.followUpDate)),'Needs Definition':sort(list.filter(t=>!effectivePlanDate(t)&&!v35DeadlineDate(t)&&!t.notes))};return `<section class="panel">${panelHead('Resolve · Close Loops','Tasks are ordered by Priority Rank inside each stage.','mode_resolve')}${v33InlineTaskForm({standaloneType:'Resolve',placeholder:'Add a Resolve task…'})}<div class="resolve-lanes">${Object.entries(stages).map(([name,items])=>`<section class="lane" data-resolve-lane="${name}"><h3>${name}<span>${items.length}</span></h3><div class="activity-list">${items.length?items.map(t=>activityRow(taskActivity(t),{compact:true})).join(''):'<div class="empty compact">None</div>'}</div></section>`).join('')}</div></section>`};

function v38InvestigationThread(q,e){const tasks=v36ExplorationTasksForEntry(q,e).sort((a,b)=>v35PriorityRank(b)-v35PriorityRank(a)),done=tasks.filter(isTaskComplete).length,primary=e.type==='Question'&&!e.resolved?'Answer question':e.type==='Experiment'&&!e.completed?'Conclude experiment':e.type==='Option'&&!e.resolved?'Resolve option':'Add evidence';return `<article class="investigation-thread v38-investigation-thread ${e.isPinned?'pinned':''}"><header><span class="thread-type">${img(v36EntryIcon(e.type),'')} ${esc(e.type)}</span><button class="row-action" data-v34-entry-menu="${q.id}:${e.id}" aria-label="Manage entry">⋮</button></header><h3>${esc(e.text)}</h3><div class="thread-progress"><span>${done}/${tasks.length} Tasks complete</span>${e.resolved||e.completed?'<span class="status-good">Resolved</span>':''}</div>${tasks.length?`<div class="thread-task-list">${tasks.map(t=>`<div class="thread-task"><button class="mini-check ${isTaskComplete(t)?'done':''}" data-complete-task="${t.id}">${isTaskComplete(t)?'✓':'○'}</button><button data-open-task="${t.id}">${esc(t.title)}</button><button class="v38-mini-rank" data-v35-edit-priority="${t.id}">R${v35PriorityRank(t)}</button></div>`).join('')}</div>`:'<p class="v38-breakdown-prompt">Break this into one or more concrete Tasks that can be planned in Today.</p>'}<form class="v36-entry-task-form" data-quest="${q.id}" data-entry="${e.id}"><input name="title" placeholder="Add a concrete Task…" autocomplete="off"><button class="button tiny primary" type="submit">Add Task</button></form><footer>${e.type==='Question'&&!e.resolved?`<button class="button tiny ghost" data-resolve-question="${e.id}" data-quest="${q.id}">${primary}</button>`:''}<span>${tasks.length?`${tasks.length} linked Task${tasks.length===1?'':'s'}`:'No Tasks yet'}</span></footer></article>`}
renderQuestExplore=function(q){const all=v34AllEntries(q).filter(e=>!e.archivedAt),metrics=questExplorationMetrics(q),next=v36NextExplorationTask(q),readiness=v36ExplorationReadiness(metrics),threads=all.filter(e=>['Question','Experiment','Option'].includes(e.type)),support=all.filter(e=>!['Question','Experiment','Option'].includes(e.type));return `<div class="stack v38-exploration"><section class="panel exploration-overview">${panelHead('Actionable Exploration','Break broad uncertainty into Tasks, evidence, and decisions.','scene_discovery')}<div class="exploration-question"><span>Central question</span><strong>${esc(q.exploration.centralQuestion||'Define the question this Exploration should answer.')}</strong></div><div class="exploration-progress-strip"><span>${metrics.answered}/${metrics.questions} questions</span><span>${metrics.done}/${metrics.tasks} Tasks</span><span>${metrics.evidence} evidence</span><span>${esc(readiness)}</span></div><section class="next-move-card"><div><span class="eyebrow">NEXT MOVE</span>${next?`<h3>${esc(next.title)}</h3><p>${effectivePlanDate(next)?`Date ${fmtDate(effectivePlanDate(next))}`:'Unscheduled'} · R${v35PriorityRank(next)}</p>`:'<h3>No next Task defined</h3><p>Create the first concrete action for this Exploration.</p>'}</div>${next?`<div><button class="button tiny primary" data-open-task="${next.id}">Open</button><button class="button tiny ghost" data-v35-replan-task="${next.id}">Plan</button></div>`:`<button class="button small primary" data-add-quest-task="${q.id}" data-track="exploration">+ Add next Task</button>`}</section><form class="inline-entry-form v36-entry-capture" data-quest="${q.id}"><select name="type">${['Question','Idea','Evidence','Experiment','Option','Decision','Insight','Note'].map(x=>`<option>${x}</option>`).join('')}</select><input name="text" placeholder="Add a question, idea, experiment, option, or evidence…" autocomplete="off"><button class="button small primary" type="submit">Add</button></form></section><section class="investigation-list v38-investigation-list">${threads.length?threads.map(e=>v38InvestigationThread(q,e)).join(''):'<div class="panel empty compact">Add a Question, Experiment, or Option, then break it into Tasks.</div>'}</section>${support.length?`<section class="panel compact-evidence-panel">${panelHead('Ideas, Evidence & Decisions','Supporting context stays compact and can generate Tasks.','discovery_evidence')}<div class="compact-entry-list">${support.map(e=>`<article><span>${img(v36EntryIcon(e.type),'')}<b>${esc(e.type)}</b></span><p>${esc(e.text)}</p><div><button class="button tiny primary" data-entry-to-task="${e.id}" data-quest="${q.id}">Create Task</button><button class="row-action" data-v34-entry-menu="${q.id}:${e.id}">⋮</button></div></article>`).join('')}</div></section>`:''}</div>`};
