function v38ReviewInsights(summaries,b){
  const insights=[];
  const completed=completedInRange(b.start,b.end),highOpen=openTasks().filter(t=>v35PriorityRank(t)>=9),highMoved=highOpen.filter(t=>v35TaskMoveCount(t)>=3),lowCompleted=completed.filter(t=>v35PriorityRank(t)<=4),highCompleted=completed.filter(t=>v35PriorityRank(t)>=9);
  if(highOpen.length&&highCompleted.length<highOpen.length&&lowCompleted.length>highCompleted.length)insights.push({title:'Priority alignment',text:`${lowCompleted.length} lower-rank Tasks were completed while ${highOpen.length-highCompleted.length} Rank 9–10 Tasks remain open.`,action:'Protect time for one high-priority Task.'});
  if(highMoved.length)insights.push({title:'Repeated replanning',text:`${highMoved.length} high-priority Task${highMoved.length===1?' has':'s have'} been moved at least three times.`,action:'Break one down or choose a realistic date.'});
  const dormant=summaries.filter(s=>['Needs Proactive Focus','Dormant'].includes(s.status));if(dormant.length)insights.push({title:'Dormant life areas',text:`${dormant.map(s=>s.area).slice(0,3).join(', ')} ${dormant.length===1?'has':'have'} important work without enough movement.`,action:'Choose one area for proactive focus.'});
  const maintenance=summaries.filter(s=>s.status==='Maintaining');if(maintenance.length)insights.push({title:'Maintenance without advancement',text:`${maintenance.map(s=>s.area).slice(0,2).join(' and ')} ${maintenance.length===1?'is':'are'} being sustained mainly through Habits.`,action:'That can be healthy when intentional.'});
  return insights.slice(0,4)
}
const v38BaseReviewAreas=v36ReviewAreas;
