  const clear=e.target.closest('[data-v38-clear-habit]');if(clear){e.preventDefault();e.stopImmediatePropagation();const [hid,oid]=clear.dataset.v38ClearHabit.split(':');v38ClearHabitOccurrence(hid,oid);return}
  const ret=e.target.closest('[data-v38-return-habit]');if(ret){e.preventDefault();e.stopImmediatePropagation();const [hid,oid]=ret.dataset.v38ReturnHabit.split(':');v38ReturnSkippedToPlan(hid,oid);return}
  const remove=e.target.closest('[data-v38-remove-plan]');if(remove){e.preventDefault();e.stopImmediatePropagation();const [hid,oid]=remove.dataset.v38RemovePlan.split(':');v38RemoveHabitPlan(hid,oid);return}
  const move=e.target.closest('[data-v38-move-habit]');if(move){e.preventDefault();e.stopImmediatePropagation();const [hid,oid,mode='review']=move.dataset.v38MoveHabit.split(':');v38OpenHabitMove(`${hid}:${oid}`,mode);return}
  const moveDate=e.target.closest('[data-v38-habit-move-date]');if(moveDate){e.preventDefault();e.stopImmediatePropagation();const parts=moveDate.dataset.v38HabitMoveDate.split(':'),hid=parts[0],oid=parts[1],date=parts.slice(2).join(':');v38ApplyHabitMove(hid,oid,date);return}
