window.addEventListener('click',e=>{const step=e.target.closest('[data-v38-numeric-step]');if(step){e.preventDefault();e.stopImmediatePropagation();const input=step.closest('form')?.querySelector('[name="actual"]');if(input)input.value=Math.max(0,Number(input.value||0)+Number(step.dataset.v38NumericStep))}},true);
