/* Questline 3.8 duplicate handling */
completedInRange=function(start,end){return state.tasks.filter(t=>!t.archivedAt&&!t.duplicateOfTaskId&&t.status==='Completed'&&t.completedAt?.slice(0,10)>=start&&t.completedAt?.slice(0,10)<=end)};
function v38TaskLifecycleMenu(id){const t=taskById(id);if(!t)return;showModal(`${modalHeader('Task actions',t.title)}<div class="modal-body action-menu-list"><button data-v34-toggle-task-complete="${t.id}"><span>${isTaskComplete(t)?'Reopen Task':'Mark complete'}</span><b>›</b></button><button data-v34-duplicate-task="${t.id}"><span>Create a copy</span><small>Creates a new independent Task.</small></button><button data-v38-mark-duplicate="${t.id}"><span>Mark as duplicate</span><small>Removes this accidental copy from active planning.</small></button><button data-v34-archive-task="${t.id}"><span>Remove from active lists</span><small>Keeps the Task and its history.</small></button><button class="destructive" data-v34-delete-task="${t.id}"><span>Move to Trash</span><b>›</b></button></div><footer class="modal-actions compact-footer"><div></div><div><button class="button ghost" data-close-modal>Close</button></div></footer>`)}
