  return `<section class="v39-day-panel"><div><strong>${fmtDay(date)}</strong><small>${s.count?`${s.count} completion${s.count===1?'':'s'} recorded`:s.skipped.length?'Skipped opportunity':s.planned.length?'Planned opportunity':'No activity recorded'}</small></div><div class="v39-inline-actions"><button class="button tiny primary" data-v39-day-action="${h.id}|${date}|complete">${s.count?'Add another':'Complete'}</button>${s.planned.length&&!s.count?`<button class="button tiny ghost" data-v39-day-action="${h.id}|${date}|skip">Skip</button>`:''}${!s.planned.length&&!s.count?`<button class="button tiny ghost" data-v39-day-action="${h.id}|${date}|plan">Plan</button>`:''}${s.count||s.skipped.length?`<button class="button tiny ghost" data-v39-day-action="${h.id}|${date}|clear">Undo last</button>`:''}</div></section>`
