  const weekday=e.target.closest('[data-v39-weekday]');if(weekday){e.preventDefault();e.stopImmediatePropagation();const [id,day]=weekday.dataset.v39Weekday.split('|'),h=habitById(id);if(h){const set=new Set(h.preferredWeekdays||[]);weekday.checked?set.add(Number(day)):set.delete(Number(day));h.preferredWeekdays=[...set].sort((a,b)=>a-b);v39ApplyRecurrence(h,{recurrenceMode:'weekdays'})}return}
