  const od=e.target.closest('[data-v39-ordinal-day]');if(od){const h=habitById(od.dataset.v39OrdinalDay);if(h)v39ApplyRecurrence(h,{recurrenceMode:'ordinalWeekday',ordinalWeekday:Number(od.value||1)})}
