window.addEventListener('submit',e=>{const form=e.target;if(form.matches('.v39-numeric-form')){e.preventDefault();e.stopImmediatePropagation();const h=habitById(form.dataset.habit),anchor=form.dataset.anchor||todayISO(),p=h&&periodBounds(h,anchor);if(h&&p){Object.keys(h.entries||{}).filter(d=>d>=p.start&&d<=p.end).forEach(d=>delete h.entries[d]);h.entries[anchor]=Math.max(0,Number(new FormData(form).get('actual')||0));h.updatedAt=nowStamp();v38SyncHabitPeriod(h,anchor);save();v39OpenHabitCycle(h.id,anchor,'review')}return}},true);



