function v41TaskChecklist(t){const rows=v33ChecklistProgress(t);return `<section class="v41-checklist"><div class="section-title"><div><strong>Checklist</strong><small>${rows.done}/${rows.total} steps complete</small></div></div><div data-v41-checklist-list>${rows.items.map(s=>`<div class="v41-check-row" data-step-id="${s.id}"><input type="checkbox" class="v41-step-done" ${s.done?'checked':''} aria-label="Step complete"><input class="v41-step-title" value="${esc(s.title)}" placeholder="Step"><button type="button" data-v41-remove-step aria-label="Remove step">×</button></div>`).join('')}</div><div class="v41-add-step"><input data-v41-new-step placeholder="Add a step…"><button type="button" class="button tiny primary" data-v41-add-step>Add</button></div>${rows.all?'<p class="v41-all-done">All steps are done. Complete the parent Task when the overall result is finished.</p>':''}</section>`}
function v41ReadChecklist(form){return [...form.querySelectorAll('.v41-check-row')].map((row,i)=>{const title=String(row.querySelector('.v41-step-title')?.value||'').trim();if(!title)return null;const done=!!row.querySelector('.v41-step-done')?.checked;return{id:row.dataset.stepId||uid('step'),title,done,order:i+1,createdAt:row.dataset.createdAt||nowStamp(),completedAt:done?nowStamp():null}}).filter(Boolean)}

function v41TaskDateFields(t){
  if(t.dateMode==='split')return `<section class="v41-date-editor"><div class="section-title"><div><strong>Date details</strong><small>Plan work separately from the final deadline.</small></div><button type="button" class="button tiny ghost" data-v41-unify-date>Use one date</button></div><div class="v41-date-grid"><label>Plan for<input type="date" name="plannedDate" value="${t.plannedDate||''}"></label><label>Start time<input type="time" name="startTime" value="${t.startTime||''}"></label><label>Due by<input type="date" name="dueDate" value="${t.dueDate||''}"></label></div></section>`;
  return `<section class="v41-date-editor"><div class="section-title"><div><strong>Date</strong><small>Used for planning and overdue status.</small></div></div><label class="v41-single-date"><input type="date" name="date" value="${effectivePlanDate(t)||''}"></label><div class="v41-quick-dates"><button type="button" data-v41-editor-date="${todayISO()}">Today</button><button type="button" data-v41-editor-date="${addDays(todayISO(),1)}">Tomorrow</button><button type="button" data-v41-editor-date="${addDays(todayISO(),7)}">Next week</button><button type="button" data-v41-editor-date="">Clear</button></div><button type="button" class="button tiny ghost" data-v41-split-date>Add more date details</button></section>`
}
function v41TaskEditorMarkup(t,{existing=false,captureSource=false}={}){
  const q=questById(t.questId),areas=q?v41UniqueAreas(q.area,q.secondaryAreas):v41RecordAreas(t),rank=v35PriorityRank(t),duplicate=activeTasks().find(x=>x.id!==t.id&&v41TitleKey(x.title)===v41TitleKey(t.title)&&x.questId===t.questId);
  return `${modalHeader(existing?'Task Details':'New Task',v41ContextLabel(t))}<form id="${existing?'v41-task-editor':'v41-task-create'}" data-id="${t.id}" data-existing="${existing?'1':'0'}" data-capture-source="${captureSource?'1':'0'}"><input type="hidden" name="questId" value="${esc(t.questId||'')}"><input type="hidden" name="track" value="${esc(t.track||'outcome')}"><input type="hidden" name="standaloneType" value="${esc(t.standaloneType||'Resolve')}"><input type="hidden" name="workstreamId" value="${esc(t.workstreamId||'')}"><input type="hidden" name="dateMode" value="${esc(t.dateMode||'unified')}"><div class="modal-body v41-task-editor"><div class="v41-task-title-row">${existing?`<button type="button" class="activity-check ${isTaskComplete(t)?'checked':''}" data-complete-task="${t.id}" aria-label="${isTaskComplete(t)?'Reopen':'Complete'}">${isTaskComplete(t)?'✓':''}</button>`:''}<input name="title" required value="${esc(t.title==='Untitled Task'?'':t.title)}" placeholder="What needs to be done?" autocomplete="off">${existing?`<button type="button" class="priority-star ${v37IsStarred(`task:${t.id}`,effectivePlanDate(t))?'active':''}" data-top-priority="task:${t.id}" data-date="${effectivePlanDate(t)||todayISO()}" aria-label="Star Task">${v37IsStarred(`task:${t.id}`,effectivePlanDate(t))?'★':'☆'}</button><button type="button" class="row-action" data-v34-task-lifecycle="${t.id}">⋮</button>`:''}</div><div class="v41-priority-editor">${v41PrioritySelector('importance',t.importance,'Importance')}${v41PrioritySelector('urgency',t.urgency,'Urgency')}<div class="v41-rank-preview"><img src="${v41RankAsset(rank)}" alt=""><span>Priority Rank <b>R${rank}</b></span></div></div>${duplicate&&!existing?`<div class="notice watch v41-duplicate-hint">${img('risk_watch','')}<div><strong>Possible duplicate</strong><p>${esc(duplicate.title)}</p></div><button type="button" class="button tiny ghost" data-open-task="${duplicate.id}">Open</button></div>`:''}${v41TaskDateFields(t)}<label class="v41-progress-field">Progress<input type="range" name="progress" min="0" max="100" step="5" value="${Number(t.progress||0)}"><output>${Number(t.progress||0)}%</output></label>${v41TaskChecklist(t)}<details class="editor-details" ${existing&&t.notes?'open':''}><summary>Context and more details</summary><div class="v41-details-stack"><button type="button" class="v41-context-button" data-v41-context-button><span>${img(q?q.outcome?.enabled?'object_goal':'object_discovery':t.standaloneType==='Renew/Fun'?'mode_renew':'mode_resolve','')}<strong>${esc(v41ContextLabel(t))}</strong></span><b>›</b></button>${q&&v34ActiveWorkstreams(q).length?`<input type="hidden" name="workstreamId" value="${esc(t.workstreamId||'')}"><button type="button" class="v41-context-button" data-v41-workstream-button="${q.id}"><span>${img('goal_next','')}<strong>${esc(v34ActiveWorkstreams(q).find(w=>w.id===t.workstreamId)?.title||'Unassigned')}</strong></span><b>›</b></button>`:''}${v41AreaPicker(areas.primary,areas.secondary)}<label>Notes<textarea name="notes" placeholder="Optional notes">${esc(t.notes||'')}</textarea></label></div></details></div><footer class="modal-actions compact-footer"><div>${existing?'<span data-v41-save-state>Saved</span>':'<button type="button" class="button ghost" data-close-modal>Cancel</button>'}</div><div>${existing?'<button type="button" class="button primary" data-close-modal>Close</button>':'<button class="button primary" type="submit">Create Task</button>'}</div></footer></form>`
}
openTaskEditor=function(existing=null,defaults={}){
  const parent=questById(defaults.questId),draft=normalizeTask(existing||{id:uid('task'),title:defaults.title||'',area:defaults.area||parent?.area||'',secondaryAreas:defaults.secondaryAreas||parent?.secondaryAreas||[],questId:defaults.questId||null,track:defaults.track||'outcome',standaloneType:defaults.standaloneType||'Resolve',workstreamId:defaults.workstreamId||parent?.workstreams?.[0]?.id||null,dateMode:'unified',date:defaults.date||defaults.plannedDate||defaults.dueDate||null,startTime:null,progress:0,importance:defaults.importance||'Medium',urgency:defaults.urgency||'Medium',checklist:[],notes:'',createdAt:nowStamp(),updatedAt:nowStamp()});
  showModal(v41TaskEditorMarkup(draft,{existing:!!existing,captureSource:!!defaults.captureSource}),true);setTimeout(()=>document.querySelector(`#${existing?'v41-task-editor':'v41-task-create'} [name="title"]`)?.focus(),20)
};
function v41UpdateRankPreview(form){const fd=new FormData(form),rank=PRIORITY_RANK[`${fd.get('importance')||'Medium'}-${fd.get('urgency')||'Medium'}`]||1,box=form.querySelector('.v41-rank-preview');if(box){box.querySelector('img').src=v41RankAsset(rank);box.querySelector('b').textContent=`R${rank}`}}
function v41SaveTaskForm(form,{close=false}={}){
  const existing=taskById(form.dataset.id),isNew=!existing,fd=new FormData(form),title=String(fd.get('title')||'').trim();if(!title){if(isNew)toast('Task needs a title','risk_watch');return null}
  const old=existing?clone(existing):null,q=questById(fd.get('questId')||null),areas=q?v41UniqueAreas(q.area,q.secondaryAreas):v41ReadAreas(form),mode=fd.get('dateMode')||'unified',date=fd.get('date')||null,planned=fd.get('plannedDate')||null,due=fd.get('dueDate')||null,progress=Math.max(0,Math.min(100,Number(fd.get('progress')||0))),t=normalizeTask({...(existing||{}),id:form.dataset.id,title,questId:q?.id||null,track:q?(fd.get('track')||'outcome'):null,standaloneType:q?'Resolve':(fd.get('standaloneType')||'Resolve'),workstreamId:q?(fd.get('workstreamId')||null):null,area:areas.primary||(existing?existing.area:''),secondaryAreas:areas.secondary,dateMode:mode,date:mode==='unified'?date:null,plannedDate:mode==='split'?planned:date,dueDate:mode==='split'?due:date,startTime:fd.get('startTime')||null,progress,importance:fd.get('importance')||'Medium',urgency:fd.get('urgency')||'Medium',notes:String(fd.get('notes')||''),checklist:v41ReadChecklist(form),completedAt:progress>=100?(existing?.completedAt||nowStamp()):progress<100?null:existing?.completedAt,createdAt:existing?.createdAt||nowStamp(),updatedAt:nowStamp(),lastProgressAt:progress>Number(existing?.progress||0)?nowStamp():existing?.lastProgressAt||null,sourceEntryId:existing?.sourceEntryId||null});
  if(old){const oldDate=effectivePlanDate(old),newDate=effectivePlanDate(t);if(oldDate!==newDate){t.originalDate=t.originalDate||old.originalDate||oldDate||newDate;t.dateHistory=[...(old.dateHistory||[]),{from:oldDate,to:newDate,at:nowStamp(),reason:'Edited'}]}}
  if(existing)Object.assign(existing,t);else{t.plannedOrder=activeTasks().filter(x=>effectivePlanDate(x)===effectivePlanDate(t)).length+1;state.tasks.push(t)}
  if(q&&!q.nextMoveTaskId)q.nextMoveTaskId=t.id;if(q)q.updatedAt=nowStamp();save();const indicator=form.querySelector('[data-v41-save-state]');if(indicator){indicator.textContent='Saved';indicator.classList.remove('saving')}
  if(isNew){if(form.dataset.captureSource==='1')v36ClearCaptureAfterCreate();closeModal();toast('Task created',categoryIcon(taskCategory(t)));render()}else if(close){closeModal();render()}
  return t
}
function v41ScheduleTaskAutosave(form,immediate=false){if(!form||form.id!=='v41-task-editor')return;const indicator=form.querySelector('[data-v41-save-state]');if(indicator){indicator.textContent='Saving…';indicator.classList.add('saving')}clearTimeout(v41AutosaveTimer);v41AutosaveTimer=setTimeout(()=>v41SaveTaskForm(form),immediate?30:550)}

function v41ActivityMeta(activity){
  const cat=activityCategory(activity),q=activityQuest(activity),parts=[categoryTag(cat),areaTag(activity.area)];if(q)parts.push(`<button class="tag quest v41-parent-link" data-v41-open-parent="${q.id}|${activity.kind==='task'&&activity.task.track==='exploration'?'explore':'tasks'}">${esc(q.title)} ›</button>`);return parts.join('')
}
function v41ActivitySubline(activity){
  if(activity.kind==='calendar')return`${activity.calendar.startTime||''}${activity.calendar.endTime?`–${activity.calendar.endTime}`:''} · Fixed commitment`;
  if(activity.kind==='habit'){const p=periodProgress(activity.habit,activity.date),status=v39CycleStatus(activity.habit,activity.date);return`${p.actual}/${p.target} ${esc(activity.habit.unit)} · ${esc(status.label)} · ends ${fmtDate(p.end)}`}
  const t=activity.task,date=effectivePlanDate(t),parts=[];if(taskDerivedState(t)==='Overdue'){const late=Math.max(1,dateDiff(v35DeadlineDate(t),todayISO()));parts.push(`${late} day${late===1?'':'s'} overdue`)}else if(date)parts.push(`Date ${fmtDate(date)}`);if(t.dateMode==='split'&&t.dueDate)parts.push(`Due ${fmtDate(t.dueDate)}`);const moves=v41DateMoveCount(t);if(moves)parts.push(`Moved ${moves}×`);if(Number(t.progress||0)>0)parts.push(`${t.progress}%`);const c=v33Checklist(t);if(c.total)parts.push(`${c.done}/${c.total} steps`);return parts.join(' · ')
}
activityRow=function(activity,{compact=false,draggable=true}={}){
  const complete=activityCompleted(activity),rank=v35ActivityRank(activity,activity.date),top=!!activity.topPriority,overdue=activity.kind==='task'&&taskDerivedState(activity.task)==='Overdue',progress=activityProgress(activity),category=activityCategory(activity);
  let control='';
  if(activity.kind==='calendar')control=`<span class="activity-check calendar">◷</span>`;
  else if(activity.kind==='habit'){const p=periodProgress(activity.habit,activity.date);control=`<button class="activity-check habit ${complete?'checked':''}" data-v41-habit-complete="${activity.habit.id}|${activity.occurrence.id}" aria-label="${complete?'Undo Habit completion':'Complete Habit'}">${complete?'✓':activity.habit.measurement==='quantity'?`${p.actual}/${p.target}`:''}</button>`}
  else control=`<button class="activity-check ${complete?'checked':progress>0?'progress':''}" style="--progress:${progress}%" data-complete-task="${activity.task.id}" aria-label="${complete?'Reopen':'Complete'}">${complete?'✓':progress>0?`${progress}%`:''}</button>`;
  const star=activity.kind==='calendar'?'':`<button class="priority-star ${top?'active':''}" data-top-priority="${esc(activity.key)}" data-date="${activity.date||todayISO()}" aria-label="${top?'Remove star':'Star'}">${top?'★':'☆'}</button>`;
  const rankDock=activity.kind==='calendar'?'':`<button class="v41-rank-dock" ${activity.kind==='task'?`data-v41-rank-editor="${activity.task.id}"`:activity.kind==='habit'?`data-v41-habit-cycle="${activity.habit.id}|settings"`:''} aria-label="Priority rank ${rank}"><img src="${v41RankAsset(rank)}" alt=""><span>R${rank}</span></button>`;
  const actions=activity.kind==='calendar'?`<div class="activity-actions"><button class="button tiny ghost" data-hide-calendar="${activity.calendar.id}">Hide</button></div>`:activity.kind==='habit'?`<div class="activity-actions"><button class="button tiny primary" data-v41-habit-complete="${activity.habit.id}|${activity.occurrence.id}">Complete</button><button class="button tiny ghost" data-v41-habit-skip="${activity.habit.id}|${activity.occurrence.id}">Skip</button><button class="button tiny ghost" data-v41-habit-move="${activity.habit.id}|${activity.occurrence.id}">Move</button></div>`:`<div class="activity-actions"><button class="button tiny ghost" data-progress-task="${activity.task.id}">Progress</button><button class="button tiny ${overdue?'warning':'ghost'}" data-v35-replan-task="${activity.task.id}">${overdue?'Replan':'Move'}</button><button class="button tiny ghost icon-only" data-open-activity="${esc(activity.key)}" aria-label="More">⋮</button></div>`;
  return `<article class="activity-row v41-activity-row category-${categoryClass(category)} rank-card-${rank} ${complete?'completed':''} ${overdue?'overdue-card':''}" data-activity-key="${esc(activity.key)}" ${draggable&&activity.kind==='task'?`draggable="true" data-task-drag="${activity.task.id}"`:''}><div class="v41-control">${control}</div><div class="activity-content"><div class="activity-title-line"><span class="activity-title">${esc(activity.title)}</span></div><div class="activity-meta">${v41ActivityMeta(activity)}</div><div class="activity-subline">${esc(v41ActivitySubline(activity))}</div>${progress>0&&progress<100?`<div class="mini-progress"><span style="width:${Math.min(100,progress)}%"></span></div>`:''}${actions}</div><div class="v41-card-signals">${star}${rankDock}</div></article>`
}
sortActivities=function(list,date){return[...list].sort((a,b)=>{const r=v35ActivityRank(b,date)-v35ActivityRank(a,date);if(r)return r;if(a.topPriority!==b.topPriority)return a.topPriority?-1:1;const ad=String(a.dueDate||'9999'),bd=String(b.dueDate||'9999');if(ad!==bd)return ad.localeCompare(bd);const ao=a.task?.plannedOrder||a.occurrence?.order||99,bo=b.task?.plannedOrder||b.occurrence?.order||99;return ao-bo})}
function v41PriorityQueue(list,date){const flexible=sortActivities(list.filter(a=>a.kind!=='calendar'),date),calendar=list.filter(a=>a.kind==='calendar').sort((a,b)=>String(a.startTime||'99:99').localeCompare(String(b.startTime||'99:99'))),groups=['Do First','Next','Later','Not Assessed'];return `${calendar.length?`<div class="v41-fixed-block"><h3>Fixed commitments</h3>${calendar.map(a=>activityRow(a,{draggable:false})).join('')}</div>`:''}${flexible.length?`<div class="v41-priority-queue">${groups.map(group=>{const rows=flexible.filter(a=>v41PriorityBand(v35ActivityRank(a,date))===group);if(!rows.length)return'';return `<section class="v41-queue-band ${v41Slug(group)}"><header><span>${group}</span><b>${rows.length}</b></header>${rows.map(a=>activityRow(a)).join('')}</section>`}).join('')}</div>`:'<div class="empty compact">Nothing planned.</div>'}`}
function v41CompletedGroup(date,list){if(!state.ui.showCompletedToday||!list.length)return'';return `<details class="completed-group"><summary>Completed · ${list.length}</summary><div class="activity-list">${list.map(a=>activityRow(a,{draggable:false})).join('')}</div></details>`}
dateSection=function(date,activities,{title=null,subtitle='',today=false}={}){
  const open=activities.filter(a=>!activityCompleted(a)),done=activities.filter(activityCompleted),mins=sum(open.map(a=>a.estimateMinutes||0));if(!open.length&&!done.length&&!today)return'';
  return `<section class="panel date-section v41-date-section ${today?'today-section':''}" data-date-section="${date}"><div class="date-section-head"><div><span class="eyebrow">${today?'TODAY':'PLANNED'}</span><h2>${esc(title||fmtDay(date))}</h2><p>${open.length} activit${open.length===1?'y':'ies'} · ${formatMinutes(mins)}</p></div><div class="date-stats"><span>${open.length}</span><button class="button tiny primary" data-add-to-date="${date}">+ Add</button></div></div>${v41PriorityQueue(open,date)}${v41CompletedGroup(date,done)}</section>`
}
overdueSection=function(){const list=sortActivities(overdueTasks().map(taskActivity),todayISO());if(!list.length)return'';return `<section class="panel attention-section v41-overdue-section"><div class="attention-head"><div><span class="eyebrow danger-text">OVERDUE · ${list.length}</span><h2>Replan before building Today</h2><p>Past commitments stay here until completed or given a realistic new date.</p></div>${img('risk_critical','','small-scene-icon')}</div><div class="activity-list">${list.map(a=>activityRow(a,{draggable:false})).join('')}</div></section>`}
