function v41OpenHabitCycle(id,anchor=state.ui.habitReviewDate||todayISO(),tab=state.ui.habitCycleTab||'review'){const h=habitById(id);if(!h)return;state.ui.habitReviewDate=anchor;state.ui.habitCycleTab=tab;ensureHabitOccurrences(h,anchor);v39EnsureUpcoming(h,3);v38DedupeHabitOccurrences(h);save();const content=tab==='plan'?v41HabitPlanView(h,anchor):tab==='settings'?v41HabitSettingsView(h):v41HabitReviewView(h,anchor);showModal(`${modalHeader(`${tab==='plan'?'Plan':tab==='settings'?'Habit settings':'Review'} ${h.period}`,h.title)}<div class="modal-body v41-habit-cycle"><div class="v41-cycle-tabs"><button class="${tab==='review'?'active':''}" data-v41-habit-cycle="${h.id}|review">Review</button><button class="${tab==='plan'?'active':''}" data-v41-habit-cycle="${h.id}|plan">Plan</button><button class="${tab==='settings'?'active':''}" data-v41-habit-cycle="${h.id}|settings">Settings</button></div><div class="v41-period-nav"><button class="button tiny ghost" data-v41-shift-cycle="${h.id}|-1">‹ Previous</button><strong>${esc(v36PeriodName(h,anchor))}</strong><button class="button tiny ghost" data-v41-shift-cycle="${h.id}|1">Next ›</button></div>${content}</div><footer class="modal-actions compact-footer"><div><span>Changes save automatically</span></div><div><button class="button primary" data-close-modal>Done</button></div></footer>`,true)}
function v41RecordHabitCompletion(hid,date){const h=habitById(hid);if(!h)return;const p=periodBounds(h,date),before=periodProgress(h,date),open=(h.occurrences||[]).filter(o=>o.periodKey===p.key&&!o.completedAt&&!o.skippedAt&&!o.notRequiredAt&&!o.extra).sort((a,b)=>Math.abs(dateDiff(a.date,date))-Math.abs(dateDiff(b.date,date)));let o=open[0];if(!o){o={id:uid('occ'),periodKey:p.key,date,originalDate:date,completedAt:null,completedDate:null,skippedAt:null,notRequiredAt:null,extra:before.met,systemGenerated:false,moveCount:0,order:(h.occurrences||[]).length+1,sequenceNumber:(h.occurrences||[]).length+1};h.occurrences.push(o)}o.completedAt=nowStamp();o.completedDate=date;o.skippedAt=null;o.notRequiredAt=null;if(before.met)o.extra=true;h.entries[date]=Number(h.entries[date]||0)+1;v38SyncHabitPeriod(h,date);save();toast(`${h.title}: ${periodProgress(h,date).actual}/${periodProgress(h,date).target}`,'occurrence_completed');v41OpenHabitCycle(hid,state.ui.habitReviewDate||date,'review')}
function v41SkipHabitOccurrence(hid,oid){const h=habitById(hid),o=h?.occurrences.find(x=>x.id===oid);if(!h||!o)return;o.skippedAt=nowStamp();o.completedAt=null;o.completedDate=null;h.updatedAt=nowStamp();v38SyncHabitPeriod(h,o.date);save();toast('Opportunity skipped','occurrence_skipped');v41OpenHabitCycle(hid,state.ui.habitReviewDate||o.date,'review')}
function v41MoveHabitOccurrence(hid,oid,date,scope='one'){const h=habitById(hid),o=h?.occurrences.find(x=>x.id===oid);if(!h||!o||!date)return;const old=o.date;o.originalDate=o.originalDate||old;o.date=date;o.periodKey=periodBounds(h,date).key;o.moveCount=Number(o.moveCount||0)+1;o.systemGenerated=false;if(scope==='future'){if(h.period==='week'){const oldDay=new Date(`${old}T12:00:00`).getDay(),newDay=new Date(`${date}T12:00:00`).getDay();h.preferredWeekdays=(h.preferredWeekdays||[]).map(d=>d===oldDay?newDay:d)}else if(h.period==='month'){h.recurrenceMode='fixedDay';h.preferredMonthDay=new Date(`${date}T12:00:00`).getDate()}v39RegenerateFuture(h,date)}v38DedupeHabitOccurrences(h);save();toast(`Moved to ${fmtDate(date)}`,'action_move');v41OpenHabitCycle(hid,state.ui.habitReviewDate||date,'plan')}
function v41HabitDateSheet(hid,oid=null,mode='move'){const h=habitById(hid);if(!h)return;v41Subsheet(`<header><div><span class="eyebrow">${mode==='record'?'RECORD COMPLETION':'MOVE OPPORTUNITY'}</span><h3>${esc(h.title)}</h3></div><button class="icon-button" data-v41-close-subsheet>×</button></header><div class="v41-quick-date-list">${[['Today',todayISO()],['Yesterday',addDays(todayISO(),-1)],['Tomorrow',addDays(todayISO(),1)],['Next week',addDays(todayISO(),7)]].map(([label,date])=>`<button data-v41-habit-date-choice="${hid}|${oid||''}|${mode}|${date}"><span>${label}</span><small>${fmtDate(date)}</small></button>`).join('')}<label>Pick a date<input type="date" value="${todayISO()}" data-v41-habit-date-picker="${hid}|${oid||''}|${mode}"></label>${mode==='move'?`<fieldset><legend>Apply to</legend><label><input type="radio" name="v41-habit-scope" value="one" checked> This occurrence only</label><label><input type="radio" name="v41-habit-scope" value="future"> This and future occurrences</label></fieldset>`:''}</div>`)}

function v41ProjectOverview(q){const known=questKnown(q),next=taskById(q.nextMoveTaskId),milestones=q.outcome?.milestones||[],open=questTasks(q.id).filter(t=>!isTaskComplete(t)),habits=activeHabits().filter(h=>h.questId===q.id);return `<div class="stack"><section class="panel v41-quest-overview">${panelHead('Project Overview','Outcome, milestones, next move, and supporting rhythm.','scene_goal')}<div class="v41-outcome"><span>Outcome</span><strong>${esc(q.outcome?.statement||'Define what complete looks like.')}</strong></div><div class="v41-project-metrics"><div><b>${q.outcome?.progress||0}%</b><span>Overall</span></div><div><b>${milestones.filter(m=>m.done).length}/${milestones.length}</b><span>Milestones</span></div><div><b>${known.done}/${known.total}</b><span>Known Tasks</span></div><div><b>${habits.length}</b><span>Habits</span></div></div><section class="next-move-card"><div><span class="eyebrow">NEXT MOVE</span><h3>${esc(next?.title||'No next Task defined')}</h3><p>${next?`${effectivePlanDate(next)?`Date ${fmtDate(effectivePlanDate(next))}`:'Unscheduled'} · R${v35PriorityRank(next)}`:'Choose or add one concrete Task.'}</p></div>${next?`<button class="button small primary" data-open-task="${next.id}">Open</button>`:`<button class="button small primary" data-add-quest-task="${q.id}" data-track="outcome">+ Add Task</button>`}</section></section><section class="panel">${panelHead('Milestones & Workstreams','Break the outcome into stages, then into Tasks.','goal_milestone')}<div class="v41-milestones">${milestones.map(m=>`<span class="${m.done?'done':''}">${m.done?'✓':'○'} ${esc(m.title)}</span>`).join('')||'<span>No milestones defined yet.</span>'}</div><div class="v41-workstream-summary">${v34ActiveWorkstreams(q).map(w=>{const tasks=questTasks(q.id).filter(t=>t.workstreamId===w.id),done=tasks.filter(isTaskComplete).length;return `<button data-v41-jump-workstream="${q.id}|${w.id}"><strong>${esc(w.title)}</strong><small>${done}/${tasks.length} Tasks</small></button>`}).join('')}</div></section></div>`}
function v41ProjectPlan(q){const workstreams=v34ActiveWorkstreams(q),unassigned=questTasks(q.id).filter(t=>!t.workstreamId),sections=[...workstreams.map(w=>({id:w.id,title:w.title,tasks:questTasks(q.id).filter(t=>t.workstreamId===w.id)})),...(unassigned.length?[{id:'',title:'Unassigned',tasks:unassigned}]:[])];return `<div class="stack"><section class="panel">${panelHead('Project Plan','Add, sort, and plan concrete Tasks by workstream.','object_goal','<button class="button small ghost" data-v34-manage-workstreams="'+q.id+'">Manage workstreams</button>')}<div class="v41-plan-progress"><span>${questKnown(q).done}/${questKnown(q).total} Tasks complete</span><span>${q.outcome?.progress||0}% overall</span></div></section>${sections.map(s=>`<section class="panel v41-workstream" data-workstream="${s.id}"><header><div><h3>${esc(s.title)}</h3><small>${s.tasks.filter(t=>!isTaskComplete(t)).length} open</small></div>${s.id?`<button class="row-action" data-v34-workstream-menu="${q.id}:${s.id}">⋮</button>`:''}</header><div class="activity-list">${s.tasks.filter(t=>state.ui.showCompletedQuest||!isTaskComplete(t)).sort((a,b)=>v35PriorityRank(b)-v35PriorityRank(a)||a.plannedOrder-b.plannedOrder).map(t=>activityRow(taskActivity(t))).join('')||'<div class="empty compact">No open Tasks.</div>'}</div><form class="inline-task-form" data-quest="${q.id}" data-track="outcome" data-workstream="${s.id}"><input name="title" placeholder="Add a Task…" autocomplete="off"><button class="button tiny primary" type="submit">Add</button></form></section>`).join('')}</div>`}
function v41ExplorationNextSteps(q){const tasks=questTasks(q.id).filter(t=>t.track==='exploration'&&!isTaskComplete(t)).sort((a,b)=>v35PriorityRank(b)-v35PriorityRank(a)||String(effectivePlanDate(a)||'9999').localeCompare(String(effectivePlanDate(b)||'9999'))),next=v36NextExplorationTask(q),metrics=questExplorationMetrics(q);return `<div class="stack"><section class="panel v41-exploration-overview">${panelHead('Exploration Next Steps','Turn open questions into concrete, schedulable Tasks.','scene_discovery')}<div class="exploration-question"><span>Central question</span><strong>${esc(q.exploration?.centralQuestion||'Define the question this Exploration should answer.')}</strong></div><div class="exploration-progress-strip"><span>${metrics.answered}/${metrics.questions} questions</span><span>${metrics.done}/${metrics.tasks} Tasks</span><span>${metrics.evidence} evidence</span><span>${esc(v36ExplorationReadiness(metrics))}</span></div><section class="next-move-card"><div><span class="eyebrow">NEXT MOVE</span><h3>${esc(next?.title||'No next Task defined')}</h3><p>${next?`${effectivePlanDate(next)?`Date ${fmtDate(effectivePlanDate(next))}`:'Unscheduled'} · R${v35PriorityRank(next)}`:'Add one concrete research or decision step.'}</p></div>${next?`<button class="button small primary" data-open-task="${next.id}">Open</button>`:`<button class="button small primary" data-add-quest-task="${q.id}" data-track="exploration">+ Add Task</button>`}</section></section><section class="panel">${panelHead('Open Exploration Tasks','These appear normally in Today and contribute evidence or decisions.','discovery_step')}<form class="inline-task-form" data-quest="${q.id}" data-track="exploration" data-workstream="${q.workstreams?.[0]?.id||''}"><input name="title" placeholder="Add a research or exploration Task…"><button class="button tiny primary" type="submit">Add</button></form><div class="activity-list">${tasks.map(t=>activityRow(taskActivity(t))).join('')||'<div class="empty compact">No open Exploration Tasks.</div>'}</div></section></div>`}
function v41Investigation(q){const entries=v34AllEntries(q).filter(e=>!e.archivedAt&&!e.deletedAt),threads=entries.filter(e=>['Question','Experiment','Option'].includes(e.type)),support=entries.filter(e=>!['Question','Experiment','Option'].includes(e.type));return `<div class="stack"><section class="panel">${panelHead('Investigation','Questions, experiments, and options each generate concrete Tasks.','discovery_question')}<form class="inline-entry-form v36-entry-capture" data-quest="${q.id}"><select name="type"><option>Question</option><option>Experiment</option><option>Option</option><option>Idea</option><option>Evidence</option><option>Decision</option></select><input name="text" placeholder="Add a question, experiment, option, or evidence…"><button class="button small primary" type="submit">Add</button></form></section><div class="v41-investigation-list">${threads.map(e=>v36InvestigationThread(q,e)).join('')||'<section class="panel empty compact">Add a Question, Experiment, or Option, then break it into Tasks.</section>'}</div>${support.length?`<section class="panel">${panelHead('Ideas, Evidence & Decisions','Supporting context remains compact and actionable.','discovery_evidence')}<div class="compact-entry-list">${support.map(e=>`<article><span>${img(v36EntryIcon(e.type),'')}<b>${esc(e.type)}</b></span><p>${esc(e.text)}</p><div><button class="button tiny primary" data-entry-to-task="${e.id}" data-quest="${q.id}">Create Task</button><button class="row-action" data-v34-entry-menu="${q.id}:${e.id}">⋮</button></div></article>`).join('')}</div></section>`:''}</div>`}
renderQuestList=function(space='projects'){const filter=state.ui.questFilter||'Active',sort=state.ui.questSort||'manual';let list=activeQuests().filter(q=>space==='projects'?q.outcome?.enabled:!q.outcome?.enabled&&q.exploration?.enabled);if(filter==='Active')list=list.filter(q=>['To Start','In Progress'].includes(q.status));else if(filter!=='All')list=list.filter(q=>q.status===filter);list.sort((a,b)=>{if(a.topQuest!==b.topQuest)return a.topQuest?-1:1;if(sort==='target')return String(a.outcome?.targetDate||'9999').localeCompare(String(b.outcome?.targetDate||'9999'));if(sort==='progress')return Number(b.outcome?.progress||0)-Number(a.outcome?.progress||0);if(sort==='recent')return String(b.updatedAt).localeCompare(String(a.updatedAt));return Number(a.manualOrder||99)-Number(b.manualOrder||99)});return `<section class="panel">${panelHead(space==='projects'?'Projects':'Explorations',space==='projects'?'Defined outcomes broken into milestones, workstreams, Tasks, and Habits.':'Open questions broken into research Tasks, evidence, options, and decisions.',space==='projects'?'object_goal':'object_discovery',`<button class="button primary small" data-new-quest data-quest-kind="${space==='projects'?'project':'exploration'}">+ New ${space==='projects'?'Project':'Exploration'}</button>`)}<div class="v41-quest-toolbar"><div class="subfilters">${['All','Active','To Start','In Progress','Paused','Completed'].map(x=>`<button class="chip ${filter===x?'active':''}" data-quest-filter="${x}">${x}</button>`).join('')}</div></div><div class="quest-list compact-quest-list">${list.length?list.map(q=>questRow(q,space)).join(''):'<div class="empty">No items match this view.</div>'}</div></section>`}
renderQuestDetail=function(id){const q=questById(id);if(!q)return;const project=!!q.outcome?.enabled,allowed=project?['overview','tasks','explore']:['tasks','explore','details'],tab=allowed.includes(state.ui.questTab)?state.ui.questTab:(project?'overview':'tasks'),tabs=project?[['overview','Overview'],['tasks','Plan'],['explore','Ideas']]:[['tasks','Next Steps'],['explore','Investigation'],['details','History']];root.innerHTML=`<section class="quest-header compact-quest-header"><div class="quest-copy"><span class="eyebrow">${project?'PROJECT':'EXPLORATION'}</span><h2>${esc(q.title)}</h2><p>${esc(q.status)} · ${esc(q.area)}${q.secondaryAreas?.length?` + ${q.secondaryAreas.length} shared`:''} · ${questKnown(q).done}/${questKnown(q).total} Tasks</p><div class="quest-header-actions"><button class="button small ghost" data-back-from-quest>← Back</button><button class="button small ${q.topQuest?'warning':'ghost'}" data-top-quest="${q.id}">${q.topQuest?'★ Top':'☆ Top'}</button><button class="button small primary" data-add-quest-task="${q.id}" data-track="${project?'outcome':'exploration'}">+ Task</button><button class="button small ghost" data-add-quest-entry="${q.id}">+ Idea</button></div></div>${img(project?'scene_goal':'scene_discovery','','scene')}</section><div class="tab-strip quest-tabs compact-tabs">${tabs.map(([k,l])=>`<button class="tab-button ${tab===k?'active':''}" data-quest-tab="${k}">${l}</button>`).join('')}</div>${project?(tab==='overview'?v41ProjectOverview(q):tab==='tasks'?v41ProjectPlan(q):v41Investigation(q)):(tab==='tasks'?v41ExplorationNextSteps(q):tab==='explore'?v41Investigation(q):v36ExplorationHistory(q))}`}

function v41WeekStart(date=todayISO(),offset=0){const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()-((d.getDay()+6)%7)+offset*7);return localDateISO(d)}
function v41ActivityEvents(start,end,area='All'){
  const events=[];
  state.tasks.filter(t=>!t.archivedAt&&!t.deletedAt&&!t.duplicateOfTaskId&&t.completedAt).forEach(t=>{const d=String(t.completedAt).slice(0,10);if(d<start||d>end)return;if(area!=='All'&&!v36AllAreas(t).includes(area))return;events.push({date:d,type:taskCategory(t),importance:t.importance,urgency:t.urgency,rank:v35PriorityRank(t),area:t.area,title:t.title,kind:'task'})});
  activeHabits().forEach(h=>{Object.entries(h.entries||{}).forEach(([d,count])=>{if(d<start||d>end)return;if(area!=='All'&&!v36AllAreas(h).includes(area))return;for(let i=0;i<Number(count||0);i++){const urg=v35HabitUrgency(h,d),rank=PRIORITY_RANK[`${h.importance||'Medium'}-${urg}`]||7;events.push({date:d,type:'Habit',importance:h.importance||'Medium',urgency:urg,rank,area:h.area,title:h.title,kind:'habit'})}})});
  return events
}
function v41WeeklySeries(weeks=8,area='All'){
  return Array.from({length:weeks},(_,i)=>{const offset=i-(weeks-1),start=v41WeekStart(todayISO(),offset),end=addDays(start,6),events=v41ActivityEvents(start,end,area);return{start,end,label:`${fmtDate(start)}–${fmtDate(end)}`,events,total:events.length,priority:sum(events.map(e=>e.rank)),importance:{High:events.filter(e=>e.importance==='High').length,Medium:events.filter(e=>e.importance==='Medium').length,Low:events.filter(e=>e.importance==='Low').length},urgency:{High:events.filter(e=>e.urgency==='High').length,Medium:events.filter(e=>e.urgency==='Medium').length,Low:events.filter(e=>e.urgency==='Low').length},type:{Resolve:events.filter(e=>e.type==='Resolve').length,Project:events.filter(e=>e.type==='Goal/Project').length,Exploration:events.filter(e=>e.type==='Exploration').length,Habit:events.filter(e=>e.type==='Habit').length,'Renew/Fun':events.filter(e=>e.type==='Renew/Fun').length}}})
}
function v41ChartValue(row,metric){return metric==='priority'?row.priority:row.total}
const V41_CHART_COLORS={High:'#d25545',Medium:'#e5aa37',Low:'#6a9d5c',Resolve:'#d88c24',Project:'#3e8cc5',Exploration:'#8060b0',Habit:'#4f9c57','Renew/Fun':'#b85f82'};
function v41TrendChart(){const metric=state.ui.reviewChartMetric||'completed',weeks=Number(state.ui.reviewChartWeeks||8),area=state.ui.reviewAreaFilter||'All',series=v41WeeklySeries(weeks,area),max=Math.max(1,...series.map(r=>metric==='priority'?r.priority:r.total));const stacked=metric==='importance'?['High','Medium','Low']:metric==='urgency'?['High','Medium','Low']:metric==='type'?['Resolve','Project','Exploration','Habit','Renew/Fun']:null;return `<section class="panel v41-trend-panel">${panelHead('Weekly Trend','Compare your own pace and the significance of completed work.','recognition_pace_increased')}<div class="v41-chart-controls"><div class="segmented">${[['completed','Completed'],['priority','Priority points'],['importance','Importance'],['urgency','Urgency'],['type','Type']].map(([k,l])=>`<button class="${metric===k?'active':''}" data-v41-chart-metric="${k}">${l}</button>`).join('')}</div><div class="v41-chart-options"><select data-v41-review-area><option>All</option>${AREAS.map(a=>`<option ${area===a?'selected':''}>${a}</option>`).join('')}</select><select data-v41-chart-weeks><option value="4" ${weeks===4?'selected':''}>4 weeks</option><option value="8" ${weeks===8?'selected':''}>8 weeks</option><option value="12" ${weeks===12?'selected':''}>12 weeks</option></select></div></div><div class="v41-chart" role="img" aria-label="${esc(metric)} weekly trend">${series.map((row,i)=>{const val=v41ChartValue(row,metric),height=Math.max(val?8:2,Math.round(val/max*100));return `<button class="v41-bar-wrap" data-v41-chart-week="${row.start}|${row.end}"><div class="v41-bar" style="height:${height}%">${stacked?stacked.map(key=>{const count=(metric==='importance'?row.importance:metric==='urgency'?row.urgency:row.type)[key]||0,pct=row.total?Math.round(count/row.total*100):0;return `<span style="height:${pct}%;background:${V41_CHART_COLORS[key]||'#557'}" title="${key}: ${count}"></span>`}).join(''):`<span style="height:100%"></span>`}</div><b>${val}</b><small>${fmtDate(row.start)}</small></button>`}).join('')}</div>${stacked?`<div class="v41-chart-legend">${stacked.map(k=>`<span><i style="background:${V41_CHART_COLORS[k]||'#557'}"></i>${k}</span>`).join('')}</div>`:''}<details class="v41-chart-table"><summary>View accessible table</summary><table><thead><tr><th>Week</th><th>Completed</th><th>Priority points</th></tr></thead><tbody>${series.map(r=>`<tr><td>${esc(r.label)}</td><td>${r.total}</td><td>${r.priority}</td></tr>`).join('')}</tbody></table></details></section>`}
function v41ReviewAreas(){const m=v39ReviewMetrics(),big=v39BigMoves(m),strong=m.summaries.filter(s=>['Strong Momentum','Maintaining'].includes(s.status)),needs=m.summaries.filter(s=>['Needs Proactive Focus','Dormant'].includes(s.status)),biggest=big[0];return `<div class="stack v41-review"><section class="v41-review-hero"><div><span class="eyebrow">YOUR ${m.range==='week'?'WEEK':'MONTH'} IN MOTION</span><h2>${esc(m.b.label)}</h2><p>${m.current.length} Tasks closed · ${m.important.length} important moves · ${m.recovered.length} recoveries · ${m.habitMet.length} Habit targets</p><strong>${m.pace>=0?'+':''}${m.pace} vs previous ${m.range}</strong></div><img src="${A[biggest?'recognition_big_move':'recognition_balanced']}" alt=""></section>${biggest?`<section class="panel v41-biggest-move">${panelHead('Biggest Move','Meaningful progress appears before game rewards.','recognition_big_move')}<article><img src="${A.recognition_big_move}" alt=""><div><strong>${esc(biggest.title)}</strong><small>${esc(taskCategory(biggest))} · R${v35PriorityRank(biggest)}</small></div><button class="button tiny ghost" data-open-task="${biggest.id}">Open</button></article></section>`:''}${v41TrendChart()}<section class="panel">${panelHead('Strong Momentum','Life areas with important movement, healthy Habits, or active Projects and Explorations.','recognition_area_flourishing')}<div class="v39-area-grid-review">${strong.length?strong.map(v39AreaReviewCard).join(''):'<div class="empty compact">Momentum is still building.</div>'}</div></section>${m.recovered.length?`<section class="panel">${panelHead('Recovery Wins','Delayed commitments that finally moved deserve explicit recognition.','recognition_recovery_hero')}<div class="v39-recovery-list">${m.recovered.slice(0,6).map(t=>`<article><img src="${A.recognition_recovery_hero}" alt=""><div><strong>${esc(t.title)}</strong><small>Completed after ${v41DateMoveCount(t)} replan${v41DateMoveCount(t)===1?'':'s'} · originally ${fmtDate(v41TaskOriginalDate(t))}</small></div></article>`).join('')}</div></section>`:''}<section class="panel">${panelHead('Needs Proactive Focus','Important records without dates, progress, or a clear Next Move.','area_status_needs_focus')}<div class="v39-area-grid-review">${needs.length?needs.map(v39AreaReviewCard).join(''):'<div class="empty compact">No life area currently needs proactive focus.</div>'}</div></section><section class="panel">${panelHead('All Life Areas','Attention Footprint shows evidence of movement without claiming untracked time.','scene_realm')}<div class="v39-area-grid-review compact">${m.summaries.map(v39AreaReviewCard).join('')}</div></section></div>`}
renderReview=function(){const tab=state.ui.reviewTab||'areas';root.innerHTML=`${hero({title:'Review',subtitle:'Celebrate meaningful movement, compare your pace, and identify life areas that need deliberate attention.',scene:'scene_campfire',meta:[['Period',v39PeriodBounds().label],['Version',VERSION]]})}<div class="toolbar review-toolbar"><div class="segmented"><button class="${state.ui.reviewRange==='week'?'active':''}" data-review-range="week">This Week</button><button class="${state.ui.reviewRange==='month'?'active':''}" data-review-range="month">This Month</button></div></div><div class="tab-strip compact-tabs review-tabs">${[['areas','Areas'],['progress','Progress'],['history','History'],['victories','Victories']].map(([k,l])=>`<button class="tab-button ${tab===k?'active':''}" data-v36-review-tab="${k}">${l}</button>`).join('')}</div>${tab==='areas'?v41ReviewAreas():tab==='progress'?`<div class="stack">${v41TrendChart()}${v39ReviewProgress()}</div>`:tab==='history'?v39BaseRenderHistory():v39BaseRenderVictories()}`}

