sortActivities=function(list,date){return[...list].sort((a,b)=>{
  const ar=v35ActivityRank(a,date),br=v35ActivityRank(b,date);if(ar!==br)return br-ar;
  const ao=a.kind==='task'&&taskDerivedState(a.task)==='Overdue',bo=b.kind==='task'&&taskDerivedState(b.task)==='Overdue';if(ao!==bo)return ao?-1:1;
  const ad=String(a.dueDate||effectivePlanDate(a.task||{})||'9999'),bd=String(b.dueDate||effectivePlanDate(b.task||{})||'9999');if(ad!==bd)return ad.localeCompare(bd);
  if(a.topPriority!==b.topPriority)return a.topPriority?-1:1;
  const ap=a.task?.plannedOrder||a.occurrence?.order||99,bp=b.task?.plannedOrder||b.occurrence?.order||99;return ap-bp
})};

v41ResolveTasks=function(){
  const list=openTasks().filter(t=>taskCategory(t)==='Resolve').sort((a,b)=>v35PriorityRank(b)-v35PriorityRank(a)||String(effectivePlanDate(a)||'9999').localeCompare(String(effectivePlanDate(b)||'9999')));
  const stages={'Do Now':[],'Schedule':[],'Waiting':[],'Follow Up':[],'Needs Definition':[]};
  for(const t of list){
    if(t.waitingOn)stages['Waiting'].push(t);
    else if(t.followUpDate)stages['Follow Up'].push(t);
    else if(!effectivePlanDate(t)&&!String(t.notes||'').trim())stages['Needs Definition'].push(t);
    else if(!effectivePlanDate(t))stages['Schedule'].push(t);
    else stages['Do Now'].push(t)
  }
  return `<section class="panel">${panelHead('Resolve','Simple standalone obligations, ranked and ready to plan.','mode_resolve')}${v33InlineTaskForm({standaloneType:'Resolve',placeholder:'Add a Resolve Task…'})}<div class="resolve-lanes">${Object.entries(stages).map(([name,items])=>`<section class="lane"><h3>${name}<span>${items.length}</span></h3><div class="activity-list">${items.length?items.map(t=>activityRow(taskActivity(t),{compact:true})).join(''):'<div class="empty compact">None</div>'}</div></section>`).join('')}</div></section>`
};

function v41ToggleHabitActivity(hid,oid){
  const h=habitById(hid),o=h?.occurrences?.find(x=>x.id===oid);if(!h||!o)return;
  if(o.completedAt){
    v36RemoveHabitEntry(h,o);o.completedAt=null;o.completedDate=null;o.extra=false;h.updatedAt=nowStamp();v38SyncHabitPeriod(h,o.date);save();toast(`${h.title}: completion removed`,'occurrence_planned');render();return
  }
  const actual=todayISO();o.completedAt=nowStamp();o.completedDate=actual;o.skippedAt=null;o.notRequiredAt=null;
  h.entries[actual]=Number(h.entries?.[actual]||0)+1;h.updatedAt=nowStamp();v38SyncHabitPeriod(h,actual);save();toast(`${h.title}: completed`,'occurrence_completed');render()
}
function v41SkipHabitActivity(hid,oid){
  const h=habitById(hid),o=h?.occurrences?.find(x=>x.id===oid);if(!h||!o)return;
  if(o.completedAt)v36RemoveHabitEntry(h,o);o.completedAt=null;o.completedDate=null;o.skippedAt=nowStamp();o.notRequiredAt=null;h.updatedAt=nowStamp();v38SyncHabitPeriod(h,o.date);save();toast(`${h.title}: opportunity skipped`,'occurrence_skipped');render()
}

