const v41BaseMoveHabitOccurrence=v41MoveHabitOccurrence;
v41MoveHabitOccurrence=function(hid,oid,date,scope='one'){
  const returnMode=state.ui.v41HabitDateReturn||'cycle';state.ui.v41HabitDateReturn=null;
  const h=habitById(hid),o=h?.occurrences?.find(x=>x.id===oid);if(!h||!o||!date)return;
  const old=o.date;o.originalDate=o.originalDate||old;o.date=date;o.periodKey=periodBounds(h,date).key;o.moveCount=Number(o.moveCount||0)+1;o.systemGenerated=false;
  if(scope==='future'){
    if(h.period==='week'){const oldDay=new Date(`${old}T12:00:00`).getDay(),newDay=new Date(`${date}T12:00:00`).getDay();h.preferredWeekdays=(h.preferredWeekdays||[]).map(d=>d===oldDay?newDay:d)}
    else if(h.period==='month'){h.recurrenceMode='fixedDay';h.preferredMonthDay=new Date(`${date}T12:00:00`).getDate()}
    v39RegenerateFuture(h,date)
  }
  v38DedupeHabitOccurrences(h);h.updatedAt=nowStamp();save();v41CloseSubsheet();toast(`Moved to ${fmtDate(date)}`,'action_move');
  if(returnMode==='view'){render()}else v41OpenHabitCycle(hid,state.ui.habitReviewDate||date,'plan')
};

function v41PlanRemainingHabit(hid){
  const h=habitById(hid);if(!h)return;const anchor=state.ui.habitReviewDate||todayISO(),s=v41HabitStats(h,anchor),b=periodBounds(h,anchor);let date=todayISO()<b.start?b.start:todayISO();let created=0;
  for(let i=0;i<Math.max(0,s.needed-s.planned.length)&&date<=b.end;i++){
    while(date<=b.end&&(h.occurrences||[]).some(o=>o.periodKey===b.key&&o.date===date&&!o.completedAt&&!o.skippedAt&&!o.notRequiredAt))date=addDays(date,1);
    if(date>b.end)break;v39PlanDay(h.id,date);created++;date=addDays(date,1)
  }
  save();toast(created?`${created} opportunit${created===1?'y':'ies'} planned`:'No additional opportunity was needed','action_plan_remaining');v41OpenHabitCycle(h.id,anchor,'plan')
}

