function v42TaskTabs(){const counts=v42TaskCounts();return `<div class="tab-strip v42-task-tabs">${['Resolve','Project','Exploration','Renew/Fun','All','Priority'].map(x=>`<button class="tab-button ${state.ui.tasksTab===x?'active':''}" data-tasks-tab="${x}"><span>${x}</span><b>${counts[x]||0}</b></button>`).join('')}</div>`}
