  const icon=tab==='Resolve'?'mode_resolve':tab==='Project'?'object_goal':tab==='Exploration'?'object_discovery':tab==='Renew/Fun'?'mode_renew':'object_action';
  const subtitle=tab==='Resolve'?'Standalone obligations that can be completed or scheduled directly.':tab==='Project'?'Concrete steps advancing defined outcomes.':tab==='Exploration'?'Research and decision Tasks that reduce uncertainty.':tab==='Renew/Fun'?'Intentional restoration, connection, and enjoyment.':'All open Tasks across their current destinations.';
  let body='';
  if(tab==='Resolve')body=v42ResolveLanes(list);
  else if(tab==='Project')body=v42GroupedQuestTasks(list,'outcome');
  else if(tab==='Exploration')body=v42GroupedQuestTasks(list,'exploration');
